export const HEVY_EXERCISES: HevyExercise[] = [{"name":"21s Bicep Curl","description":"Combines seven bottom-half reps, seven top-half reps, and seven full curls to keep the biceps under continuous tension. The extended time under tension builds biceps size and improves control through the entire curling range.","descriptionAr":"يجمع بين سبعة تكرارات في النصف السفلي وسبعة في النصف العلوي وسبعة تكرارات كاملة لإبقاء العضلة ذات الرأسين تحت توتر مستمر. يزيد هذا التوتر المطول من حجم العضلة ذات الرأسين ويحسن التحكم في كامل مدى الثني.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"biceps","percentage":80},{"bodyTarget":"forearms","percentage":20}]},{"name":"Ab Scissors","description":"Targets the lower abdominals and hip flexors by crossing straight legs over each other while lying on your back. Keeping the lower back pressed into the floor builds core control and hip strength.","descriptionAr":"يستهدف عضلات البطن السفلية وعضلات مثنيات الورك عبر تقاطع الساقين الممدودتين بالتناوب أثناء الاستلقاء على الظهر. يؤدي إبقاء أسفل الظهر ملتصقا بالأرض إلى تعزيز التحكم في الجذع وقوة الوركين.","measurement":"reps","types":["Core"],"targets":[{"bodyTarget":"core_abs","percentage":60},{"bodyTarget":"hip_flexors","percentage":30},{"bodyTarget":"core_deep","percentage":10}]},{"name":"Ab Wheel","description":"Rolling the wheel forward from a kneeling position forces the abdominals and deep core to resist spinal extension, with the lats assisting the return. It is one of the most demanding movements for building total core strength and stability.","descriptionAr":"يجبر دحرجة العجلة إلى الأمام من وضعية الركوع عضلات البطن والعضلات العميقة للجذع على مقاومة تقوس العمود الفقري، بمساعدة العضلة الظهرية العريضة في العودة. وهو من أكثر التمارين فاعلية لبناء قوة الجذع وثباته.","measurement":"reps","types":["Core"],"targets":[{"bodyTarget":"core_abs","percentage":55},{"bodyTarget":"core_deep","percentage":20},{"bodyTarget":"lats","percentage":15},{"bodyTarget":"obliques","percentage":10}]},{"name":"Aerobics","description":"Rhythmic, continuous full-body movement performed to a steady tempo that elevates the heart rate. Regular sessions improve cardiovascular fitness, coordination, and general endurance.","descriptionAr":"حركة إيقاعية متواصلة لكامل الجسم تؤدى على وتيرة ثابتة ترفع معدل ضربات القلب. تحسن الجلسات المنتظمة اللياقة القلبية الوعائية والتناسق الحركي والتحمل العام.","measurement":"distance_duration","types":["Cardio"],"targets":[{"bodyTarget":"cardiovascular","percentage":70},{"bodyTarget":"endurance","percentage":30}]},{"name":"Air Bike","description":"The fan bike works arms and legs together against air resistance, so effort scales with how hard you push. It is ideal for high-intensity intervals and builds powerful whole-body conditioning.","descriptionAr":"تعمل الدراجة الهوائية ذات المروحة على الذراعين والساقين معا ضد مقاومة الهواء، بحيث تزداد المقاومة كلما زاد الجهد. وهي مثالية للتدريب المتقطع عالي الشدة وتبني لياقة قوية لكامل الجسم.","measurement":"distance_duration","types":["Cardio","HIIT"],"targets":[{"bodyTarget":"cardiovascular","percentage":60},{"bodyTarget":"endurance","percentage":25},{"bodyTarget":"quadriceps","percentage":15}]},{"name":"Arnold Press (Dumbbell)","description":"A dumbbell press that starts palms-facing-you and rotates outward on the way up, working the front and side heads of the deltoid through a long range. The rotation increases time under tension and builds well-rounded shoulder size.","descriptionAr":"ضغط بالدمبل يبدأ وراحتا اليدين متجهتان نحوك ثم تدوران للخارج أثناء الصعود، فيعمل على الرأسين الأمامي والجانبي للعضلة الدالية عبر مدى حركة طويل. يزيد الدوران من زمن التوتر ويبني كتفين متوازنتين.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"shoulders_anterior","percentage":55},{"bodyTarget":"shoulders_lateral","percentage":25},{"bodyTarget":"triceps","percentage":20}]},{"name":"Around The World","description":"Lying on a bench, light dumbbells travel in a wide arc from the hips around to overhead, keeping the chest under constant tension. The sweeping path stretches and strengthens the pecs while the shoulders stabilize throughout.","descriptionAr":"أثناء الاستلقاء على المقعد، يحرك المتدرب دمبلين خفيفين في قوس واسع من جانبي الوركين حتى فوق الرأس، مع إبقاء الصدر تحت توتر مستمر. يعمل هذا المسار الدائري على إطالة عضلات الصدر وتقويتها بينما تعمل الكتفان على التثبيت.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"chest","percentage":70},{"bodyTarget":"shoulders_anterior","percentage":20},{"bodyTarget":"biceps","percentage":10}]},{"name":"Assisted Pistol Squats","description":"A single-leg squat performed while holding a support such as a band, strap, or post, letting you descend fully on one leg. It builds unilateral quad and glute strength along with the balance needed for the free pistol squat.","descriptionAr":"قرفصاء على ساق واحدة تؤدى مع الإمساك بدعامة مثل حزام مطاطي أو عمود، مما يتيح النزول الكامل على ساق واحدة. يبني هذا التمرين قوة أحادية الجانب في الفخذ الأمامي والأليتين إضافة إلى التوازن اللازم لأداء القرفصاء الحرة على ساق واحدة.","measurement":"reps","types":["Leg Day","Lower Body","Calisthenics"],"targets":[{"bodyTarget":"quadriceps","percentage":55},{"bodyTarget":"glutes","percentage":25},{"bodyTarget":"hamstrings","percentage":10},{"bodyTarget":"balance","percentage":10}]},{"name":"Back Extension (Hyperextension)","description":"Hinging at the hips over a back-extension bench, you lower the torso and raise it back to neutral, loading the spinal erectors, glutes, and hamstrings. It strengthens the entire posterior chain and supports a healthy, resilient lower back.","descriptionAr":"بالانحناء من الوركين فوق مقعد تمديد الظهر، ينزل الجذع ثم يرفع إلى الوضع المستقيم، مما يحمل العضلات الناصبة للفقار والأليتين وأوتار الركبة. يقوي هذا التمرين السلسلة الخلفية كاملة ويدعم صحة أسفل الظهر ومتانته.","measurement":"reps","types":["Lower Body","Core"],"targets":[{"bodyTarget":"lower_back","percentage":35},{"bodyTarget":"erector_spinae","percentage":25},{"bodyTarget":"glutes","percentage":25},{"bodyTarget":"hamstrings","percentage":15}]},{"name":"Back Extension (Machine)","description":"Seated against a padded lever, you extend the torso backward against adjustable resistance, isolating the lower back and spinal erectors with support from the glutes. The machine allows precise, safe loading for building lower-back strength.","descriptionAr":"جالسا مستندا إلى ذراع مبطنة، يمد المتدرب جذعه إلى الخلف ضد مقاومة قابلة للتعديل، فيعزل أسفل الظهر والعضلات الناصبة للفقار بمساندة الأليتين. يتيح الجهاز تحميلا دقيقا وآمنا لبناء قوة أسفل الظهر.","measurement":"reps","types":["Lower Body","Core"],"targets":[{"bodyTarget":"lower_back","percentage":35},{"bodyTarget":"erector_spinae","percentage":25},{"bodyTarget":"glutes","percentage":25},{"bodyTarget":"hamstrings","percentage":15}]},{"name":"Back Extension (Weighted Hyperextension)","description":"The standard hyperextension performed while holding a plate or bar to the chest, adding resistance to the spinal erectors, glutes, and hamstrings. Progressive loading makes it a key builder of posterior-chain strength.","descriptionAr":"التمديد الخلفي التقليدي يؤدى مع حمل قرص أو بار على الصدر، مما يضيف مقاومة على العضلات الناصبة للفقار والأليتين وأوتار الركبة. يجعل التحميل التدريجي هذا التمرين أساسيا لبناء قوة السلسلة الخلفية.","measurement":"reps","types":["Lower Body","Core"],"targets":[{"bodyTarget":"lower_back","percentage":35},{"bodyTarget":"erector_spinae","percentage":25},{"bodyTarget":"glutes","percentage":25},{"bodyTarget":"hamstrings","percentage":15}]},{"name":"Ball Slams","description":"Lifting a medicine ball overhead and slamming it into the floor with full force trains explosive power through the core, lats, and shoulders. It doubles as intense conditioning and a safe outlet for maximal effort.","descriptionAr":"رفع كرة طبية فوق الرأس ثم ضربها بالأرض بكامل القوة يدرب القدرة الانفجارية في الجذع والعضلة الظهرية العريضة والكتفين. كما يشكل تمرين لياقة مكثفا ووسيلة آمنة لبذل أقصى جهد.","measurement":"reps","types":["Full Body","HIIT","Functional"],"targets":[{"bodyTarget":"core_abs","percentage":35},{"bodyTarget":"lats","percentage":30},{"bodyTarget":"shoulders_anterior","percentage":20},{"bodyTarget":"triceps","percentage":15}]},{"name":"Band Pullaparts","description":"Holding a resistance band at shoulder height with straight arms, you pull it apart until it touches the chest, squeezing the rear delts and upper back. High-rep pullaparts improve posture and shoulder health, especially for those who press often.","descriptionAr":"بإمساك حزام مقاومة عند مستوى الكتفين وذراعين ممدودتين، يشد المتدرب الحزام إلى الجانبين حتى يلامس الصدر، مع عصر العضلة الدالية الخلفية وأعلى الظهر. تحسن التكرارات العالية من هذا التمرين وضعية الجسم وصحة الكتفين، خصوصا لمن يكثرون من تمارين الضغط.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"shoulders_posterior","percentage":60},{"bodyTarget":"upper_back","percentage":25},{"bodyTarget":"traps","percentage":15}]},{"name":"Bear Crawl","description":"Crawling on hands and feet with knees hovering just off the ground forces the deep core to stabilize while shoulders and legs drive the movement. It builds total-body coordination, core stiffness, and shoulder endurance.","descriptionAr":"الزحف على اليدين والقدمين مع إبقاء الركبتين مرتفعتين قليلا عن الأرض يجبر عضلات الجذع العميقة على التثبيت بينما تقود الكتفان والساقان الحركة. يبني هذا التمرين التناسق الكلي للجسم وصلابة الجذع وتحمل الكتفين.","measurement":"reps","types":["Full Body","Functional","Calisthenics"],"targets":[{"bodyTarget":"core_abs","percentage":35},{"bodyTarget":"shoulders_anterior","percentage":25},{"bodyTarget":"quadriceps","percentage":20},{"bodyTarget":"core_deep","percentage":20}]},{"name":"Behind the Back Curl (Cable)","description":"With the cable running behind the body, the arm starts extended slightly back, placing the long head of the biceps under a deep stretch before each curl. Training the biceps from this lengthened position is highly effective for growth.","descriptionAr":"مع مرور الكابل خلف الجسم، تبدأ الذراع ممدودة إلى الخلف قليلا، مما يضع الرأس الطويل للعضلة ذات الرأسين تحت إطالة عميقة قبل كل ثنية. يعد تدريب العضلة من هذا الوضع الممدود فعالا جدا للنمو العضلي.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"biceps","percentage":80},{"bodyTarget":"forearms","percentage":20}]},{"name":"Behind the Back Wrist Curl (Barbell)","description":"Holding a barbell behind the body with palms facing back, you curl the wrists upward to work the forearm flexors through a strong contraction. It builds forearm size and grip strength with minimal stress on the wrists' front side.","descriptionAr":"بإمساك البار خلف الجسم وراحتا اليدين متجهتان إلى الخلف، يثني المتدرب معصميه إلى الأعلى لتشغيل عضلات الساعد القابضة بانقباض قوي. يبني هذا التمرين حجم الساعدين وقوة القبضة مع ضغط ضئيل على الجهة الأمامية للمعصمين.","measurement":"reps","types":["Upper Body"],"targets":[{"bodyTarget":"forearms","percentage":90},{"bodyTarget":"biceps","percentage":10}]},{"name":"Belt Squat (Machine)","description":"The load hangs from a belt around the hips, letting you squat heavy without compressing the spine. It targets the quads and glutes hard and is valuable when training around back or shoulder limitations.","descriptionAr":"يتدلى الوزن من حزام حول الوركين، مما يتيح أداء قرفصاء ثقيلة دون ضغط على العمود الفقري. يستهدف هذا التمرين الفخذين الأماميين والأليتين بقوة، وهو مفيد عند التدريب مع وجود قيود في الظهر أو الكتفين.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"quadriceps","percentage":60},{"bodyTarget":"glutes","percentage":25},{"bodyTarget":"hamstrings","percentage":10},{"bodyTarget":"adductors","percentage":5}]},{"name":"Bench Press - Close Grip (Barbell)","description":"Narrowing the grip to about shoulder width shifts the pressing workload onto the triceps while the chest and front delts assist. It is one of the best heavy compound movements for building triceps size and lockout strength.","descriptionAr":"تضييق القبضة إلى ما يقارب عرض الكتفين ينقل عبء الدفع إلى العضلة ثلاثية الرؤوس بينما يساند الصدر ومقدمة الكتفين. وهو من أفضل التمارين المركبة الثقيلة لبناء حجم العضلة ثلاثية الرؤوس وقوة فرد الذراعين.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"triceps","percentage":55},{"bodyTarget":"chest","percentage":30},{"bodyTarget":"shoulders_anterior","percentage":15}]},{"name":"Bench Press - Wide Grip (Barbell)","description":"A wider-than-shoulder grip shortens the bar path and increases the demand on the chest, especially its outer fibers. It emphasizes pec strength and mass while reducing the triceps' contribution.","descriptionAr":"قبضة أوسع من الكتفين تقصر مسار البار وتزيد العبء على عضلات الصدر، وخاصة أليافها الخارجية. يركز هذا التمرين على قوة الصدر وكتلته مع تقليل مساهمة العضلة ثلاثية الرؤوس.","measurement":"reps","types":["Push Day","Upper Body","Powerlifting"],"targets":[{"bodyTarget":"chest","percentage":65},{"bodyTarget":"shoulders_anterior","percentage":20},{"bodyTarget":"triceps","percentage":15}]},{"name":"Bench Press (Barbell)","description":"The classic barbell press from the chest while lying on a bench, driving the bar to lockout with chest, triceps, and front delts. It is the primary builder of horizontal pressing strength and upper-body mass.","descriptionAr":"الضغط التقليدي بالبار من على الصدر أثناء الاستلقاء على المقعد، بدفع البار حتى فرد الذراعين بمشاركة الصدر والعضلة ثلاثية الرؤوس ومقدمة الكتفين. وهو التمرين الأساسي لبناء قوة الدفع الأفقي وكتلة الجزء العلوي من الجسم.","measurement":"reps","types":["Push Day","Upper Body","Powerlifting"],"targets":[{"bodyTarget":"chest","percentage":60},{"bodyTarget":"triceps","percentage":25},{"bodyTarget":"shoulders_anterior","percentage":15}]},{"name":"Bench Press (Cable)","description":"Pressing cable handles from chest level while lying on a bench keeps tension on the pecs through the entire range, including lockout. The constant resistance makes it excellent for chest hypertrophy with less shoulder strain.","descriptionAr":"دفع مقبضي الكابل من مستوى الصدر أثناء الاستلقاء على المقعد يحافظ على توتر عضلات الصدر عبر كامل مدى الحركة حتى فرد الذراعين. تجعل المقاومة المستمرة هذا التمرين ممتازا لتضخيم الصدر مع إجهاد أقل للكتفين.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"chest","percentage":60},{"bodyTarget":"triceps","percentage":25},{"bodyTarget":"shoulders_anterior","percentage":15}]},{"name":"Bench Press (Dumbbell)","description":"Pressing a dumbbell in each hand allows a deeper stretch and a longer range of motion than the barbell, while demanding more stabilizer work. It builds chest, triceps, and front-delt strength and helps correct side-to-side imbalances.","descriptionAr":"الضغط بدمبل في كل يد يتيح إطالة أعمق ومدى حركة أطول من البار، مع مطالبة العضلات المثبتة بعمل أكبر. يبني قوة الصدر والعضلة ثلاثية الرؤوس ومقدمة الكتفين ويساعد على تصحيح الفروق بين الجانبين.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"chest","percentage":60},{"bodyTarget":"triceps","percentage":25},{"bodyTarget":"shoulders_anterior","percentage":15}]},{"name":"Bench Press (Smith Machine)","description":"The fixed bar path of the Smith machine removes the need to balance the load, letting you focus purely on pressing with the chest, triceps, and front delts. It is useful for controlled overload and training close to failure without a spotter.","descriptionAr":"يلغي المسار الثابت لبار جهاز سميث الحاجة إلى موازنة الوزن، مما يتيح التركيز الكامل على الدفع بعضلات الصدر والعضلة ثلاثية الرؤوس ومقدمة الكتفين. وهو مفيد لزيادة الحمل بشكل منضبط والتدريب قرب الإجهاد الكامل دون مساعد.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"chest","percentage":60},{"bodyTarget":"triceps","percentage":25},{"bodyTarget":"shoulders_anterior","percentage":15}]},{"name":"Bent Over Row (Band)","description":"Hinged at the hips while standing on a resistance band, you row the handles to the torso, working the upper back, lats, and biceps. Band tension increases toward the top, rewarding a strong squeeze at the finish.","descriptionAr":"بالانحناء من الوركين مع الوقوف على حزام مقاومة، يسحب المتدرب المقبضين نحو الجذع، فيعمل على أعلى الظهر والعضلة الظهرية العريضة والعضلة ذات الرأسين. تزداد مقاومة الحزام قرب نهاية الحركة، مما يكافئ العصر القوي عند الانتهاء.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"upper_back","percentage":45},{"bodyTarget":"lats","percentage":25},{"bodyTarget":"biceps","percentage":20},{"bodyTarget":"shoulders_posterior","percentage":10}]},{"name":"Bent Over Row (Barbell)","description":"From a hip hinge, the barbell is pulled to the lower ribs, building thickness through the upper back and lats with strong biceps involvement. It is a foundational heavy pull that also challenges the lower back isometrically.","descriptionAr":"من وضعية الانحناء من الوركين، يسحب البار نحو الأضلاع السفلية، فيبني سماكة أعلى الظهر والعضلة الظهرية العريضة مع مشاركة قوية للعضلة ذات الرأسين. وهو تمرين سحب ثقيل أساسي يتحدى أسفل الظهر بانقباض ثابت أيضا.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"upper_back","percentage":45},{"bodyTarget":"lats","percentage":25},{"bodyTarget":"biceps","percentage":20},{"bodyTarget":"shoulders_posterior","percentage":10}]},{"name":"Bent Over Row (Dumbbell)","description":"Rowing dumbbells from a bent-over position lets each arm move through its natural path and a fuller range than a barbell allows. It develops the upper back, lats, and biceps while exposing and correcting side-to-side strength gaps.","descriptionAr":"سحب الدمبلين من وضعية الانحناء يتيح لكل ذراع التحرك في مسارها الطبيعي وبمدى أكمل مما يسمح به البار. يطور هذا التمرين أعلى الظهر والعضلة الظهرية العريضة والعضلة ذات الرأسين ويكشف فروق القوة بين الجانبين ويصححها.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"upper_back","percentage":45},{"bodyTarget":"lats","percentage":25},{"bodyTarget":"biceps","percentage":20},{"bodyTarget":"shoulders_posterior","percentage":10}]},{"name":"Bent Over Row (Smith Machine)","description":"The guided bar of the Smith machine stabilizes the rowing path, letting you load the upper back and lats without balancing a free bar. It suits controlled, strict rowing and progressive overload for back thickness.","descriptionAr":"يثبت البار الموجه في جهاز سميث مسار السحب، مما يتيح تحميل أعلى الظهر والعضلة الظهرية العريضة دون الحاجة إلى موازنة بار حر. يناسب هذا التمرين السحب الصارم المنضبط وزيادة الأحمال التدريجية لبناء سماكة الظهر.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"upper_back","percentage":45},{"bodyTarget":"lats","percentage":25},{"bodyTarget":"biceps","percentage":20},{"bodyTarget":"shoulders_posterior","percentage":10}]},{"name":"Bicep Curl (Barbell)","description":"Curling a barbell with both hands allows the heaviest loading of any curl variation, driving growth in the biceps with forearm assistance. Strict form with elbows pinned at the sides keeps the tension where it belongs.","descriptionAr":"ثني البار بكلتا اليدين يتيح أثقل حمل بين جميع أنواع تمارين الثني، مما يعزز نمو العضلة ذات الرأسين بمساندة الساعدين. يحافظ الأداء الصارم مع تثبيت المرفقين إلى الجانبين على التوتر في مكانه الصحيح.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"biceps","percentage":80},{"bodyTarget":"forearms","percentage":20}]},{"name":"Bicep Curl (Cable)","description":"The cable keeps resistance on the biceps through the entire curl, including the bottom position where free weights lose tension. This constant load makes it a highly efficient choice for biceps hypertrophy.","descriptionAr":"يحافظ الكابل على المقاومة على العضلة ذات الرأسين طوال حركة الثني، بما فيها الوضع السفلي حيث تفقد الأوزان الحرة توترها. يجعل هذا الحمل المستمر التمرين خيارا عالي الكفاءة لتضخيم العضلة ذات الرأسين.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"biceps","percentage":80},{"bodyTarget":"forearms","percentage":20}]},{"name":"Bicep Curl (Dumbbell)","description":"Curling dumbbells lets the wrists rotate naturally and each arm work independently, fully engaging the biceps with forearm support. It is a staple movement for building arm size and balanced strength.","descriptionAr":"ثني الدمبلين يتيح للمعصمين الدوران بشكل طبيعي ولكل ذراع العمل باستقلالية، مع تفعيل كامل للعضلة ذات الرأسين بمساندة الساعد. وهو تمرين أساسي لبناء حجم الذراعين وقوة متوازنة.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"biceps","percentage":80},{"bodyTarget":"forearms","percentage":20}]},{"name":"Bicep Curl (Machine)","description":"With the upper arms fixed against a pad, the machine isolates the biceps and removes momentum from the movement. It is ideal for strict high-rep work and for safely training the biceps to failure.","descriptionAr":"مع تثبيت العضدين على وسادة، يعزل الجهاز العضلة ذات الرأسين ويزيل الزخم من الحركة. وهو مثالي للتكرارات العالية الصارمة ولتدريب العضلة ذات الرأسين حتى الإجهاد الكامل بأمان.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"biceps","percentage":80},{"bodyTarget":"forearms","percentage":20}]},{"name":"Bicep Curl (Suspension)","description":"Leaning back while holding suspension straps, you curl your bodyweight up by flexing the elbows, keeping the body rigid throughout. Adjusting foot position changes the difficulty, making it a scalable bodyweight biceps builder.","descriptionAr":"بالميل إلى الخلف أثناء الإمساك بأحزمة التعليق، يرفع المتدرب وزن جسمه بثني المرفقين مع إبقاء الجسم مشدودا طوال الحركة. يغير تعديل موضع القدمين مستوى الصعوبة، مما يجعله تمرينا متدرجا لبناء العضلة ذات الرأسين بوزن الجسم.","measurement":"reps","types":["Pull Day","Upper Body","Calisthenics"],"targets":[{"bodyTarget":"biceps","percentage":80},{"bodyTarget":"forearms","percentage":20}]},{"name":"Bicycle Crunch Raised Legs","description":"With legs raised off the floor, you alternate driving each elbow toward the opposite knee in a pedaling motion. The combination of trunk flexion and rotation works the abs and obliques while the raised legs keep the hip flexors engaged.","descriptionAr":"مع رفع الساقين عن الأرض، يوجه المتدرب كل مرفق بالتناوب نحو الركبة المقابلة بحركة تشبه التبديل. يعمل الجمع بين ثني الجذع ودورانه على عضلات البطن والعضلات المائلة، بينما يبقي رفع الساقين مثنيات الورك في حالة عمل.","measurement":"reps","types":["Core"],"targets":[{"bodyTarget":"core_abs","percentage":50},{"bodyTarget":"obliques","percentage":30},{"bodyTarget":"hip_flexors","percentage":20}]},{"name":"Bird Dog","description":"From all fours, you extend the opposite arm and leg while keeping the hips and spine perfectly still. It trains glute activation and deep core stability, making it a staple for lower-back health.","descriptionAr":"من وضعية الارتكاز على اليدين والركبتين، يمد المتدرب الذراع والساق المتقابلتين مع إبقاء الوركين والعمود الفقري ثابتين تماما. يدرب هذا التمرين تفعيل الأليتين وثبات الجذع العميق، مما يجعله أساسيا لصحة أسفل الظهر.","measurement":"reps","types":["Core","Functional"],"targets":[{"bodyTarget":"glutes","percentage":40},{"bodyTarget":"core_deep","percentage":25},{"bodyTarget":"erector_spinae","percentage":20},{"bodyTarget":"core_abs","percentage":15}]},{"name":"Box Squat (Barbell)","description":"Squatting back onto a box enforces a consistent depth and a strong hip hinge, briefly pausing before driving up through the quads and glutes. The pause removes the stretch reflex, building raw starting strength out of the bottom.","descriptionAr":"القرفصاء بالجلوس إلى الخلف على صندوق تفرض عمقا ثابتا وانحناء قويا من الوركين، مع توقف قصير قبل الدفع للأعلى بالفخذين الأماميين والأليتين. يلغي التوقف منعكس الإطالة، مما يبني قوة انطلاق خام من الوضع السفلي.","measurement":"reps","types":["Leg Day","Lower Body","Powerlifting"],"targets":[{"bodyTarget":"quadriceps","percentage":50},{"bodyTarget":"glutes","percentage":30},{"bodyTarget":"hamstrings","percentage":20}]},{"name":"Boxing","description":"Rounds of punching combinations and footwork keep the heart rate high while the shoulders, arms, and core generate and absorb force. It develops cardiovascular conditioning, coordination, and rotational power.","descriptionAr":"تحافظ جولات من تركيبات اللكم وحركة القدمين على معدل ضربات قلب مرتفع بينما تولد الكتفان والذراعان والجذع القوة وتمتصها. يطور هذا التمرين اللياقة القلبية الوعائية والتناسق الحركي والقدرة الدورانية.","measurement":"distance_duration","types":["Cardio","HIIT"],"targets":[{"bodyTarget":"cardiovascular","percentage":60},{"bodyTarget":"endurance","percentage":25},{"bodyTarget":"shoulders_anterior","percentage":15}]},{"name":"Bulgarian Split Squat (Barbell)","description":"With the rear foot elevated on a bench and a barbell across the back, you squat on the front leg, heavily loading the quad and glute. It is one of the most effective single-leg strength builders and exposes imbalances between legs.","descriptionAr":"مع رفع القدم الخلفية على مقعد ووضع البار على أعلى الظهر، يؤدي المتدرب القرفصاء على الساق الأمامية، محملا الفخذ الأمامي والألية بشدة. وهو من أكثر التمارين فاعلية لبناء قوة الساق الواحدة ويكشف الفروق بين الساقين.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"quadriceps","percentage":50},{"bodyTarget":"glutes","percentage":30},{"bodyTarget":"hamstrings","percentage":12},{"bodyTarget":"adductors","percentage":8}]},{"name":"Bulgarian Split Squat (Dumbbell)","description":"Holding dumbbells at the sides with the rear foot elevated, you squat on the front leg through a deep range of motion. It builds quad and glute strength on each leg independently while training balance and hip stability.","descriptionAr":"بحمل دمبلين إلى الجانبين مع رفع القدم الخلفية، يؤدي المتدرب القرفصاء على الساق الأمامية عبر مدى حركة عميق. يبني هذا التمرين قوة الفخذ الأمامي والألية لكل ساق على حدة مع تدريب التوازن وثبات الورك.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"quadriceps","percentage":50},{"bodyTarget":"glutes","percentage":30},{"bodyTarget":"hamstrings","percentage":12},{"bodyTarget":"adductors","percentage":8}]},{"name":"Burpee Broad Jumps","description":"Each rep combines a full burpee with an explosive broad jump forward, taxing the legs, chest, and core in one continuous effort. It builds explosive power and severe conditioning in minimal space.","descriptionAr":"يجمع كل تكرار بين بيربي كامل وقفزة عريضة انفجارية إلى الأمام، مجهدا الساقين والصدر والجذع في جهد متواصل واحد. يبني هذا التمرين قدرة انفجارية ولياقة قاسية في مساحة صغيرة.","measurement":"reps","types":["Full Body","HIIT","CrossFit / WOD"],"targets":[{"bodyTarget":"quadriceps","percentage":35},{"bodyTarget":"glutes","percentage":25},{"bodyTarget":"chest","percentage":20},{"bodyTarget":"core_abs","percentage":20}]},{"name":"Burpee Over the Bar","description":"After each burpee you jump laterally or forward over a barbell before dropping into the next rep. Common in competitive fitness, it combines full-body conditioning with repeated explosive jumps under fatigue.","descriptionAr":"بعد كل بيربي يقفز المتدرب جانبيا أو أماميا فوق البار قبل النزول إلى التكرار التالي. يشيع هذا التمرين في منافسات اللياقة، وهو يجمع بين تكييف الجسم بالكامل وقفزات انفجارية متكررة تحت الإرهاق.","measurement":"reps","types":["Full Body","HIIT","CrossFit / WOD"],"targets":[{"bodyTarget":"quadriceps","percentage":35},{"bodyTarget":"glutes","percentage":25},{"bodyTarget":"chest","percentage":20},{"bodyTarget":"core_abs","percentage":20}]},{"name":"Butterfly (Pec Deck)","description":"Seated with forearms or hands on the pads, you squeeze the arms together in front of the chest, isolating the pecs through a fixed arc. The machine removes balance demands, making it excellent for a strong peak contraction and chest hypertrophy.","descriptionAr":"جالسا واضعا الساعدين أو اليدين على الوسادتين، يضم المتدرب ذراعيه أمام صدره، فيعزل عضلات الصدر عبر قوس ثابت. يزيل الجهاز متطلبات التوازن، مما يجعله ممتازا لانقباض ذروي قوي وتضخيم الصدر.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"chest","percentage":80},{"bodyTarget":"shoulders_anterior","percentage":20}]},{"name":"Cable Core Pallof Press","description":"Standing side-on to a cable, you press the handle straight out and resist the pull twisting you toward the machine. This anti-rotation work builds deep core and oblique strength that transfers directly to lifting and sport.","descriptionAr":"واقفا بجانبه إلى جهاز الكابل، يدفع المتدرب المقبض أمامه مباشرة ويقاوم قوة الشد التي تحاول تدويره نحو الجهاز. يبني هذا العمل المقاوم للدوران قوة عميقة في الجذع والعضلات المائلة تنتقل مباشرة إلى رفع الأثقال والرياضة.","measurement":"reps","types":["Core","Functional"],"targets":[{"bodyTarget":"core_abs","percentage":40},{"bodyTarget":"obliques","percentage":35},{"bodyTarget":"core_deep","percentage":25}]},{"name":"Cable Fly Crossovers","description":"From high pulleys, the handles sweep down and across the body until the hands cross, taking the pecs through a long arc under constant cable tension. The crossover finish emphasizes the inner chest and delivers an intense peak contraction.","descriptionAr":"من بكرتين مرتفعتين، ينزل المقبضان في قوس عبر الجسم حتى تتقاطع اليدان، مما يأخذ عضلات الصدر عبر قوس طويل تحت توتر كابل مستمر. تركز نهاية التقاطع على الجزء الداخلي من الصدر وتمنح انقباضا ذرويا مكثفا.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"chest","percentage":80},{"bodyTarget":"shoulders_anterior","percentage":20}]},{"name":"Cable Pull Through","description":"Facing away from a low cable with the rope between the legs, you hinge at the hips and drive them forward to stand tall. It grooves a powerful hip-hinge pattern and builds the glutes and hamstrings with little spinal loading.","descriptionAr":"مديرا ظهره إلى كابل منخفض مع مرور الحبل بين الساقين، ينحني المتدرب من الوركين ثم يدفعهما إلى الأمام للوقوف منتصبا. يرسخ هذا التمرين نمط الانحناء الوركي القوي ويبني الأليتين وأوتار الركبة بحمل ضئيل على العمود الفقري.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"glutes","percentage":55},{"bodyTarget":"hamstrings","percentage":30},{"bodyTarget":"erector_spinae","percentage":15}]},{"name":"Cable Twist (Down to up)","description":"From a low pulley, you rotate the torso and drive the handle diagonally upward across the body with straight arms. The low-to-high path trains the obliques and abs through a powerful rotational pattern used in throwing and swinging sports.","descriptionAr":"من بكرة منخفضة، يدير المتدرب جذعه ويدفع المقبض قطريا إلى الأعلى عبر الجسم وذراعاه ممدودتان. يدرب المسار من الأسفل إلى الأعلى العضلات المائلة وعضلات البطن عبر نمط دوراني قوي يستخدم في رياضات الرمي والضرب.","measurement":"reps","types":["Core"],"targets":[{"bodyTarget":"core_abs","percentage":50},{"bodyTarget":"obliques","percentage":35},{"bodyTarget":"core_deep","percentage":15}]},{"name":"Cable Twist (Up to down)","description":"From a high pulley, you pull the handle diagonally down and across the body in a chopping motion while the hips and core control the rotation. It strengthens the obliques and abs and builds controlled rotational power.","descriptionAr":"من بكرة مرتفعة، يسحب المتدرب المقبض قطريا إلى الأسفل وعبر الجسم بحركة تشبه التقطيع بينما يتحكم الوركان والجذع في الدوران. يقوي هذا التمرين العضلات المائلة وعضلات البطن ويبني قدرة دورانية منضبطة.","measurement":"reps","types":["Core"],"targets":[{"bodyTarget":"core_abs","percentage":50},{"bodyTarget":"obliques","percentage":35},{"bodyTarget":"core_deep","percentage":15}]},{"name":"Calf Extension (Machine)","description":"Pressing through the balls of the feet against machine resistance takes the calves through a full stretch and contraction. Controlled reps with a pause at the stretched bottom are key for building calf size.","descriptionAr":"الدفع بمقدمة القدمين ضد مقاومة الجهاز يأخذ عضلات الساق الخلفية عبر إطالة وانقباض كاملين. تعد التكرارات المنضبطة مع توقف عند نقطة الإطالة السفلية أساسية لبناء حجم بطة الساق.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"calves","percentage":90},{"bodyTarget":"hamstrings","percentage":10}]},{"name":"Calf Press (Machine)","description":"Performed on a leg-press style machine, you extend the ankles by pressing the platform away with the balls of the feet. The seated position allows heavy, stable loading of the calves through a long range of motion.","descriptionAr":"يؤدى على جهاز يشبه جهاز ضغط الأرجل، حيث يمد المتدرب كاحليه بدفع المنصة بعيدا بمقدمة القدمين. تتيح وضعية الجلوس تحميلا ثقيلا وثابتا لعضلات الساق الخلفية عبر مدى حركة طويل.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"calves","percentage":90},{"bodyTarget":"hamstrings","percentage":10}]},{"name":"Chest Dip","description":"Lowering the body between parallel bars with a forward lean stretches the chest deeply before pressing back to lockout. It is a fundamental bodyweight builder of the lower chest, triceps, and front delts.","descriptionAr":"خفض الجسم بين متوازيين مع ميل أمامي يمنح الصدر إطالة عميقة قبل الدفع مجددا حتى فرد الذراعين. وهو تمرين أساسي بوزن الجسم لبناء أسفل الصدر والعضلة ثلاثية الرؤوس ومقدمة الكتفين.","measurement":"reps","types":["Push Day","Upper Body","Calisthenics"],"targets":[{"bodyTarget":"chest","percentage":55},{"bodyTarget":"triceps","percentage":30},{"bodyTarget":"shoulders_anterior","percentage":15}]},{"name":"Chest Dip (Assisted)","description":"The assisted machine or band offsets part of your bodyweight, letting you dip with a forward lean to load the lower chest and triceps. It is the standard progression toward full bodyweight chest dips.","descriptionAr":"يعوض جهاز المساعدة أو الحزام المطاطي جزءا من وزن الجسم، مما يتيح أداء الغطس مع ميل أمامي لتحميل أسفل الصدر والعضلة ثلاثية الرؤوس. وهو التدرج المعتمد للوصول إلى الغطس الكامل بوزن الجسم.","measurement":"reps","types":["Push Day","Upper Body","Calisthenics"],"targets":[{"bodyTarget":"chest","percentage":55},{"bodyTarget":"triceps","percentage":30},{"bodyTarget":"shoulders_anterior","percentage":15}]},{"name":"Chest Dip (Weighted)","description":"Adding a dip belt or dumbbell to the bodyweight dip turns it into a heavy compound press for the lower chest and triceps. Progressive loading here builds serious pressing strength and upper-body mass.","descriptionAr":"إضافة حزام أثقال أو دمبل إلى الغطس بوزن الجسم تحوله إلى تمرين ضغط مركب ثقيل لأسفل الصدر والعضلة ثلاثية الرؤوس. يبني التحميل التدريجي هنا قوة دفع كبيرة وكتلة عضلية في الجزء العلوي من الجسم.","measurement":"reps","types":["Push Day","Upper Body","Calisthenics"],"targets":[{"bodyTarget":"chest","percentage":55},{"bodyTarget":"triceps","percentage":30},{"bodyTarget":"shoulders_anterior","percentage":15}]},{"name":"Chest Fly (Band)","description":"With a band anchored behind you, the arms sweep together in a wide arc, isolating the chest as the band tension rises toward the finish. It is a joint-friendly fly you can perform anywhere to build and pump the pecs.","descriptionAr":"مع تثبيت الحزام المطاطي خلف الجسم، تتحرك الذراعان معا في قوس واسع، فتعزلان عضلات الصدر بينما تزداد مقاومة الحزام قرب نهاية الحركة. وهو تمرين تجميع لطيف على المفاصل يمكن أداؤه في أي مكان لبناء عضلات الصدر وتنشيطها.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"chest","percentage":80},{"bodyTarget":"shoulders_anterior","percentage":20}]},{"name":"Chest Fly (Dumbbell)","description":"Lying on a bench with slightly bent elbows, you lower the dumbbells in a wide arc for a deep pec stretch, then bring them together above the chest. It isolates the chest and is a key movement for pec hypertrophy.","descriptionAr":"مستلقيا على المقعد مع ثني بسيط في المرفقين، يخفض المتدرب الدمبلين في قوس واسع لإطالة عميقة لعضلات الصدر، ثم يضمهما فوق الصدر. يعزل هذا التمرين الصدر ويعد حركة رئيسية لتضخيم عضلاته.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"chest","percentage":80},{"bodyTarget":"shoulders_anterior","percentage":20}]},{"name":"Chest Fly (Machine)","description":"The machine guides the arms through a fixed arc, keeping constant tension on the pecs from stretch to squeeze. Its stability makes it ideal for strict isolation work and safely training the chest close to failure.","descriptionAr":"يوجه الجهاز الذراعين عبر قوس ثابت، محافظا على توتر مستمر لعضلات الصدر من الإطالة حتى العصر. يجعل ثباته مثاليا لعمل العزل الصارم وتدريب الصدر بأمان قرب الإجهاد الكامل.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"chest","percentage":80},{"bodyTarget":"shoulders_anterior","percentage":20}]},{"name":"Chest Fly (Suspension)","description":"Leaning into suspension straps with arms wide, you control the descent into a deep fly and then draw the hands together to rise. Bodyweight and instability make it a demanding chest isolation that also challenges the core.","descriptionAr":"بالميل على أحزمة التعليق مع فتح الذراعين، يتحكم المتدرب في النزول إلى وضعية تجميع عميقة ثم يضم يديه للصعود. يجعل وزن الجسم وعدم الاستقرار هذا التمرين عزلا مجهدا للصدر يتحدى الجذع أيضا.","measurement":"reps","types":["Push Day","Upper Body","Calisthenics"],"targets":[{"bodyTarget":"chest","percentage":80},{"bodyTarget":"shoulders_anterior","percentage":20}]},{"name":"Chest Press (Band)","description":"With the band anchored behind the back or a post, you press the handles forward until the arms extend, loading the chest, triceps, and front delts. Band resistance builds pressing strength anywhere, with tension peaking at lockout.","descriptionAr":"مع تثبيت الحزام خلف الظهر أو على عمود، يدفع المتدرب المقبضين إلى الأمام حتى تمتد الذراعان، محملا الصدر والعضلة ثلاثية الرؤوس ومقدمة الكتفين. تبني مقاومة الحزام قوة الدفع في أي مكان، مع بلوغ التوتر ذروته عند فرد الذراعين.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"chest","percentage":60},{"bodyTarget":"triceps","percentage":25},{"bodyTarget":"shoulders_anterior","percentage":15}]},{"name":"Chest Press (Machine)","description":"Seated with handles at chest level, you press forward along a guided path that keeps the chest, triceps, and front delts under stable load. It allows safe, heavy pressing without a spotter and easy progressive overload.","descriptionAr":"جالسا والمقبضان عند مستوى الصدر، يدفع المتدرب إلى الأمام عبر مسار موجه يبقي الصدر والعضلة ثلاثية الرؤوس ومقدمة الكتفين تحت حمل ثابت. يتيح الجهاز ضغطا ثقيلا وآمنا دون مساعد وزيادة الأحمال تدريجيا بسهولة.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"chest","percentage":60},{"bodyTarget":"triceps","percentage":25},{"bodyTarget":"shoulders_anterior","percentage":15}]},{"name":"Chest Supported Incline Row (Dumbbell)","description":"Lying chest-down on an incline bench removes momentum and lower-back strain while you row the dumbbells to your sides. The strict support isolates the upper back, lats, and rear shoulders for clean, focused pulling.","descriptionAr":"الاستلقاء على الصدر فوق مقعد مائل يزيل الزخم والإجهاد عن أسفل الظهر بينما يسحب المتدرب الدمبلين إلى جانبيه. يعزل هذا الدعم الصارم أعلى الظهر والعضلة الظهرية العريضة والكتفين الخلفيتين لسحب نظيف ومركز.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"upper_back","percentage":45},{"bodyTarget":"lats","percentage":25},{"bodyTarget":"biceps","percentage":20},{"bodyTarget":"shoulders_posterior","percentage":10}]},{"name":"Chest Supported Reverse Fly (Dumbbell)","description":"Lying chest-down on an incline bench, you raise the dumbbells out to the sides with slightly bent elbows, isolating the rear delts and upper back. The chest support eliminates swinging, forcing the target muscles to do all the work.","descriptionAr":"مستلقيا على الصدر فوق مقعد مائل، يرفع المتدرب الدمبلين إلى الجانبين مع ثني بسيط في المرفقين، فيعزل العضلة الدالية الخلفية وأعلى الظهر. يلغي دعم الصدر التأرجح، مما يجبر العضلات المستهدفة على أداء العمل كله.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"shoulders_posterior","percentage":60},{"bodyTarget":"upper_back","percentage":25},{"bodyTarget":"traps","percentage":15}]},{"name":"Chest Supported T Bar Row","description":"With the torso braced against the machine's pad, you row the T-bar handles toward the chest, loading the mid and upper back heavily. The support removes lower-back stress, allowing strict, heavy rowing for back thickness.","descriptionAr":"مع استناد الجذع إلى وسادة الجهاز، يسحب المتدرب مقابض البار على شكل T نحو الصدر، محملا منتصف الظهر وأعلاه بقوة. يزيل الدعم الضغط عن أسفل الظهر، مما يتيح سحبا صارما وثقيلا لبناء سماكة الظهر.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"upper_back","percentage":45},{"bodyTarget":"lats","percentage":25},{"bodyTarget":"biceps","percentage":20},{"bodyTarget":"shoulders_posterior","percentage":10}]},{"name":"Chest Supported Y Raise (Dumbbell)","description":"Lying chest-down on an incline bench, you raise light dumbbells overhead in a Y shape, targeting the lower trapezius and rear shoulders. It strengthens the muscles that upwardly rotate and stabilize the shoulder blades, improving overhead mechanics.","descriptionAr":"مستلقيا على الصدر فوق مقعد مائل، يرفع المتدرب دمبلين خفيفين فوق الرأس على شكل حرف Y، مستهدفا الجزء السفلي من العضلة شبه المنحرفة والكتفين الخلفيتين. يقوي هذا التمرين العضلات التي تدير لوحي الكتف وتثبتهما، مما يحسن ميكانيكا الحركات فوق الرأس.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"shoulders_posterior","percentage":45},{"bodyTarget":"traps","percentage":30},{"bodyTarget":"upper_back","percentage":25}]},{"name":"Chin Up (Assisted)","description":"Using a band or assisted machine to offset bodyweight, you pull yourself up with an underhand grip until the chin clears the bar. It builds the lats and biceps while progressing you toward unassisted chin ups.","descriptionAr":"باستخدام حزام مطاطي أو جهاز مساعدة لتعويض جزء من وزن الجسم، يسحب المتدرب نفسه للأعلى بقبضة سفلية حتى يتجاوز ذقنه البار. يبني هذا التمرين العضلة الظهرية العريضة والعضلة ذات الرأسين ويقربك من أداء التمرين دون مساعدة.","measurement":"reps","types":["Pull Day","Upper Body","Calisthenics"],"targets":[{"bodyTarget":"lats","percentage":50},{"bodyTarget":"biceps","percentage":30},{"bodyTarget":"upper_back","percentage":12},{"bodyTarget":"shoulders_posterior","percentage":8}]},{"name":"Chin Up (Weighted)","description":"Adding weight via a dip belt to the underhand pull-up turns it into a heavy compound lift for the lats and biceps. It is one of the most effective ways to keep building upper-body pulling strength once bodyweight reps become easy.","descriptionAr":"إضافة وزن عبر حزام أثقال إلى العقلة بالقبضة السفلية تحولها إلى رفعة مركبة ثقيلة للعضلة الظهرية العريضة والعضلة ذات الرأسين. وهي من أكثر الطرق فاعلية لمواصلة بناء قوة السحب في الجزء العلوي بعد أن تصبح تكرارات وزن الجسم سهلة.","measurement":"reps","types":["Pull Day","Upper Body","Calisthenics"],"targets":[{"bodyTarget":"lats","percentage":50},{"bodyTarget":"biceps","percentage":30},{"bodyTarget":"upper_back","percentage":12},{"bodyTarget":"shoulders_posterior","percentage":8}]},{"name":"Clamshell","description":"Lying on your side with knees bent and feet together, you open the top knee like a clamshell against gravity or a band. It isolates the gluteus medius, improving hip stability and helping protect the knees and lower back.","descriptionAr":"مستلقيا على الجانب مع ثني الركبتين وضم القدمين، يفتح المتدرب الركبة العلوية كالصدفة ضد الجاذبية أو حزام مقاومة. يعزل هذا التمرين العضلة الألوية الوسطى، فيحسن ثبات الورك ويساعد على حماية الركبتين وأسفل الظهر.","measurement":"reps","types":["Lower Body","Functional"],"targets":[{"bodyTarget":"glutes","percentage":85},{"bodyTarget":"hip_flexors","percentage":15}]},{"name":"Clap Push Ups","description":"An explosive push-up in which you drive off the floor hard enough to clap before catching yourself. It develops upper-body power in the chest, triceps, and shoulders while demanding a rigid, braced core.","descriptionAr":"تمرين ضغط انفجاري يدفع فيه المتدرب جسمه عن الأرض بقوة تكفي للتصفيق قبل استقبال نفسه. يطور هذا التمرين القدرة الانفجارية للجزء العلوي في الصدر والعضلة ثلاثية الرؤوس والكتفين مع مطالبة الجذع بالبقاء مشدودا وثابتا.","measurement":"reps","types":["Push Day","Upper Body","Calisthenics"],"targets":[{"bodyTarget":"chest","percentage":55},{"bodyTarget":"triceps","percentage":25},{"bodyTarget":"shoulders_anterior","percentage":15},{"bodyTarget":"core_abs","percentage":5}]},{"name":"Clean","description":"The clean pulls the barbell explosively from the floor and catches it on the front of the shoulders in a squat position. It develops full-body power with strong demands on the legs, hips, and upper back.","descriptionAr":"يعتمد تمرين الكلين على سحب البار من الأرض بشكل انفجاري واستقباله على مقدمة الكتفين في وضعية القرفصاء. وهو يطور قوة الجسم الكامل مع متطلبات عالية من الساقين والوركين وأعلى الظهر.","measurement":"reps","types":["Olympic Lifting","Full Body"],"targets":[{"bodyTarget":"quadriceps","percentage":30},{"bodyTarget":"glutes","percentage":25},{"bodyTarget":"hamstrings","percentage":25},{"bodyTarget":"traps","percentage":20}]},{"name":"Clean and Jerk","description":"The clean and jerk is a two-part Olympic lift in which the barbell is pulled explosively to the shoulders, then driven overhead using a dip and leg drive. It develops total-body power, coordination, and strength through the legs, hips, and shoulders.","descriptionAr":"يتكون تمرين الخطف والنتر من مرحلتين: سحب البار بشكل انفجاري إلى الكتفين، ثم دفعه فوق الرأس بمساعدة دفع الساقين. وهو يطور قوة الجسم الكامل والتناسق الحركي عبر الساقين والوركين والكتفين.","measurement":"reps","types":["Olympic Lifting","Full Body"],"targets":[{"bodyTarget":"quadriceps","percentage":30},{"bodyTarget":"glutes","percentage":25},{"bodyTarget":"shoulders_anterior","percentage":25},{"bodyTarget":"hamstrings","percentage":20}]},{"name":"Clean and Press","description":"The clean and press brings the barbell from the floor to the shoulders, then presses it strictly overhead without leg drive. It combines posterior-chain power with genuine overhead pressing strength in the shoulders and triceps.","descriptionAr":"ينقل هذا التمرين البار من الأرض إلى الكتفين ثم يدفعه فوق الرأس بضغط صارم دون مساعدة الساقين. وهو يجمع بين قوة السلسلة الخلفية وقوة الضغط الحقيقية في الكتفين والعضلة ثلاثية الرؤوس.","measurement":"reps","types":["Olympic Lifting","Full Body"],"targets":[{"bodyTarget":"shoulders_anterior","percentage":30},{"bodyTarget":"quadriceps","percentage":25},{"bodyTarget":"glutes","percentage":25},{"bodyTarget":"triceps","percentage":20}]},{"name":"Clean Pull","description":"The clean pull drives a barbell from the floor to full hip extension with a powerful shrug, without catching the bar. It builds the explosive posterior-chain strength and pulling speed that carry over directly to the full clean.","descriptionAr":"تعتمد سحبة الكلين على دفع البار من الأرض حتى الامتداد الكامل للوركين مع هزة كتف قوية دون استقبال البار. وهي تبني القوة الانفجارية للسلسلة الخلفية وسرعة السحب بما ينعكس مباشرة على أداء تمرين الكلين الكامل.","measurement":"reps","types":["Olympic Lifting","Full Body"],"targets":[{"bodyTarget":"hamstrings","percentage":30},{"bodyTarget":"glutes","percentage":25},{"bodyTarget":"traps","percentage":25},{"bodyTarget":"erector_spinae","percentage":20}]},{"name":"Climbing","description":"Climbing elevates the heart rate while demanding sustained pulling strength through the grip, forearms, and back. Regular sessions build aerobic endurance, body control, and total-body coordination.","descriptionAr":"يرفع التسلق معدل ضربات القلب بينما يتطلب قوة سحب مستمرة في القبضة والساعدين والظهر. وتبني الممارسة المنتظمة التحمل الهوائي والتحكم بالجسم والتناسق الحركي الشامل.","measurement":"distance_duration","types":["Cardio","Functional"],"targets":[{"bodyTarget":"cardiovascular","percentage":45},{"bodyTarget":"endurance","percentage":20},{"bodyTarget":"forearms","percentage":20},{"bodyTarget":"lats","percentage":15}]},{"name":"Cross Body Hammer Curl","description":"The cross body hammer curl flexes the elbow with a neutral grip while bringing the dumbbell across the torso toward the opposite shoulder. This path emphasizes the brachialis and brachioradialis, adding arm thickness and forearm strength.","descriptionAr":"يثني هذا التمرين المرفق بقبضة محايدة مع رفع الدمبل بشكل مائل عبر الجذع نحو الكتف المقابل. ويركز هذا المسار على العضلة العضدية والعضدية الكعبرية، مما يزيد سماكة الذراع وقوة الساعد.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"biceps","percentage":60},{"bodyTarget":"forearms","percentage":40}]},{"name":"Crunch (Machine)","description":"The machine crunch flexes the spine against adjustable resistance, isolating the rectus abdominis through a controlled range of motion. The fixed path makes progressive overload of the abs simple and joint-friendly.","descriptionAr":"يثني تمرين الطحن على الجهاز العمود الفقري ضد مقاومة قابلة للتعديل، معزولاً العضلة البطنية المستقيمة عبر مدى حركي منضبط. ويسهل المسار الثابت زيادة الحمل التدريجي على عضلات البطن بطريقة آمنة للمفاصل.","measurement":"reps","types":["Core"],"targets":[{"bodyTarget":"core_abs","percentage":85},{"bodyTarget":"obliques","percentage":15}]},{"name":"Crunch (Weighted)","description":"The weighted crunch adds external load to spinal flexion, forcing the rectus abdominis to work harder than in a bodyweight crunch. Holding a plate or dumbbell against the chest allows steady progressive overload of the abs.","descriptionAr":"يضيف الطحن بالأوزان حملاً خارجياً إلى ثني العمود الفقري، مما يجبر العضلة البطنية المستقيمة على بذل جهد أكبر من الطحن بوزن الجسم. ويتيح حمل قرص أو دمبل على الصدر زيادة الحمل التدريجي على عضلات البطن.","measurement":"reps","types":["Core"],"targets":[{"bodyTarget":"core_abs","percentage":85},{"bodyTarget":"obliques","percentage":15}]},{"name":"Curtsy Lunge (Dumbbell)","description":"The dumbbell curtsy lunge steps one leg diagonally behind the other, loading the quadriceps and glutes while challenging the adductors and balance. It strengthens the legs through a frontal-plane pattern that standard lunges miss.","descriptionAr":"يخطو هذا التمرين بساق واحدة قطرياً خلف الأخرى مع حمل الدمبل، محملاً العضلة الرباعية والألوية ومتحدياً العضلات الضامة والتوازن. وهو يقوي الساقين عبر نمط حركي جانبي لا توفره الاندفاعات التقليدية.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"quadriceps","percentage":40},{"bodyTarget":"glutes","percentage":35},{"bodyTarget":"adductors","percentage":15},{"bodyTarget":"hamstrings","percentage":10}]},{"name":"Cycling","description":"Cycling is a low-impact cardio activity that elevates the heart rate through continuous, rhythmic leg work. It improves aerobic capacity and muscular endurance in the quadriceps and calves while sparing the joints.","descriptionAr":"يعد ركوب الدراجة نشاطاً قلبياً منخفض التأثير يرفع معدل ضربات القلب من خلال عمل الساقين المستمر والإيقاعي. وهو يحسن السعة الهوائية والتحمل العضلي في العضلة الرباعية وربلة الساق مع الحفاظ على المفاصل.","measurement":"distance_duration","types":["Cardio"],"targets":[{"bodyTarget":"cardiovascular","percentage":50},{"bodyTarget":"endurance","percentage":25},{"bodyTarget":"quadriceps","percentage":15},{"bodyTarget":"calves","percentage":10}]},{"name":"Deadlift (Band)","description":"The band deadlift trains the hip hinge against elastic resistance that increases toward lockout. It teaches the glutes and hamstrings to finish the movement powerfully while keeping spinal loading light.","descriptionAr":"تدرب الرفعة المميتة بالحبل المطاطي حركة مفصلة الورك ضد مقاومة مرنة تزداد نحو نهاية الحركة. وهي تعلم الألوية وأوتار الركبة إنهاء الحركة بقوة مع إبقاء الحمل على العمود الفقري خفيفاً.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"glutes","percentage":40},{"bodyTarget":"hamstrings","percentage":30},{"bodyTarget":"erector_spinae","percentage":20},{"bodyTarget":"quadriceps","percentage":10}]},{"name":"Deadlift (Barbell)","description":"The barbell deadlift lifts a loaded bar from the floor to standing by driving through the legs and extending the hips. It is a foundational strength exercise for the glutes, hamstrings, and the entire back.","descriptionAr":"ترفع الرفعة المميتة بالبار وزناً من الأرض حتى الوقوف الكامل عبر الدفع بالساقين ومد الوركين. وهي تمرين قوة أساسي للألوية وأوتار الركبة والظهر بأكمله.","measurement":"reps","types":["Leg Day","Powerlifting"],"targets":[{"bodyTarget":"glutes","percentage":40},{"bodyTarget":"hamstrings","percentage":30},{"bodyTarget":"erector_spinae","percentage":20},{"bodyTarget":"quadriceps","percentage":10}]},{"name":"Deadlift (Dumbbell)","description":"The dumbbell deadlift replicates the hip hinge with weights held at the sides, making it accessible when a barbell is unavailable. It strengthens the glutes, hamstrings, and spinal erectors through a controlled, joint-friendly range.","descriptionAr":"تحاكي الرفعة المميتة بالدمبل حركة مفصلة الورك مع حمل الأوزان على الجانبين، مما يجعلها متاحة عند عدم توفر البار. وهي تقوي الألوية وأوتار الركبة وعضلات ناصبة الفقار عبر مدى حركي منضبط وآمن للمفاصل.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"glutes","percentage":40},{"bodyTarget":"hamstrings","percentage":30},{"bodyTarget":"erector_spinae","percentage":20},{"bodyTarget":"quadriceps","percentage":10}]},{"name":"Deadlift (Smith Machine)","description":"The Smith machine deadlift performs the hip hinge on a fixed vertical path, helping lifters groove technique with reduced balance demands. It loads the glutes, hamstrings, and lower back in a controlled and stable way.","descriptionAr":"تؤدى الرفعة المميتة على جهاز سميث عبر مسار عمودي ثابت يساعد المتدربين على إتقان التقنية مع تقليل متطلبات التوازن. وهي تحمل الألوية وأوتار الركبة وأسفل الظهر بطريقة منضبطة ومستقرة.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"glutes","percentage":40},{"bodyTarget":"hamstrings","percentage":30},{"bodyTarget":"erector_spinae","percentage":20},{"bodyTarget":"quadriceps","percentage":10}]},{"name":"Deadlift (Trap bar)","description":"The trap bar deadlift places the load at the lifter's sides, allowing a more upright torso and greater knee bend than a straight bar. It builds the glutes, hamstrings, and quadriceps while reducing stress on the lower back.","descriptionAr":"تضع الرفعة المميتة بالبار السداسي الحمل على جانبي المتدرب، مما يسمح بجذع أكثر استقامة وثني أكبر للركبتين مقارنة بالبار المستقيم. وهي تبني الألوية وأوتار الركبة والعضلة الرباعية مع تقليل الضغط على أسفل الظهر.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"glutes","percentage":35},{"bodyTarget":"quadriceps","percentage":25},{"bodyTarget":"hamstrings","percentage":25},{"bodyTarget":"erector_spinae","percentage":15}]},{"name":"Deadlift High Pull","description":"The deadlift high pull extends the hips explosively, then continues pulling the bar to chest height with the elbows leading. It links posterior-chain power to the traps and shoulders in one continuous movement.","descriptionAr":"يمد هذا التمرين الوركين بشكل انفجاري ثم يواصل سحب البار إلى مستوى الصدر مع تقدم المرفقين. وهو يربط قوة السلسلة الخلفية بعضلات الترابيس والكتفين في حركة واحدة متصلة.","measurement":"reps","types":["Full Body","Functional"],"targets":[{"bodyTarget":"glutes","percentage":30},{"bodyTarget":"hamstrings","percentage":25},{"bodyTarget":"traps","percentage":25},{"bodyTarget":"shoulders_lateral","percentage":20}]},{"name":"Decline Bench Press (Barbell)","description":"The decline barbell bench press presses the bar from a downward-angled bench, shifting emphasis to the lower chest fibers. The angle typically reduces shoulder strain while still allowing heavy pressing loads.","descriptionAr":"يضغط تمرين البنش المائل للأسفل بالبار من مقعد مائل نحو الأسفل، مما ينقل التركيز إلى ألياف الصدر السفلية. وتقلل هذه الزاوية عادة الإجهاد على الكتفين مع السماح بأحمال ضغط ثقيلة.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"chest","percentage":60},{"bodyTarget":"triceps","percentage":25},{"bodyTarget":"shoulders_anterior","percentage":15}]},{"name":"Decline Bench Press (Dumbbell)","description":"The decline dumbbell bench press targets the lower chest while each arm stabilizes its own load. The independent dumbbells increase the range of motion and expose side-to-side strength imbalances.","descriptionAr":"يستهدف البنش المائل للأسفل بالدمبل الجزء السفلي من الصدر بينما تثبت كل ذراع حملها بشكل مستقل. وتزيد الدمبلات المستقلة مدى الحركة وتكشف اختلالات القوة بين الجانبين.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"chest","percentage":60},{"bodyTarget":"triceps","percentage":25},{"bodyTarget":"shoulders_anterior","percentage":15}]},{"name":"Decline Bench Press (Machine)","description":"The decline machine press guides the pressing path at a downward angle, isolating the lower chest with minimal stabilization demands. It is well suited to controlled overload and training close to failure safely.","descriptionAr":"يوجه جهاز الضغط المائل للأسفل مسار الضغط بزاوية منخفضة، معزولاً الجزء السفلي من الصدر مع الحد الأدنى من متطلبات التثبيت. وهو مناسب لزيادة الحمل المنضبطة والتدريب قرب الفشل العضلي بأمان.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"chest","percentage":60},{"bodyTarget":"triceps","percentage":25},{"bodyTarget":"shoulders_anterior","percentage":15}]},{"name":"Decline Bench Press (Smith Machine)","description":"The Smith machine decline press fixes the bar path at a downward angle, emphasizing the lower chest with added stability. The guided track lets lifters focus on pressing effort without balancing the bar.","descriptionAr":"يثبت الضغط المائل للأسفل على جهاز سميث مسار البار بزاوية منخفضة، مركزاً على الجزء السفلي من الصدر مع ثبات إضافي. ويتيح المسار الموجه للمتدرب التركيز على جهد الضغط دون الانشغال بموازنة البار.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"chest","percentage":60},{"bodyTarget":"triceps","percentage":25},{"bodyTarget":"shoulders_anterior","percentage":15}]},{"name":"Decline Chest Fly (Dumbbell)","description":"The decline dumbbell fly sweeps the arms in a wide arc over a downward-angled bench, stretching and contracting the lower chest. Keeping a slight elbow bend isolates the pecs with minimal triceps involvement.","descriptionAr":"يحرك هذا التمرين الذراعين في قوس واسع فوق مقعد مائل للأسفل، مما يمدد الجزء السفلي من الصدر ويقلصه. ويؤدي الحفاظ على انثناء بسيط في المرفقين إلى عزل عضلات الصدر مع مشاركة ضئيلة للعضلة ثلاثية الرؤوس.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"chest","percentage":75},{"bodyTarget":"shoulders_anterior","percentage":15},{"bodyTarget":"biceps","percentage":10}]},{"name":"Decline Crunch","description":"The decline crunch flexes the trunk upward on a decline bench, lengthening the range of motion compared with a floor crunch. Gravity provides increasing resistance, strengthening the rectus abdominis and hip flexors.","descriptionAr":"يثني تمرين الطحن المائل الجذع نحو الأعلى على مقعد مائل، مما يطيل مدى الحركة مقارنة بالطحن على الأرض. وتوفر الجاذبية مقاومة متزايدة تقوي العضلة البطنية المستقيمة وعضلات ثني الورك.","measurement":"reps","types":["Core"],"targets":[{"bodyTarget":"core_abs","percentage":75},{"bodyTarget":"hip_flexors","percentage":15},{"bodyTarget":"obliques","percentage":10}]},{"name":"Decline Crunch (Weighted)","description":"The weighted decline crunch performs spinal flexion on a decline bench with added load, working the abs through a longer range against gravity. It is one of the most effective ways to progressively overload the rectus abdominis.","descriptionAr":"يؤدي هذا التمرين ثني العمود الفقري على مقعد مائل مع حمل إضافي، فيعمل على عضلات البطن عبر مدى أطول ضد الجاذبية. وهو من أكثر الطرق فعالية لزيادة الحمل التدريجي على العضلة البطنية المستقيمة.","measurement":"reps","types":["Core"],"targets":[{"bodyTarget":"core_abs","percentage":75},{"bodyTarget":"hip_flexors","percentage":15},{"bodyTarget":"obliques","percentage":10}]},{"name":"Decline Push Up","description":"The decline push up elevates the feet, shifting more body weight onto the upper chest and shoulders. It is a harder push-up variation that builds pressing strength without any equipment.","descriptionAr":"يرفع تمرين الضغط المائل القدمين، مما ينقل مزيداً من وزن الجسم إلى الجزء العلوي من الصدر والكتفين. وهو نسخة أصعب من تمرين الضغط تبني قوة الدفع دون أي معدات.","measurement":"reps","types":["Push Day","Calisthenics"],"targets":[{"bodyTarget":"chest","percentage":50},{"bodyTarget":"shoulders_anterior","percentage":30},{"bodyTarget":"triceps","percentage":20}]},{"name":"Downward Dog","description":"Downward dog is a held yoga position forming an inverted V, stretching the hamstrings, calves, and shoulders while lengthening the spine. Regular practice improves posterior-chain flexibility and shoulder mobility.","descriptionAr":"وضعية الكلب المتجه للأسفل هي وضعية يوغا ثابتة على شكل حرف V مقلوب، تمدد أوتار الركبة وربلتي الساقين والكتفين مع إطالة العمود الفقري. وتحسن الممارسة المنتظمة مرونة السلسلة الخلفية وحركية الكتفين.","measurement":"time_hold","types":["Mobility"],"targets":[{"bodyTarget":"flexibility","percentage":40},{"bodyTarget":"hamstrings","percentage":25},{"bodyTarget":"shoulders_anterior","percentage":20},{"bodyTarget":"calves","percentage":15}]},{"name":"Drag Curl","description":"The drag curl pulls the bar upward along the torso with the elbows drifting back, removing front-delt assistance from the curl. This path keeps constant tension on the biceps, particularly the long head.","descriptionAr":"يسحب تمرين الدراغ كيرل البار للأعلى ملاصقاً للجذع مع تحرك المرفقين للخلف، مما يلغي مساعدة الكتف الأمامي في الحركة. ويحافظ هذا المسار على توتر مستمر في العضلة ذات الرأسين، وخاصة رأسها الطويل.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"biceps","percentage":75},{"bodyTarget":"forearms","percentage":25}]},{"name":"Dragonfly","description":"The dragonfly lowers the straight body from a shoulder-supported position, resisting extension through a very long lever arm. It is an advanced, eccentric-focused exercise for the abs and hip flexors.","descriptionAr":"يخفض تمرين الدراغون فلاي الجسم المستقيم من وضعية مرتكزة على الكتفين، مقاوماً التمدد عبر ذراع رفع طويلة جداً. وهو تمرين متقدم يركز على المرحلة السلبية لتقوية عضلات البطن وثنيات الورك.","measurement":"reps","types":["Core","Calisthenics"],"targets":[{"bodyTarget":"core_abs","percentage":55},{"bodyTarget":"hip_flexors","percentage":25},{"bodyTarget":"core_deep","percentage":20}]},{"name":"Dumbbell Snatch","description":"The dumbbell snatch drives a dumbbell from the floor to overhead in one explosive movement powered by hip extension. It develops total-body power, shoulder stability, and conditioning at the same time.","descriptionAr":"يدفع خطف الدمبل الوزن من الأرض إلى فوق الرأس في حركة انفجارية واحدة تعتمد على مد الوركين. وهو يطور قوة الجسم الكامل وثبات الكتف واللياقة البدنية في آن واحد.","measurement":"reps","types":["Full Body","Functional"],"targets":[{"bodyTarget":"glutes","percentage":30},{"bodyTarget":"shoulders_anterior","percentage":25},{"bodyTarget":"hamstrings","percentage":25},{"bodyTarget":"quadriceps","percentage":20}]},{"name":"Dumbbell Squeeze Press","description":"The squeeze press presses two dumbbells while actively pushing them together, keeping constant tension on the inner chest. The isometric squeeze increases pec activation throughout the entire pressing range.","descriptionAr":"يضغط هذا التمرين دمبلين مع دفعهما نحو بعضهما بقوة طوال الحركة، محافظاً على توتر مستمر في الجزء الداخلي من الصدر. ويزيد هذا الضغط المتساوي القياس تفعيل عضلات الصدر عبر كامل مدى الضغط.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"chest","percentage":65},{"bodyTarget":"triceps","percentage":25},{"bodyTarget":"shoulders_anterior","percentage":10}]},{"name":"Elbow to Knee","description":"Elbow to knee crunches rotate the torso to bring the opposite elbow toward the rising knee, combining trunk flexion with rotation. This pattern works the obliques together with the rectus abdominis.","descriptionAr":"يدير تمرين المرفق إلى الركبة الجذع لتقريب المرفق من الركبة المقابلة المرتفعة، جامعاً بين ثني الجذع ودورانه. ويعمل هذا النمط على العضلات المائلة إلى جانب العضلة البطنية المستقيمة.","measurement":"reps","types":["Core"],"targets":[{"bodyTarget":"core_abs","percentage":50},{"bodyTarget":"obliques","percentage":40},{"bodyTarget":"hip_flexors","percentage":10}]},{"name":"Elliptical Trainer","description":"The elliptical trainer provides continuous low-impact cardio by moving the legs through a smooth gliding cycle. It raises the heart rate and builds lower-body endurance with minimal stress on the joints.","descriptionAr":"يوفر الجهاز الإهليلجي تمريناً قلبياً متواصلاً منخفض التأثير عبر تحريك الساقين في دورة انزلاقية سلسة. وهو يرفع معدل ضربات القلب ويبني تحمل الجزء السفلي من الجسم مع ضغط ضئيل على المفاصل.","measurement":"distance_duration","types":["Cardio"],"targets":[{"bodyTarget":"cardiovascular","percentage":50},{"bodyTarget":"endurance","percentage":25},{"bodyTarget":"quadriceps","percentage":15},{"bodyTarget":"glutes","percentage":10}]},{"name":"EZ Bar Biceps Curl","description":"The EZ bar curl flexes the elbows with a semi-supinated grip that eases wrist strain compared with a straight bar. It allows heavy, comfortable loading of the biceps and forearms.","descriptionAr":"يثني تمرين العضلة ذات الرأسين ببار EZ المرفقين بقبضة شبه مستلقية تخفف الإجهاد على الرسغين مقارنة بالبار المستقيم. وهو يتيح تحميلاً ثقيلاً ومريحاً للعضلة ذات الرأسين والساعدين.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"biceps","percentage":70},{"bodyTarget":"forearms","percentage":30}]},{"name":"Farmers Walk","description":"The farmers walk carries heavy weights at the sides for distance or time, taxing the grip, traps, and core. It builds real-world carrying strength, upright posture, and work capacity.","descriptionAr":"يحمل تمرين مشية الفلاح أوزاناً ثقيلة على الجانبين لمسافة أو زمن محدد، مجهداً القبضة وعضلات الترابيس والجذع. وهو يبني قوة الحمل الواقعية والوضعية المستقيمة والقدرة على العمل البدني.","measurement":"distance_duration","types":["Full Body","Functional"],"targets":[{"bodyTarget":"forearms","percentage":30},{"bodyTarget":"traps","percentage":25},{"bodyTarget":"core_deep","percentage":25},{"bodyTarget":"glutes","percentage":20}]},{"name":"Feet Up Bench Press (Barbell)","description":"The feet up bench press removes leg drive by lifting the feet off the floor, forcing the chest, shoulders, and triceps to do all the work. It sharpens pressing technique and gives an honest measure of upper-body strength.","descriptionAr":"يلغي البنش برس مع رفع القدمين دفع الساقين عبر إبعاد القدمين عن الأرض، مجبراً الصدر والكتفين والعضلة ثلاثية الرؤوس على أداء كامل العمل. وهو يصقل تقنية الضغط ويعطي قياساً صادقاً لقوة الجزء العلوي من الجسم.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"chest","percentage":55},{"bodyTarget":"triceps","percentage":30},{"bodyTarget":"shoulders_anterior","percentage":15}]},{"name":"Fire Hydrants","description":"Fire hydrants lift the bent knee out to the side from an all-fours position, targeting the gluteus medius and hip stabilizers. They improve hip mobility and glute activation before heavier lower-body work.","descriptionAr":"يرفع تمرين فاير هايدرنت الركبة المثنية جانبياً من وضعية الارتكاز على اليدين والركبتين، مستهدفاً العضلة الألوية الوسطى ومثبتات الورك. وهو يحسن حركية الورك وتفعيل الألوية قبل تمارين الجزء السفلي الأثقل.","measurement":"reps","types":["Leg Day","Mobility"],"targets":[{"bodyTarget":"glutes","percentage":70},{"bodyTarget":"core_deep","percentage":20},{"bodyTarget":"hip_flexors","percentage":10}]},{"name":"Floor Press (Barbell)","description":"The barbell floor press presses from the floor, cutting the range at the point where the upper arms touch down. It emphasizes the triceps and lockout strength while limiting stress on the shoulders.","descriptionAr":"يؤدى الضغط الأرضي بالبار من وضعية الاستلقاء على الأرض، حيث يتوقف المدى عند ملامسة العضدين للأرض. وهو يركز على العضلة ثلاثية الرؤوس وقوة قفل المرفقين مع الحد من الضغط على الكتفين.","measurement":"reps","types":["Push Day","Powerlifting"],"targets":[{"bodyTarget":"chest","percentage":50},{"bodyTarget":"triceps","percentage":35},{"bodyTarget":"shoulders_anterior","percentage":15}]},{"name":"Floor Press (Dumbbell)","description":"The dumbbell floor press limits the range of motion at the bottom, emphasizing the triceps and mid-range chest strength. Pressing from the floor keeps the shoulders in a supported, low-strain position.","descriptionAr":"يحد الضغط الأرضي بالدمبل من مدى الحركة في الأسفل، مركزاً على العضلة ثلاثية الرؤوس وقوة الصدر في منتصف المدى. ويبقي الضغط من الأرض الكتفين في وضعية مدعومة منخفضة الإجهاد.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"chest","percentage":50},{"bodyTarget":"triceps","percentage":35},{"bodyTarget":"shoulders_anterior","percentage":15}]},{"name":"Floor Triceps Dip","description":"The floor triceps dip presses the body up from the ground with the hands placed behind the hips, extending the elbows against body weight. It is an accessible bodyweight exercise for building triceps and shoulder strength anywhere.","descriptionAr":"يرفع تمرين الغطس الأرضي الجسم عن الأرض بوضع اليدين خلف الوركين ومد المرفقين ضد وزن الجسم. وهو تمرين متاح بوزن الجسم لبناء قوة العضلة ثلاثية الرؤوس والكتفين في أي مكان.","measurement":"reps","types":["Push Day","Calisthenics"],"targets":[{"bodyTarget":"triceps","percentage":60},{"bodyTarget":"shoulders_anterior","percentage":25},{"bodyTarget":"chest","percentage":15}]},{"name":"Flutter Kicks","description":"Flutter kicks alternate small, rapid leg raises while lying on the back with the lower back pressed into the floor. They challenge the lower abs and hip flexors to stabilize the pelvis under continuous movement.","descriptionAr":"يبادل تمرين الركلات المتقطعة رفعات ساق صغيرة وسريعة أثناء الاستلقاء على الظهر مع تثبيت أسفل الظهر على الأرض. وهو يتحدى عضلات البطن السفلية وثنيات الورك لتثبيت الحوض تحت حركة مستمرة.","measurement":"reps","types":["Core"],"targets":[{"bodyTarget":"core_abs","percentage":50},{"bodyTarget":"hip_flexors","percentage":30},{"bodyTarget":"core_deep","percentage":20}]},{"name":"Frog Jumps","description":"Frog jumps explode upward and forward from a deep squat position, developing power in the quadriceps and glutes. The repeated jumping also builds conditioning and explosive lower-body endurance.","descriptionAr":"ينطلق تمرين قفزات الضفدع للأعلى وللأمام من وضعية قرفصاء عميقة، مطوراً القوة في العضلة الرباعية والألوية. كما يبني القفز المتكرر اللياقة البدنية والتحمل الانفجاري للجزء السفلي من الجسم.","measurement":"reps","types":["Leg Day","HIIT"],"targets":[{"bodyTarget":"quadriceps","percentage":40},{"bodyTarget":"glutes","percentage":30},{"bodyTarget":"calves","percentage":15},{"bodyTarget":"hamstrings","percentage":15}]},{"name":"Frog Pumps (Dumbbell)","description":"Frog pumps drive the hips upward with the soles of the feet together and knees flared, holding a dumbbell on the hips. The foot position minimizes hamstring involvement and maximizes the glute contraction.","descriptionAr":"يدفع هذا التمرين الوركين للأعلى مع ضم باطني القدمين وفتح الركبتين للخارج وحمل دمبل على الوركين. وتقلل وضعية القدمين مشاركة أوتار الركبة وتزيد انقباض الألوية إلى الحد الأقصى.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"glutes","percentage":75},{"bodyTarget":"hamstrings","percentage":15},{"bodyTarget":"adductors","percentage":10}]},{"name":"Front Lever Hold","description":"The front lever hold keeps the body perfectly horizontal beneath a bar with straight arms, demanding extreme lat and core strength. It is a benchmark calisthenics isometric that builds total-body tension and control.","descriptionAr":"يبقي تمرين الرافعة الأمامية الجسم أفقياً تماماً أسفل العقلة مع استقامة الذراعين، متطلباً قوة هائلة في العضلة الظهرية العريضة والجذع. وهو تمرين متساوي القياس مرجعي في الكاليسثينكس يبني شد الجسم الكامل والتحكم به.","measurement":"time_hold","types":["Calisthenics","Core"],"targets":[{"bodyTarget":"lats","percentage":35},{"bodyTarget":"core_abs","percentage":30},{"bodyTarget":"core_deep","percentage":20},{"bodyTarget":"shoulders_posterior","percentage":15}]},{"name":"Front Lever Raise","description":"The front lever raise pulls the straight body from a dead hang up toward the horizontal lever position. It builds the lat and core strength required to progress toward a full front lever hold.","descriptionAr":"يسحب هذا التمرين الجسم المستقيم من وضعية التعلق الكامل نحو الوضعية الأفقية للرافعة الأمامية. وهو يبني قوة العضلة الظهرية العريضة والجذع اللازمة للتقدم نحو ثبات الرافعة الأمامية الكامل.","measurement":"reps","types":["Calisthenics","Core"],"targets":[{"bodyTarget":"lats","percentage":40},{"bodyTarget":"core_abs","percentage":30},{"bodyTarget":"shoulders_posterior","percentage":15},{"bodyTarget":"triceps","percentage":15}]},{"name":"Front Raise (Band)","description":"The band front raise lifts the arms forward against elastic tension that increases through the range, targeting the anterior deltoid. Bands provide smooth, joint-friendly resistance ideal for higher-rep shoulder work.","descriptionAr":"يرفع هذا التمرين الذراعين للأمام ضد شد مطاطي يزداد عبر مدى الحركة، مستهدفاً الكتف الأمامي. وتوفر الأحبال المطاطية مقاومة سلسة وآمنة للمفاصل تناسب تمارين الكتف عالية التكرارات.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"shoulders_anterior","percentage":70},{"bodyTarget":"shoulders_lateral","percentage":20},{"bodyTarget":"traps","percentage":10}]},{"name":"Front Raise (Barbell)","description":"The barbell front raise lifts the bar forward to shoulder height with nearly straight arms, loading both anterior deltoids together. It builds front-shoulder strength and size with simple progressive loading.","descriptionAr":"يرفع هذا التمرين البار للأمام حتى مستوى الكتفين بذراعين شبه مستقيمتين، محملاً الكتفين الأماميين معاً. وهو يبني قوة وحجم مقدمة الكتف مع سهولة زيادة الحمل التدريجي.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"shoulders_anterior","percentage":70},{"bodyTarget":"shoulders_lateral","percentage":20},{"bodyTarget":"traps","percentage":10}]},{"name":"Front Raise (Cable)","description":"The cable front raise keeps constant tension on the anterior deltoid from the bottom to the top of the arc. The cable's steady resistance profile makes it effective for strict, controlled shoulder isolation.","descriptionAr":"يحافظ الرفع الأمامي بالكابل على توتر مستمر في الكتف الأمامي من أسفل القوس إلى أعلاه. ويجعل ثبات مقاومة الكابل هذا التمرين فعالاً لعزل الكتف بشكل صارم ومنضبط.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"shoulders_anterior","percentage":70},{"bodyTarget":"shoulders_lateral","percentage":20},{"bodyTarget":"traps","percentage":10}]},{"name":"Front Raise (Dumbbell)","description":"The dumbbell front raise lifts a weight forward to about eye level, isolating the anterior deltoid one arm at a time or both together. It strengthens shoulder flexion and improves front-delt definition.","descriptionAr":"يرفع الرفع الأمامي بالدمبل الوزن للأمام حتى مستوى العينين تقريباً، معزولاً الكتف الأمامي بذراع واحدة أو بالذراعين معاً. وهو يقوي حركة ثني الكتف ويحسن تحديد مقدمة الكتف.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"shoulders_anterior","percentage":70},{"bodyTarget":"shoulders_lateral","percentage":20},{"bodyTarget":"traps","percentage":10}]},{"name":"Front Raise (Suspension)","description":"The suspension front raise leans the body back on straps and raises the arms overhead, using body weight to load the anterior deltoids. The core must brace throughout, adding a stability challenge to the shoulder work.","descriptionAr":"يميل هذا التمرين الجسم للخلف على أحزمة التعليق ثم يرفع الذراعين فوق الرأس، مستخدماً وزن الجسم لتحميل الكتفين الأماميين. ويجب أن يظل الجذع مشدوداً طوال الحركة، مما يضيف تحدي ثبات إلى عمل الكتفين.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"shoulders_anterior","percentage":60},{"bodyTarget":"shoulders_lateral","percentage":20},{"bodyTarget":"core_deep","percentage":20}]},{"name":"Full Squat","description":"The full squat descends until the hips drop below the knees, taking the quadriceps and glutes through their complete range. Training this deep improves leg strength, hip mobility, and joint resilience.","descriptionAr":"ينزل القرفصاء الكامل حتى يهبط الوركان تحت مستوى الركبتين، مما يعمل على العضلة الرباعية والألوية عبر مداهما الكامل. ويحسن التدريب بهذا العمق قوة الساقين وحركية الوركين ومتانة المفاصل.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"quadriceps","percentage":45},{"bodyTarget":"glutes","percentage":30},{"bodyTarget":"hamstrings","percentage":15},{"bodyTarget":"adductors","percentage":10}]},{"name":"Glute Bridge (Barbell)","description":"The barbell glute bridge drives the hips upward from the floor with a bar resting over the pelvis, producing a strong glute contraction at lockout. It overloads hip extension without compressing the spine vertically.","descriptionAr":"يدفع جسر الألوية بالبار الوركين للأعلى من الأرض مع استقرار البار فوق الحوض، منتجاً انقباضاً قوياً في الألوية عند قمة الحركة. وهو يزيد الحمل على مد الورك دون ضغط عمودي على العمود الفقري.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"glutes","percentage":60},{"bodyTarget":"hamstrings","percentage":25},{"bodyTarget":"core_deep","percentage":15}]},{"name":"Glute Ham Raise","description":"The glute ham raise lowers and lifts the torso by contracting the hamstrings around a fixed footplate. It is one of the most demanding knee-flexion exercises, building the hamstrings and glutes with a strong eccentric emphasis.","descriptionAr":"يخفض تمرين رفع الألوية وأوتار الركبة الجذع ثم يرفعه عبر انقباض أوتار الركبة مع تثبيت القدمين. وهو من أكثر تمارين ثني الركبة تطلباً، إذ يبني أوتار الركبة والألوية مع تركيز قوي على المرحلة السلبية.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"hamstrings","percentage":60},{"bodyTarget":"glutes","percentage":25},{"bodyTarget":"erector_spinae","percentage":15}]},{"name":"Glute Kickback (Machine)","description":"The machine glute kickback extends the hip against a resistance pad, isolating the gluteus maximus one leg at a time. The guided path makes strict glute isolation and progressive loading straightforward.","descriptionAr":"يمد تمرين ركلة الألوية على الجهاز الورك ضد وسادة مقاومة، معزولاً العضلة الألوية الكبرى بساق واحدة في كل مرة. ويجعل المسار الموجه عزل الألوية الصارم وزيادة الحمل التدريجي أمراً سهلاً.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"glutes","percentage":70},{"bodyTarget":"hamstrings","percentage":20},{"bodyTarget":"core_deep","percentage":10}]},{"name":"Glute Kickback on Floor","description":"The floor glute kickback extends one leg up and back from an all-fours position, squeezing the glute at the top. It is a simple bodyweight movement for glute activation and muscular endurance.","descriptionAr":"يمد تمرين ركلة الألوية الأرضية ساقاً واحدة للأعلى وللخلف من وضعية الارتكاز على اليدين والركبتين مع عصر الألوية في القمة. وهو حركة بسيطة بوزن الجسم لتفعيل الألوية وبناء تحملها العضلي.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"glutes","percentage":70},{"bodyTarget":"hamstrings","percentage":20},{"bodyTarget":"core_deep","percentage":10}]},{"name":"Good Morning (Barbell)","description":"The barbell good morning hinges the torso forward with the bar on the upper back, stretching and loading the hamstrings and spinal erectors. It builds hip-hinge strength that directly supports the squat and deadlift.","descriptionAr":"يثني تمرين الصباح الجيد الجذع للأمام مع استقرار البار على أعلى الظهر، ممدداً ومحملاً أوتار الركبة وعضلات ناصبة الفقار. وهو يبني قوة مفصلة الورك التي تدعم مباشرة تمريني القرفصاء والرفعة المميتة.","measurement":"reps","types":["Leg Day","Powerlifting"],"targets":[{"bodyTarget":"hamstrings","percentage":45},{"bodyTarget":"erector_spinae","percentage":30},{"bodyTarget":"glutes","percentage":25}]},{"name":"Gorilla Row (Kettlebell)","description":"The gorilla row pulls kettlebells from the floor one arm at a time while holding a deep hip hinge. It builds the upper back and lats while training the hips and core to maintain a strong, stable hinge.","descriptionAr":"يسحب تجديف الغوريلا الأثقال الحديدية من الأرض بذراع واحدة في كل مرة مع الثبات في انحناء عميق للوركين. وهو يبني أعلى الظهر والعضلة الظهرية العريضة بينما يدرب الوركين والجذع على الحفاظ على انحناء قوي وثابت.","measurement":"reps","types":["Pull Day","Functional"],"targets":[{"bodyTarget":"upper_back","percentage":40},{"bodyTarget":"lats","percentage":25},{"bodyTarget":"biceps","percentage":20},{"bodyTarget":"shoulders_posterior","percentage":15}]},{"name":"Hack Squat (Machine)","description":"The hack squat machine supports the back while the legs press through a fixed sled path, placing strong emphasis on the quadriceps. The added stability allows deep, heavy leg training with reduced balance and spinal demands.","descriptionAr":"يدعم جهاز الهاك سكوات الظهر بينما تدفع الساقان عبر مسار منزلق ثابت، مع تركيز قوي على العضلة الرباعية. ويتيح الثبات الإضافي تدريباً عميقاً وثقيلاً للساقين مع تقليل متطلبات التوازن والحمل على العمود الفقري.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"quadriceps","percentage":55},{"bodyTarget":"glutes","percentage":25},{"bodyTarget":"hamstrings","percentage":12},{"bodyTarget":"calves","percentage":8}]},{"name":"Hammer Curl (Band)","description":"The band hammer curl flexes the elbow with a neutral grip against elastic tension that rises through the range. It strengthens the biceps, brachialis, and forearms with smooth, joint-friendly resistance.","descriptionAr":"يثني تمرين هامر كيرل بالحبل المطاطي المرفق بقبضة محايدة ضد شد مرن يزداد عبر مدى الحركة. وهو يقوي العضلة ذات الرأسين والعضلة العضدية والساعدين بمقاومة سلسة وآمنة للمفاصل.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"biceps","percentage":55},{"bodyTarget":"forearms","percentage":45}]},{"name":"Hammer Curl (Cable)","description":"The cable hammer curl, usually performed with a rope, keeps constant neutral-grip tension on the biceps and brachioradialis. The cable resists through the entire range, including the bottom stretch position.","descriptionAr":"يحافظ تمرين هامر كيرل بالكابل، الذي يؤدى عادة بالحبل، على توتر مستمر بقبضة محايدة في العضلة ذات الرأسين والعضدية الكعبرية. ويقاوم الكابل عبر المدى الكامل بما في ذلك وضعية التمدد في الأسفل.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"biceps","percentage":55},{"bodyTarget":"forearms","percentage":45}]},{"name":"Hammer Curl (Dumbbell)","description":"The dumbbell hammer curl lifts the weight with a thumbs-up neutral grip, shifting emphasis toward the brachialis and brachioradialis. It builds arm thickness and grip strength alongside the biceps.","descriptionAr":"يرفع تمرين هامر كيرل بالدمبل الوزن بقبضة محايدة مع اتجاه الإبهام للأعلى، ناقلاً التركيز نحو العضلة العضدية والعضدية الكعبرية. وهو يبني سماكة الذراع وقوة القبضة إلى جانب العضلة ذات الرأسين.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"biceps","percentage":55},{"bodyTarget":"forearms","percentage":45}]},{"name":"Hang Snatch","description":"The hang snatch pulls the bar explosively from above the knees to overhead in one motion, caught with locked arms. Starting from the hang position emphasizes pure hip power and speed under the bar.","descriptionAr":"يسحب الخطف المعلق البار بشكل انفجاري من فوق الركبتين إلى فوق الرأس في حركة واحدة مع استقباله بذراعين مقفلتين. ويؤكد البدء من وضعية التعليق على قوة الوركين الخالصة وسرعة النزول تحت البار.","measurement":"reps","types":["Olympic Lifting","Full Body"],"targets":[{"bodyTarget":"hamstrings","percentage":30},{"bodyTarget":"glutes","percentage":25},{"bodyTarget":"traps","percentage":25},{"bodyTarget":"shoulders_anterior","percentage":20}]},{"name":"Heel Taps","description":"Heel taps lift the shoulders slightly off the floor and reach side to side to touch each heel while lying on the back. The alternating lateral reach targets the obliques along with the upper abs.","descriptionAr":"يرفع تمرين لمس الكعبين الكتفين قليلاً عن الأرض مع الميل يميناً ويساراً للمس كل كعب أثناء الاستلقاء على الظهر. ويستهدف هذا الميل الجانبي المتناوب العضلات المائلة إلى جانب عضلات البطن العلوية.","measurement":"reps","types":["Core"],"targets":[{"bodyTarget":"core_abs","percentage":50},{"bodyTarget":"obliques","percentage":40},{"bodyTarget":"core_deep","percentage":10}]},{"name":"Hex Press (Dumbbell)","description":"The hex press presses hexagonal dumbbells held tightly together from the chest to lockout, keeping constant inner-chest tension. The pressed-together position increases pec activation while keeping the shoulders in a comfortable path.","descriptionAr":"يضغط تمرين الهيكس برس دمبلين سداسيين ملتصقين بإحكام من الصدر حتى قفل الذراعين، محافظاً على توتر مستمر في الجزء الداخلي من الصدر. وتزيد وضعية الضم تفعيل عضلات الصدر مع إبقاء الكتفين في مسار مريح.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"chest","percentage":65},{"bodyTarget":"triceps","percentage":25},{"bodyTarget":"shoulders_anterior","percentage":10}]},{"name":"High Knee Skips","description":"High knee skips drive one knee up powerfully with each skip, combining rhythm, elevation, and hip-flexor drive. They raise the heart rate while developing coordination and explosive leg turnover.","descriptionAr":"يدفع تمرين الحجل برفع الركبتين ركبة واحدة للأعلى بقوة مع كل حجلة، جامعاً بين الإيقاع والارتفاع ودفع ثنيات الورك. وهو يرفع معدل ضربات القلب بينما يطور التناسق وسرعة تبديل الساقين الانفجارية.","measurement":"reps","types":["Cardio","HIIT"],"targets":[{"bodyTarget":"cardiovascular","percentage":35},{"bodyTarget":"hip_flexors","percentage":25},{"bodyTarget":"quadriceps","percentage":20},{"bodyTarget":"calves","percentage":20}]},{"name":"HIIT","description":"High-intensity interval training alternates short bursts of near-maximal effort with brief recovery periods. It improves cardiovascular fitness and conditioning in a fraction of the time of steady-state cardio.","descriptionAr":"يبادل التدريب المتقطع عالي الشدة بين فترات قصيرة من الجهد شبه الأقصى وفترات استشفاء وجيزة. وهو يحسن اللياقة القلبية الوعائية والتكيف البدني في جزء يسير من وقت تمارين الكارديو الثابتة.","measurement":"distance_duration","types":["HIIT","Cardio"],"targets":[{"bodyTarget":"cardiovascular","percentage":55},{"bodyTarget":"endurance","percentage":30},{"bodyTarget":"quadriceps","percentage":15}]},{"name":"Hiking","description":"Hiking sustains an elevated heart rate over varied terrain, building aerobic endurance and leg strength together. Inclines in particular work the quadriceps, glutes, and calves over long durations.","descriptionAr":"يحافظ المشي الجبلي على معدل ضربات قلب مرتفع عبر تضاريس متنوعة، بانياً التحمل الهوائي وقوة الساقين معاً. وتعمل المرتفعات بشكل خاص على العضلة الرباعية والألوية وربلتي الساقين لفترات طويلة.","measurement":"distance_duration","types":["Cardio"],"targets":[{"bodyTarget":"cardiovascular","percentage":45},{"bodyTarget":"endurance","percentage":25},{"bodyTarget":"quadriceps","percentage":15},{"bodyTarget":"calves","percentage":15}]},{"name":"Hip Abduction (Cable)","description":"Standing with a cable cuff at the ankle, you raise one leg out to the side against resistance while keeping the torso upright. It strengthens the gluteus medius and minimus, improving hip stability and knee alignment during walking, running, and squatting.","descriptionAr":"أثناء الوقوف مع تثبيت رباط الكابل حول الكاحل، ترفع ساقًا واحدة إلى الجانب ضد المقاومة مع إبقاء الجذع مستقيمًا. يقوي هذا التمرين العضلة الألوية الوسطى والصغرى، مما يحسن ثبات الورك ومحاذاة الركبة أثناء المشي والجري والقرفصاء.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"glutes","percentage":85},{"bodyTarget":"core_deep","percentage":15}]},{"name":"Hip Adduction (Cable)","description":"With the cable attached at the ankle, you pull the working leg across the midline of the body in a controlled sweep. It isolates the inner-thigh adductor group, building strength that supports hip stability and side-to-side movement control.","descriptionAr":"مع تثبيت الكابل عند الكاحل، تسحب الساق العاملة عبر خط منتصف الجسم بحركة منضبطة. يعزل هذا التمرين عضلات الفخذ الداخلية المقرِّبة، فيبني قوة تدعم ثبات الورك والتحكم في الحركات الجانبية.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"adductors","percentage":85},{"bodyTarget":"hip_flexors","percentage":15}]},{"name":"Hip Thrust (Barbell)","description":"With your upper back on a bench and a barbell across the hips, you drive the hips upward until the torso is parallel to the floor. It is one of the most effective ways to load the glutes directly, building hip extension strength for sprinting, jumping, and heavy lifts.","descriptionAr":"مع استناد أعلى الظهر إلى مقعد ووضع بار الحديد فوق الوركين، تدفع الوركين إلى الأعلى حتى يصبح الجذع موازيًا للأرض. يُعد من أكثر التمارين فعالية لتحميل العضلات الألوية مباشرة، إذ يبني قوة بسط الورك اللازمة للعدو والقفز والرفعات الثقيلة.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"glutes","percentage":70},{"bodyTarget":"hamstrings","percentage":20},{"bodyTarget":"quadriceps","percentage":10}]},{"name":"Hip Thrust (Dumbbell)","description":"Resting your upper back on a bench with a dumbbell placed over the hips, you extend the hips upward and squeeze the glutes at the top. The lighter dumbbell load makes it a convenient way to practice the movement pattern and build glute strength with strict form.","descriptionAr":"مع استناد أعلى الظهر إلى مقعد ووضع دمبل فوق الوركين، تبسط الوركين إلى الأعلى وتضغط العضلات الألوية عند القمة. يجعل الحمل الأخف للدمبل هذا التمرين وسيلة عملية لإتقان نمط الحركة وبناء قوة الألوية بأداء دقيق.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"glutes","percentage":70},{"bodyTarget":"hamstrings","percentage":20},{"bodyTarget":"quadriceps","percentage":10}]},{"name":"Hip Thrust (Machine)","description":"Seated in a dedicated machine with a padded belt over the hips, you drive the hips forward and up against the resistance. The guided setup removes balance demands, letting you load the glutes heavily and safely through a full range of hip extension.","descriptionAr":"جالسًا في جهاز مخصص مع حزام مبطن فوق الوركين، تدفع الوركين إلى الأمام والأعلى ضد المقاومة. يلغي المسار الموجّه متطلبات التوازن، مما يتيح تحميل العضلات الألوية بأوزان كبيرة وبأمان عبر مدى كامل لبسط الورك.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"glutes","percentage":70},{"bodyTarget":"hamstrings","percentage":20},{"bodyTarget":"quadriceps","percentage":10}]},{"name":"Hip Thrust (Smith Machine)","description":"With your upper back on a bench and the Smith machine bar over the hips, you thrust upward along the bar's fixed vertical path. The fixed track makes setup and balance easier, so you can focus on driving through the heels and fully contracting the glutes.","descriptionAr":"مع استناد أعلى الظهر إلى مقعد ووضع بار جهاز سميث فوق الوركين، تدفع الوركين إلى الأعلى على المسار العمودي الثابت للبار. يسهّل المسار الثابت التجهيز والتوازن، فيتيح لك التركيز على الدفع بالكعبين والانقباض الكامل للعضلات الألوية.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"glutes","percentage":70},{"bodyTarget":"hamstrings","percentage":20},{"bodyTarget":"quadriceps","percentage":10}]},{"name":"Hollow Rock","description":"Lying in a hollow-body position with arms and legs lifted off the floor, you rock back and forth while keeping the lower back pressed into the ground. It builds a rigid, braced midline that transfers directly to gymnastics skills and heavy barbell lifts.","descriptionAr":"مستلقيًا في وضعية الجسم المقوّس مع رفع الذراعين والساقين عن الأرض، تتأرجح إلى الأمام والخلف مع إبقاء أسفل الظهر ملتصقًا بالأرض. يبني هذا التمرين ثباتًا صلبًا في منتصف الجسم ينتقل أثره مباشرة إلى مهارات الجمباز ورفعات البار الثقيلة.","measurement":"reps","types":["Core","Calisthenics"],"targets":[{"bodyTarget":"core_abs","percentage":70},{"bodyTarget":"hip_flexors","percentage":20},{"bodyTarget":"core_deep","percentage":10}]},{"name":"Incline Bench Press (Barbell)","description":"Pressing a barbell from a bench set at roughly 30 to 45 degrees shifts the emphasis toward the upper, clavicular fibers of the chest. It builds pressing strength across the chest, front deltoids, and triceps while allowing heavy progressive loading.","descriptionAr":"يؤدي دفع بار الحديد من مقعد مائل بزاوية 30 إلى 45 درجة تقريبًا إلى نقل التركيز نحو الألياف العلوية الترقوية للصدر. يبني هذا التمرين قوة الدفع في الصدر والكتف الأمامي والعضلة ثلاثية الرؤوس مع إتاحة التحميل التدريجي بأوزان كبيرة.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"chest","percentage":60},{"bodyTarget":"shoulders_anterior","percentage":25},{"bodyTarget":"triceps","percentage":15}]},{"name":"Incline Bench Press (Dumbbell)","description":"Pressing dumbbells from an incline bench targets the upper chest while each arm works independently through a deeper range of motion. It corrects side-to-side strength imbalances and demands extra shoulder stability compared with the barbell version.","descriptionAr":"يستهدف دفع الدمبل من مقعد مائل الجزء العلوي من الصدر بينما تعمل كل ذراع بشكل مستقل عبر مدى حركة أعمق. يصحح هذا التمرين فروق القوة بين الجانبين ويتطلب ثباتًا إضافيًا في الكتف مقارنة بنسخة بار الحديد.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"chest","percentage":60},{"bodyTarget":"shoulders_anterior","percentage":25},{"bodyTarget":"triceps","percentage":15}]},{"name":"Incline Bench Press (Smith Machine)","description":"Pressing along the Smith machine's fixed bar path from an incline bench emphasizes the upper chest with reduced balance demands. The guided track lets you push close to failure more safely, making it useful for controlled overload of the chest, front delts, and triceps.","descriptionAr":"يركز الدفع على المسار الثابت لجهاز سميث من مقعد مائل على الجزء العلوي من الصدر مع تقليل متطلبات التوازن. يتيح المسار الموجّه الاقتراب من الإجهاد الكامل بأمان أكبر، مما يجعله مفيدًا للتحميل المنضبط على الصدر والكتف الأمامي والعضلة ثلاثية الرؤوس.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"chest","percentage":60},{"bodyTarget":"shoulders_anterior","percentage":25},{"bodyTarget":"triceps","percentage":15}]},{"name":"Incline Chest Fly (Dumbbell)","description":"Lying on an incline bench with a slight bend in the elbows, you open the dumbbells in a wide arc and squeeze them back together above the chest. It isolates the upper chest through a long stretch with minimal triceps involvement, making it a strong hypertrophy accessory.","descriptionAr":"مستلقيًا على مقعد مائل مع انحناء بسيط في المرفقين، تفتح الدمبلين في قوس واسع ثم تضمهما مجددًا فوق الصدر. يعزل هذا التمرين الجزء العلوي من الصدر عبر إطالة كبيرة مع مشاركة ضئيلة للعضلة ثلاثية الرؤوس، ما يجعله تمرينًا مساعدًا فعالًا للتضخيم العضلي.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"chest","percentage":80},{"bodyTarget":"shoulders_anterior","percentage":20}]},{"name":"Incline Chest Press (Machine)","description":"Seated in a machine with handles set at an upward pressing angle, you push the weight away until the arms are extended. The fixed path targets the upper chest, front delts, and triceps while minimizing stabilizer demands, which suits beginners and high-fatigue finishing sets.","descriptionAr":"جالسًا في جهاز بمقابض موجهة بزاوية دفع صاعدة، تدفع الوزن بعيدًا حتى تمتد الذراعان. يستهدف المسار الثابت الجزء العلوي من الصدر والكتف الأمامي والعضلة ثلاثية الرؤوس مع تقليل الحاجة إلى عضلات التثبيت، ما يناسب المبتدئين وجولات الإنهاء عند التعب الشديد.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"chest","percentage":60},{"bodyTarget":"shoulders_anterior","percentage":25},{"bodyTarget":"triceps","percentage":15}]},{"name":"Incline Push Ups","description":"With your hands elevated on a bench, bar, or box, you perform push-ups at a reduced percentage of body weight. It is an accessible way to build chest, shoulder, and triceps pressing strength while training the core to hold a straight body line.","descriptionAr":"مع رفع اليدين على مقعد أو بار أو صندوق، تؤدي تمرين الضغط بنسبة أقل من وزن الجسم. إنه وسيلة سهلة المنال لبناء قوة الدفع في الصدر والكتفين والعضلة ثلاثية الرؤوس، مع تدريب عضلات الجذع على الحفاظ على استقامة الجسم.","measurement":"reps","types":["Push Day","Calisthenics"],"targets":[{"bodyTarget":"chest","percentage":55},{"bodyTarget":"triceps","percentage":25},{"bodyTarget":"shoulders_anterior","percentage":15},{"bodyTarget":"core_abs","percentage":5}]},{"name":"Iso-Lateral Chest Press (Machine)","description":"Each arm presses an independent handle, so both sides of the chest must produce force on their own. This design exposes and corrects left-right strength imbalances while training the chest, front delts, and triceps through a converging press path.","descriptionAr":"تدفع كل ذراع مقبضًا مستقلًا، فيضطر كل جانب من الصدر إلى إنتاج القوة بمفرده. يكشف هذا التصميم فروق القوة بين الجانبين ويصححها، مع تدريب الصدر والكتف الأمامي والعضلة ثلاثية الرؤوس عبر مسار دفع متقارب.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"chest","percentage":65},{"bodyTarget":"shoulders_anterior","percentage":20},{"bodyTarget":"triceps","percentage":15}]},{"name":"Iso-Lateral High Row (Machine)","description":"Pulling independent handles from a high position down and back toward the ribs combines a pulldown and a row in one motion. It emphasizes the lats with help from the biceps and upper back, and the unilateral arms prevent a stronger side from taking over.","descriptionAr":"يجمع سحب المقابض المستقلة من وضع مرتفع إلى الأسفل والخلف باتجاه الأضلاع بين السحب العلوي والتجديف في حركة واحدة. يركز على العضلة الظهرية العريضة بمساعدة العضلة ذات الرأسين وأعلى الظهر، ويمنع العمل الأحادي للذراعين هيمنة الجانب الأقوى.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"lats","percentage":60},{"bodyTarget":"biceps","percentage":20},{"bodyTarget":"upper_back","percentage":10},{"bodyTarget":"shoulders_posterior","percentage":10}]},{"name":"Iso-Lateral Low Row","description":"Rowing independent handles from a low angle toward the waist targets the mid and upper back with each arm working alone. The chest-supported, unilateral setup builds back thickness and rowing strength while eliminating momentum and lower-back strain.","descriptionAr":"يستهدف تجديف المقابض المستقلة من زاوية منخفضة باتجاه الخصر منتصف الظهر وأعلاه مع عمل كل ذراع بمفردها. يبني الوضع المدعوم بالصدر والأحادي الجانب سماكة الظهر وقوة التجديف مع إلغاء الاندفاع وتقليل الإجهاد على أسفل الظهر.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"upper_back","percentage":55},{"bodyTarget":"lats","percentage":20},{"bodyTarget":"biceps","percentage":15},{"bodyTarget":"shoulders_posterior","percentage":10}]},{"name":"Iso-Lateral Row (Machine)","description":"Seated against a chest pad, you row two independent handles back toward the torso, driving the elbows behind the body. It develops the upper back and lats with balanced input from each side, making it a staple for building back thickness with strict form.","descriptionAr":"جالسًا مستندًا إلى وسادة صدرية، تسحب مقبضين مستقلين نحو الجذع مع دفع المرفقين خلف الجسم. يطور هذا التمرين أعلى الظهر والعضلة الظهرية العريضة بمشاركة متوازنة من كل جانب، ما يجعله أساسيًا لبناء سماكة الظهر بأداء منضبط.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"upper_back","percentage":50},{"bodyTarget":"lats","percentage":25},{"bodyTarget":"biceps","percentage":15},{"bodyTarget":"shoulders_posterior","percentage":10}]},{"name":"Jack Knife (Suspension)","description":"From a plank position with your feet in suspension straps, you draw the knees toward the chest and extend back out under control. The unstable straps force the abs, hip flexors, and deep core to work continuously to keep the hips from sagging.","descriptionAr":"من وضعية البلانك مع وضع القدمين في أحزمة التعليق، تسحب الركبتين نحو الصدر ثم تمدهما مجددًا بتحكم. تجبر الأحزمة غير المستقرة عضلات البطن ومثنيات الورك والعضلات العميقة للجذع على العمل المتواصل لمنع هبوط الوركين.","measurement":"reps","types":["Core","Calisthenics"],"targets":[{"bodyTarget":"core_abs","percentage":60},{"bodyTarget":"hip_flexors","percentage":25},{"bodyTarget":"core_deep","percentage":15}]},{"name":"Jackknife Sit Up","description":"Lying flat, you simultaneously raise the straight legs and the torso, reaching your hands toward your feet to form a V shape. It trains the entire abdominal wall together with the hip flexors through a large, dynamic range of motion.","descriptionAr":"مستلقيًا على الأرض، ترفع الساقين المستقيمتين والجذع في آن واحد مادًّا يديك نحو قدميك لتشكيل حرف V. يدرب هذا التمرين جدار البطن بأكمله مع مثنيات الورك عبر مدى حركة واسع وديناميكي.","measurement":"reps","types":["Core","Calisthenics"],"targets":[{"bodyTarget":"core_abs","percentage":65},{"bodyTarget":"hip_flexors","percentage":25},{"bodyTarget":"core_deep","percentage":10}]},{"name":"JM Press (Barbell)","description":"A hybrid of a close-grip bench press and a skull crusher, you lower the bar toward the chin with the elbows held forward, then press back up. It loads the triceps heavily through their strongest range, building lockout strength for the bench press and overhead work.","descriptionAr":"في هذا المزيج بين تمرين الضغط بقبضة ضيقة وتمرين كسارة الجمجمة، تُنزل البار نحو الذقن مع إبقاء المرفقين متجهين للأمام ثم تدفعه للأعلى. يحمّل التمرين العضلة ثلاثية الرؤوس بشدة في أقوى مدى حركتها، فيبني قوة الإغلاق لتمرين الضغط والرفعات فوق الرأس.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"triceps","percentage":75},{"bodyTarget":"chest","percentage":15},{"bodyTarget":"shoulders_anterior","percentage":10}]},{"name":"Jump Shrug","description":"Holding a bar at the hips, you explosively extend the hips, knees, and ankles and finish with a powerful shrug as the feet leave the floor. It teaches the triple-extension power position used in Olympic lift pulls while building explosive traps, legs, and hips.","descriptionAr":"ممسكًا بالبار عند الوركين، تبسط الوركين والركبتين والكاحلين بشكل انفجاري وتُنهي الحركة بهزّ قوي للكتفين مع مغادرة القدمين للأرض. يعلّم هذا التمرين وضعية القوة ثلاثية البسط المستخدمة في سحبات الرفعات الأولمبية، ويبني قوة انفجارية في العضلة شبه المنحرفة والساقين والوركين.","measurement":"reps","types":["Full Body","Olympic Lifting"],"targets":[{"bodyTarget":"traps","percentage":35},{"bodyTarget":"quadriceps","percentage":25},{"bodyTarget":"glutes","percentage":20},{"bodyTarget":"calves","percentage":20}]},{"name":"Jump Squat","description":"You descend into a squat and explode upward into a vertical jump, landing softly and repeating. This plyometric movement develops lower-body power and rate of force development, improving sprinting and jumping performance.","descriptionAr":"تهبط في وضعية القرفصاء ثم تنفجر إلى الأعلى في قفزة عمودية، وتهبط بهدوء وتكرر الحركة. يطور هذا التمرين البليومتري قوة الجزء السفلي من الجسم وسرعة إنتاج القوة، فيحسن أداء العدو والقفز.","measurement":"reps","types":["Leg Day","HIIT"],"targets":[{"bodyTarget":"quadriceps","percentage":50},{"bodyTarget":"glutes","percentage":25},{"bodyTarget":"calves","percentage":15},{"bodyTarget":"hamstrings","percentage":10}]},{"name":"Jumping Lunge","description":"From a lunge position, you jump explosively and switch legs in mid-air, landing in a lunge on the opposite side. It combines single-leg strength with plyometric power, raising the heart rate while challenging balance and coordination.","descriptionAr":"من وضعية الاندفاع، تقفز بقوة وتبدّل الساقين في الهواء لتهبط في اندفاع على الجانب الآخر. يجمع هذا التمرين بين قوة الساق الواحدة والقدرة البليومترية، ويرفع معدل ضربات القلب مع تحدي التوازن والتناسق.","measurement":"reps","types":["Leg Day","HIIT"],"targets":[{"bodyTarget":"quadriceps","percentage":50},{"bodyTarget":"glutes","percentage":25},{"bodyTarget":"hamstrings","percentage":15},{"bodyTarget":"calves","percentage":10}]},{"name":"Kettlebell Around the World","description":"You pass a kettlebell in a continuous circle around your waist, handing it from one hand to the other in front and behind the body. It builds grip and shoulder control while the core works to resist the rotation created by the moving load.","descriptionAr":"تمرر الكرة الحديدية في دائرة متواصلة حول خصرك، ناقلًا إياها من يد إلى أخرى أمام الجسم وخلفه. يبني هذا التمرين قوة القبضة والتحكم في الكتف، بينما تعمل عضلات الجذع على مقاومة الدوران الناتج عن الحمل المتحرك.","measurement":"reps","types":["Functional","Core"],"targets":[{"bodyTarget":"shoulders_anterior","percentage":50},{"bodyTarget":"core_abs","percentage":20},{"bodyTarget":"forearms","percentage":15},{"bodyTarget":"shoulders_lateral","percentage":15}]},{"name":"Kettlebell Clean","description":"With an explosive hip drive, you swing the kettlebell from between the legs and guide it smoothly into the rack position at the shoulder. It develops hip power, timing, and grip while teaching the bell to travel close to the body without banging the forearm.","descriptionAr":"بدفعة انفجارية من الوركين، تؤرجح الكرة الحديدية من بين الساقين وتوجهها بسلاسة إلى وضعية الاستناد عند الكتف. يطور هذا التمرين قوة الوركين والتوقيت وقبضة اليد، ويعلّمك إبقاء الكرة قريبة من الجسم دون ارتطامها بالساعد.","measurement":"reps","types":["Full Body","Functional"],"targets":[{"bodyTarget":"glutes","percentage":30},{"bodyTarget":"hamstrings","percentage":25},{"bodyTarget":"traps","percentage":25},{"bodyTarget":"quadriceps","percentage":20}]},{"name":"Kettlebell Curl","description":"You curl a kettlebell from full arm extension up toward the shoulder while keeping the elbow pinned to your side. The offset center of mass hangs below the handle, adding a constant grip and wrist challenge on top of the biceps work.","descriptionAr":"تثني الذراع بالكرة الحديدية من الامتداد الكامل إلى أعلى باتجاه الكتف مع تثبيت المرفق إلى جانب الجسم. يقع مركز ثقل الكرة أسفل المقبض، ما يضيف تحديًا مستمرًا للقبضة والمعصم فوق عمل العضلة ذات الرأسين.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"biceps","percentage":80},{"bodyTarget":"forearms","percentage":20}]},{"name":"Kettlebell Goblet Squat","description":"Holding a kettlebell at chest height with both hands, you squat down between the knees while keeping the torso tall. The front-loaded weight acts as a counterbalance that encourages upright squat depth, making it excellent for teaching mechanics and building leg strength.","descriptionAr":"ممسكًا بالكرة الحديدية عند مستوى الصدر بكلتا اليدين، تهبط في القرفصاء بين الركبتين مع إبقاء الجذع منتصبًا. يعمل الوزن الأمامي كثقل موازن يساعد على النزول العميق بجذع مستقيم، ما يجعله ممتازًا لتعليم ميكانيكا القرفصاء وبناء قوة الساقين.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"quadriceps","percentage":50},{"bodyTarget":"glutes","percentage":30},{"bodyTarget":"core_abs","percentage":10},{"bodyTarget":"hamstrings","percentage":10}]},{"name":"Kettlebell Halo","description":"Holding the kettlebell upside down by the horns, you circle it slowly around your head while keeping the ribs down and the trunk still. It improves shoulder mobility and control through a full circular range while the core resists the shifting load.","descriptionAr":"ممسكًا بالكرة الحديدية مقلوبة من قرنيها، تديرها ببطء حول رأسك مع إبقاء القفص الصدري منخفضًا والجذع ثابتًا. يحسّن هذا التمرين مرونة الكتف والتحكم فيه عبر مدى دائري كامل، بينما تقاوم عضلات الجذع الحمل المتنقل.","measurement":"reps","types":["Mobility","Functional"],"targets":[{"bodyTarget":"shoulders_anterior","percentage":45},{"bodyTarget":"shoulders_lateral","percentage":20},{"bodyTarget":"core_abs","percentage":20},{"bodyTarget":"triceps","percentage":15}]},{"name":"Kettlebell High Pull","description":"From a hip hinge, you snap the hips forward and pull the kettlebell up to chest height with the elbow driving high and back. It blends the ballistic hip power of a swing with an upper-body pull, developing explosive strength through the posterior chain, traps, and shoulders.","descriptionAr":"من وضعية انثناء الورك، تدفع الوركين للأمام بقوة وتسحب الكرة الحديدية إلى مستوى الصدر مع رفع المرفق عاليًا وإلى الخلف. يمزج هذا التمرين بين قوة الوركين القذفية في المرجحة وسحبة الجزء العلوي، فيطور القوة الانفجارية في السلسلة الخلفية والعضلة شبه المنحرفة والكتفين.","measurement":"reps","types":["Full Body","Functional"],"targets":[{"bodyTarget":"traps","percentage":30},{"bodyTarget":"glutes","percentage":25},{"bodyTarget":"hamstrings","percentage":25},{"bodyTarget":"shoulders_lateral","percentage":20}]},{"name":"Kettlebell Shoulder Press","description":"From the rack position at the shoulder, you press the kettlebell strictly overhead until the arm locks out. The bell's offset weight demands extra shoulder stability and wrist alignment, building strong, controlled overhead pressing.","descriptionAr":"من وضعية الاستناد عند الكتف، تدفع الكرة الحديدية فوق الرأس بدقة حتى تنغلق الذراع بالكامل. يتطلب مركز الثقل غير المتمركز للكرة ثباتًا إضافيًا في الكتف ومحاذاة سليمة للمعصم، فيبني دفعًا قويًا ومنضبطًا فوق الرأس.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"shoulders_anterior","percentage":55},{"bodyTarget":"triceps","percentage":25},{"bodyTarget":"shoulders_lateral","percentage":15},{"bodyTarget":"core_abs","percentage":5}]},{"name":"Kettlebell Snatch","description":"In one continuous explosive motion, you swing the kettlebell from between the legs to a full lockout overhead, punching through at the top. It is a demanding total-body power exercise that builds hip drive, shoulder stability, grip, and serious conditioning.","descriptionAr":"في حركة انفجارية واحدة متواصلة، تؤرجح الكرة الحديدية من بين الساقين حتى الانغلاق الكامل فوق الرأس مع دفع اليد عبر المقبض في القمة. إنه تمرين قوة شامل ومتطلب يبني دفع الوركين وثبات الكتف وقوة القبضة ولياقة عالية.","measurement":"reps","types":["Full Body","Functional","HIIT"],"targets":[{"bodyTarget":"glutes","percentage":30},{"bodyTarget":"hamstrings","percentage":25},{"bodyTarget":"shoulders_anterior","percentage":25},{"bodyTarget":"traps","percentage":20}]},{"name":"Kettlebell Turkish Get Up","description":"Starting on your back with the kettlebell locked out overhead, you move through a precise sequence of positions to standing, then reverse back down. It trains full-body coordination, shoulder stability, and core control better than almost any single exercise.","descriptionAr":"بدءًا من الاستلقاء على الظهر مع تثبيت الكرة الحديدية فوق الرأس، تتحرك عبر تسلسل دقيق من الوضعيات حتى الوقوف ثم تعكس المسار نزولًا. يدرب هذا التمرين تناسق الجسم بأكمله وثبات الكتف والتحكم في الجذع أفضل من أي تمرين منفرد تقريبًا.","measurement":"reps","types":["Full Body","Functional"],"targets":[{"bodyTarget":"core_abs","percentage":30},{"bodyTarget":"shoulders_anterior","percentage":25},{"bodyTarget":"quadriceps","percentage":25},{"bodyTarget":"glutes","percentage":20}]},{"name":"Kipping Pull Up","description":"Using a rhythmic swing between arch and hollow body positions, you generate momentum that helps drive the chin over the bar. It allows higher-volume pulling for conditioning workouts while still taxing the lats, biceps, and core, though it requires solid strict pull-up strength first.","descriptionAr":"باستخدام تأرجح إيقاعي بين وضعية التقوس ووضعية الجسم المقعّر، تولّد زخمًا يساعد على رفع الذقن فوق البار. يتيح هذا الأسلوب أداء عدد أكبر من عدّات السحب في تمارين اللياقة مع إجهاد العضلة الظهرية العريضة وذات الرأسين والجذع، لكنه يتطلب أولًا قوة جيدة في العقلة الصارمة.","measurement":"reps","types":["Pull Day","Calisthenics","CrossFit / WOD"],"targets":[{"bodyTarget":"lats","percentage":55},{"bodyTarget":"biceps","percentage":20},{"bodyTarget":"core_abs","percentage":15},{"bodyTarget":"shoulders_posterior","percentage":10}]},{"name":"Knee Raise Parallel Bars","description":"Supporting yourself on parallel bars with the arms locked, you raise the knees toward the chest and lower them under control. It targets the lower abdominal region and hip flexors while the shoulders and trunk stay braced against swinging.","descriptionAr":"مستندًا على المتوازي مع قفل الذراعين، ترفع الركبتين نحو الصدر ثم تخفضهما بتحكم. يستهدف هذا التمرين المنطقة السفلية من عضلات البطن ومثنيات الورك، بينما يبقى الكتفان والجذع مشدودين لمنع التأرجح.","measurement":"reps","types":["Core","Calisthenics"],"targets":[{"bodyTarget":"core_abs","percentage":55},{"bodyTarget":"hip_flexors","percentage":35},{"bodyTarget":"core_deep","percentage":10}]},{"name":"Kneeling Pulldown (band)","description":"Kneeling under a band anchored overhead, you pull the band down toward the upper chest while keeping the torso tall. It replicates the lat pulldown pattern with accommodating band resistance, making it a practical option for home training and warm-ups.","descriptionAr":"جاثيًا تحت حزام مطاطي مثبت في الأعلى، تسحب الحزام إلى الأسفل نحو أعلى الصدر مع إبقاء الجذع منتصبًا. يحاكي هذا التمرين نمط السحب العلوي بمقاومة مطاطية متدرجة، ما يجعله خيارًا عمليًا للتدريب المنزلي والإحماء.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"lats","percentage":60},{"bodyTarget":"biceps","percentage":20},{"bodyTarget":"upper_back","percentage":10},{"bodyTarget":"shoulders_posterior","percentage":10}]},{"name":"Kneeling Push Up","description":"Performed with the knees on the floor, this push-up variation shortens the lever arm and reduces the load on the upper body. It lets beginners train the chest, shoulders, and triceps through a full range of motion while progressing toward standard push-ups.","descriptionAr":"يؤدى هذا التنويع من تمرين الضغط مع وضع الركبتين على الأرض، ما يقصّر ذراع الرافعة ويخفف الحمل على الجزء العلوي. يتيح للمبتدئين تدريب الصدر والكتفين والعضلة ثلاثية الرؤوس عبر مدى حركة كامل مع التدرج نحو تمرين الضغط الكامل.","measurement":"reps","types":["Push Day","Calisthenics"],"targets":[{"bodyTarget":"chest","percentage":60},{"bodyTarget":"triceps","percentage":25},{"bodyTarget":"shoulders_anterior","percentage":15}]},{"name":"L-Sit Hold","description":"Supporting your body on straight arms, you hold both legs extended straight out in front so they form an L with the torso. This isometric hold demands exceptional abdominal and hip flexor strength along with triceps and shoulder support, and is a foundational gymnastics position.","descriptionAr":"مستندًا على ذراعين مستقيمتين، تثبّت الساقين ممدودتين أمامك بحيث تشكلان حرف L مع الجذع. يتطلب هذا الثبات المتساوي القياس قوة استثنائية في عضلات البطن ومثنيات الورك مع دعم من العضلة ثلاثية الرؤوس والكتفين، وهو وضعية أساسية في الجمباز.","measurement":"time_hold","types":["Core","Calisthenics"],"targets":[{"bodyTarget":"core_abs","percentage":45},{"bodyTarget":"hip_flexors","percentage":30},{"bodyTarget":"triceps","percentage":15},{"bodyTarget":"core_deep","percentage":10}]},{"name":"Landmine 180","description":"Holding the end of a landmine bar with extended arms, you sweep it in an arc from one hip to the other while pivoting through the trunk. It trains rotational power and oblique strength, which transfer directly to throwing, striking, and swinging sports.","descriptionAr":"ممسكًا بطرف بار اللاندماين بذراعين ممدودتين، تحركه في قوس من ورك إلى آخر مع دوران الجذع. يدرب هذا التمرين القوة الدورانية وعضلات البطن الجانبية، وينتقل أثره مباشرة إلى رياضات الرمي واللكم والتأرجح.","measurement":"reps","types":["Core","Functional"],"targets":[{"bodyTarget":"obliques","percentage":50},{"bodyTarget":"core_abs","percentage":30},{"bodyTarget":"shoulders_anterior","percentage":20}]},{"name":"Landmine Row","description":"Straddling or standing beside a landmine bar, you hinge at the hips and row the loaded end toward your torso. The bar's arcing path provides a stable, joint-friendly rowing angle that builds upper-back and lat thickness with heavy loads.","descriptionAr":"واقفًا فوق بار اللاندماين أو بجانبه، تنحني من الوركين وتسحب الطرف المحمّل نحو جذعك. يوفر المسار القوسي للبار زاوية تجديف ثابتة ولطيفة على المفاصل، تبني سماكة أعلى الظهر والعضلة الظهرية العريضة بأوزان كبيرة.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"upper_back","percentage":50},{"bodyTarget":"lats","percentage":25},{"bodyTarget":"biceps","percentage":15},{"bodyTarget":"shoulders_posterior","percentage":10}]},{"name":"Landmine Squat and Press","description":"Holding the end of a landmine bar at the chest, you squat down and then drive up, pressing the bar away as you stand. It links the legs, hips, shoulders, and arms in one continuous power chain, making it an efficient full-body strength and conditioning movement.","descriptionAr":"ممسكًا بطرف بار اللاندماين عند الصدر، تهبط في القرفصاء ثم تنهض بقوة دافعًا البار بعيدًا أثناء الوقوف. يربط هذا التمرين الساقين والوركين والكتفين والذراعين في سلسلة قوة واحدة متواصلة، ما يجعله حركة فعالة لقوة ولياقة الجسم بأكمله.","measurement":"reps","types":["Full Body","Functional"],"targets":[{"bodyTarget":"quadriceps","percentage":30},{"bodyTarget":"glutes","percentage":25},{"bodyTarget":"shoulders_anterior","percentage":25},{"bodyTarget":"triceps","percentage":20}]},{"name":"Lat Pulldown - Close Grip (Cable)","description":"Using a narrow neutral-grip handle, you pull down to the upper chest with the elbows tracking close to the ribs. The close grip lengthens the pulling range and increases biceps involvement while still emphasizing the lower lat fibers.","descriptionAr":"باستخدام مقبض ضيق بقبضة محايدة، تسحب إلى أعلى الصدر مع بقاء المرفقين قريبين من الأضلاع. تطيل القبضة الضيقة مدى السحب وتزيد مشاركة العضلة ذات الرأسين مع استمرار التركيز على الألياف السفلية للعضلة الظهرية العريضة.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"lats","percentage":60},{"bodyTarget":"biceps","percentage":25},{"bodyTarget":"upper_back","percentage":10},{"bodyTarget":"shoulders_posterior","percentage":5}]},{"name":"Lat Pulldown (Band)","description":"With a resistance band anchored overhead, you pull the band down toward the chest while drawing the shoulder blades down and back. It mirrors the cable pulldown pattern for the lats and biceps and is ideal for home workouts, travel, and warm-up activation.","descriptionAr":"مع تثبيت حزام مقاومة في نقطة مرتفعة، تسحب الحزام إلى الأسفل نحو الصدر مع خفض لوحي الكتف وسحبهما للخلف. يحاكي هذا التمرين نمط السحب العلوي بالكابل للعضلة الظهرية العريضة وذات الرأسين، وهو مثالي للتدريب المنزلي والسفر وتنشيط الإحماء.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"lats","percentage":60},{"bodyTarget":"biceps","percentage":20},{"bodyTarget":"upper_back","percentage":10},{"bodyTarget":"shoulders_posterior","percentage":10}]},{"name":"Lat Pulldown (Cable)","description":"Seated at a cable station, you pull a wide bar down to the upper chest while keeping the torso nearly upright. It is the standard machine builder for back width, training the lats through a long vertical pulling range with easily adjustable load.","descriptionAr":"جالسًا عند جهاز الكابل، تسحب بارًا عريضًا إلى أعلى الصدر مع إبقاء الجذع شبه منتصب. إنه التمرين الآلي الأساسي لبناء عرض الظهر، إذ يدرب العضلة الظهرية العريضة عبر مدى سحب عمودي طويل مع سهولة ضبط الحمل.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"lats","percentage":60},{"bodyTarget":"biceps","percentage":20},{"bodyTarget":"upper_back","percentage":10},{"bodyTarget":"shoulders_posterior","percentage":10}]},{"name":"Lat Pulldown (Machine)","description":"Using a plate-loaded or selectorized pulldown machine, you drive the handles down toward the shoulders along a guided path. The fixed movement arc keeps tension on the lats with minimal technique demands, making it easy to train close to failure safely.","descriptionAr":"باستخدام جهاز السحب العلوي بالأوزان أو الملاقط، تدفع المقابض إلى الأسفل نحو الكتفين على مسار موجّه. يحافظ قوس الحركة الثابت على التوتر في العضلة الظهرية العريضة بأقل متطلبات تقنية، ما يسهّل التدريب قرب الإجهاد الكامل بأمان.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"lats","percentage":60},{"bodyTarget":"biceps","percentage":20},{"bodyTarget":"upper_back","percentage":10},{"bodyTarget":"shoulders_posterior","percentage":10}]},{"name":"Lateral Band Walks","description":"With a band around the knees or ankles, you step sideways in a quarter squat while keeping constant tension on the band. It activates the gluteus medius, improving hip stability and knee control, and is widely used in warm-ups and knee-injury prevention.","descriptionAr":"مع وضع حزام مقاومة حول الركبتين أو الكاحلين، تخطو جانبيًا في وضعية ربع قرفصاء مع الحفاظ على شد مستمر في الحزام. ينشط هذا التمرين العضلة الألوية الوسطى، فيحسن ثبات الورك والتحكم في الركبة، ويستخدم على نطاق واسع في الإحماء والوقاية من إصابات الركبة.","measurement":"reps","types":["Lower Body","Functional"],"targets":[{"bodyTarget":"glutes","percentage":75},{"bodyTarget":"quadriceps","percentage":15},{"bodyTarget":"core_deep","percentage":10}]},{"name":"Lateral Box Jump","description":"Standing beside a box, you jump sideways onto it and land softly in a partial squat before stepping down and repeating. It develops lateral explosive power and landing control, qualities that carry over to change-of-direction speed in sport.","descriptionAr":"واقفًا بجانب صندوق، تقفز جانبيًا إليه وتهبط بهدوء في قرفصاء جزئية قبل النزول والتكرار. يطور هذا التمرين القوة الانفجارية الجانبية والتحكم في الهبوط، وهي صفات تنعكس على سرعة تغيير الاتجاه في الرياضة.","measurement":"reps","types":["Leg Day","HIIT"],"targets":[{"bodyTarget":"quadriceps","percentage":45},{"bodyTarget":"glutes","percentage":30},{"bodyTarget":"calves","percentage":15},{"bodyTarget":"hamstrings","percentage":10}]},{"name":"Lateral Leg Raises","description":"Lying on your side or standing, you lift the top leg straight up away from the midline and lower it under control. It strengthens the hip abductors, chiefly the gluteus medius, supporting pelvic stability during single-leg movements.","descriptionAr":"مستلقيًا على جانبك أو واقفًا، ترفع الساق العلوية مستقيمة بعيدًا عن خط منتصف الجسم ثم تخفضها بتحكم. يقوي هذا التمرين مبعدات الورك وعلى رأسها العضلة الألوية الوسطى، فيدعم ثبات الحوض أثناء الحركات على ساق واحدة.","measurement":"reps","types":["Lower Body","Calisthenics"],"targets":[{"bodyTarget":"glutes","percentage":80},{"bodyTarget":"obliques","percentage":10},{"bodyTarget":"core_deep","percentage":10}]},{"name":"Lateral Lunge","description":"You step wide to one side and sit back into the leading hip while the trailing leg stays straight. It strengthens the quads and glutes in the frontal plane and gives the inner thighs a loaded stretch, improving side-to-side athleticism.","descriptionAr":"تخطو خطوة واسعة إلى أحد الجانبين وتجلس للخلف على الورك الأمامي بينما تبقى الساق الأخرى مستقيمة. يقوي هذا التمرين العضلة رباعية الرؤوس والألوية في المستوى الجانبي ويمنح الفخذين الداخليين إطالة محمّلة، فيحسن الأداء الرياضي الجانبي.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"quadriceps","percentage":40},{"bodyTarget":"adductors","percentage":25},{"bodyTarget":"glutes","percentage":25},{"bodyTarget":"hamstrings","percentage":10}]},{"name":"Lateral Raise (Band)","description":"Standing on a resistance band, you raise the arms out to the sides until they reach shoulder height. The band's rising tension peaks at the top of the movement, hitting the lateral deltoids hardest exactly where they work most.","descriptionAr":"واقفًا على حزام مقاومة، ترفع الذراعين إلى الجانبين حتى مستوى الكتفين. يبلغ شد الحزام المتزايد ذروته في أعلى الحركة، فيستهدف الرأس الجانبي للعضلة الدالية بأقصى شدة في النقطة التي يعمل فيها أكثر.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"shoulders_lateral","percentage":80},{"bodyTarget":"traps","percentage":10},{"bodyTarget":"shoulders_anterior","percentage":10}]},{"name":"Lateral Raise (Cable)","description":"With a low cable set at your side, you raise the arm out and up to shoulder height against the pulley's resistance. The cable keeps tension on the lateral deltoid through the entire arc, including the bottom range where dumbbells provide almost none.","descriptionAr":"مع ضبط كابل منخفض إلى جانبك، ترفع الذراع إلى الخارج والأعلى حتى مستوى الكتف ضد مقاومة البكرة. يحافظ الكابل على التوتر في الرأس الجانبي للدالية طوال قوس الحركة، بما في ذلك المدى السفلي الذي لا توفر فيه الدمبل مقاومة تُذكر.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"shoulders_lateral","percentage":80},{"bodyTarget":"traps","percentage":10},{"bodyTarget":"shoulders_anterior","percentage":10}]},{"name":"Lateral Raise (Dumbbell)","description":"Holding a dumbbell in each hand, you lift the arms out to the sides with a slight elbow bend until they are level with the shoulders. It is the classic isolation exercise for the lateral deltoids, the muscle most responsible for visible shoulder width.","descriptionAr":"ممسكًا بدمبل في كل يد، ترفع الذراعين إلى الجانبين مع انحناء بسيط في المرفقين حتى تصلا إلى مستوى الكتفين. إنه تمرين العزل الكلاسيكي للرأس الجانبي للعضلة الدالية، وهو العضلة الأكثر مسؤولية عن عرض الكتفين الظاهر.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"shoulders_lateral","percentage":80},{"bodyTarget":"traps","percentage":10},{"bodyTarget":"shoulders_anterior","percentage":10}]},{"name":"Lateral Raise (Machine)","description":"Seated in a machine with pads against the outer arms, you raise both arms out to the sides along a fixed arc. The machine removes momentum and balance from the movement, keeping strict, continuous tension on the lateral deltoids.","descriptionAr":"جالسًا في جهاز مع وسائد على الجزء الخارجي من الذراعين، ترفع الذراعين إلى الجانبين على قوس ثابت. يزيل الجهاز الزخم والتوازن من الحركة، فيحافظ على توتر صارم ومتواصل في الرأس الجانبي للعضلة الدالية.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"shoulders_lateral","percentage":80},{"bodyTarget":"traps","percentage":10},{"bodyTarget":"shoulders_anterior","percentage":10}]},{"name":"Lateral Squat","description":"From a wide stance, you shift your weight over one leg and squat down on that side while the other leg stays straight. It builds frontal-plane leg strength and deeply stretches the adductors of the straight leg, improving hip mobility.","descriptionAr":"من وقفة واسعة، تنقل وزنك فوق إحدى الساقين وتهبط في القرفصاء على ذلك الجانب بينما تبقى الساق الأخرى مستقيمة. يبني هذا التمرين قوة الساقين في المستوى الجانبي ويطيل بعمق العضلات المقربة للساق المستقيمة، فيحسن مرونة الورك.","measurement":"reps","types":["Leg Day","Mobility"],"targets":[{"bodyTarget":"quadriceps","percentage":40},{"bodyTarget":"adductors","percentage":30},{"bodyTarget":"glutes","percentage":20},{"bodyTarget":"hamstrings","percentage":10}]},{"name":"Leg Extension (Machine)","description":"Seated with the pad against your shins, you extend the knees until the legs are straight and lower back under control. It isolates the quadriceps completely, making it a key tool for quad hypertrophy and for strengthening the knee after other training.","descriptionAr":"جالسًا مع استناد الوسادة إلى قصبتي الساقين، تبسط الركبتين حتى تستقيم الساقان ثم تعود بتحكم. يعزل هذا التمرين العضلة رباعية الرؤوس تمامًا، ما يجعله أداة أساسية لتضخيمها ولتقوية الركبة بعد التدريبات الأخرى.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"quadriceps","percentage":90},{"bodyTarget":"hip_flexors","percentage":10}]},{"name":"Leg Press (Machine)","description":"Seated in the machine, you press the platform away by extending the knees and hips, then lower it under control. It allows very heavy loading of the quads and glutes without balancing a bar, and foot placement can shift the emphasis between muscle groups.","descriptionAr":"جالسًا في الجهاز، تدفع المنصة بعيدًا ببسط الركبتين والوركين ثم تخفضها بتحكم. يتيح هذا التمرين تحميلًا كبيرًا جدًا على العضلة رباعية الرؤوس والألوية دون الحاجة إلى موازنة بار، ويمكن لموضع القدمين تغيير التركيز بين المجموعات العضلية.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"quadriceps","percentage":55},{"bodyTarget":"glutes","percentage":30},{"bodyTarget":"hamstrings","percentage":15}]},{"name":"Leg Press Horizontal (Machine)","description":"Seated upright, you push the platform straight ahead along a horizontal track by extending the knees and hips. The seated position and guided path make it a back-friendly way to build quad and glute strength with adjustable resistance.","descriptionAr":"جالسًا بوضع منتصب، تدفع المنصة مباشرة إلى الأمام على مسار أفقي ببسط الركبتين والوركين. تجعل وضعية الجلوس والمسار الموجّه هذا التمرين وسيلة لطيفة على الظهر لبناء قوة العضلة رباعية الرؤوس والألوية بمقاومة قابلة للضبط.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"quadriceps","percentage":55},{"bodyTarget":"glutes","percentage":30},{"bodyTarget":"hamstrings","percentage":15}]},{"name":"Leg Raise Parallel Bars","description":"Supported on parallel bars with locked arms, you raise both straight legs until they are parallel to the floor or higher. Keeping the legs straight makes it considerably harder than knee raises, demanding strong abs and hip flexors with strict swing-free control.","descriptionAr":"مستندًا على المتوازي بذراعين مقفلتين، ترفع الساقين المستقيمتين حتى تصبحا موازيتين للأرض أو أعلى. يجعل إبقاء الساقين مستقيمتين هذا التمرين أصعب بكثير من رفع الركبتين، إذ يتطلب قوة كبيرة في عضلات البطن ومثنيات الورك مع تحكم صارم دون تأرجح.","measurement":"reps","types":["Core","Calisthenics"],"targets":[{"bodyTarget":"core_abs","percentage":50},{"bodyTarget":"hip_flexors","percentage":35},{"bodyTarget":"core_deep","percentage":15}]},{"name":"Low Cable Fly Crossovers","description":"With the pulleys set low, you sweep the handles upward and inward until they cross in front of the upper chest. The low-to-high path targets the upper chest fibers while cable tension stays constant through the full squeezing range.","descriptionAr":"مع ضبط البكرات في وضع منخفض، ترفع المقبضين إلى الأعلى والداخل حتى يتقاطعا أمام أعلى الصدر. يستهدف المسار من الأسفل إلى الأعلى الألياف العلوية للصدر، بينما يبقى شد الكابل ثابتًا طوال مدى العصر الكامل.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"chest","percentage":80},{"bodyTarget":"shoulders_anterior","percentage":20}]},{"name":"Low Row (Suspension)","description":"Leaning back while gripping suspension handles, you row your body up until the hands reach the ribs, keeping a rigid plank line. Walking the feet forward or back instantly changes the difficulty, making it a scalable back builder for any level.","descriptionAr":"مائلًا إلى الخلف ممسكًا بمقابض التعليق، تسحب جسمك إلى الأعلى حتى تصل اليدان إلى الأضلاع مع الحفاظ على استقامة الجسم كالبلانك. يغيّر تحريك القدمين للأمام أو الخلف مستوى الصعوبة فورًا، ما يجعله تمرين ظهر قابلًا للتدرج لأي مستوى.","measurement":"reps","types":["Pull Day","Calisthenics"],"targets":[{"bodyTarget":"upper_back","percentage":50},{"bodyTarget":"lats","percentage":20},{"bodyTarget":"biceps","percentage":20},{"bodyTarget":"shoulders_posterior","percentage":10}]},{"name":"Lunge","description":"You step forward and bend both knees until the back knee approaches the floor, then push through the front foot to return. This foundational bodyweight pattern builds single-leg strength, balance, and hip mobility with no equipment required.","descriptionAr":"تخطو للأمام وتثني الركبتين حتى تقترب الركبة الخلفية من الأرض، ثم تدفع بالقدم الأمامية للعودة. يبني هذا النمط الأساسي بوزن الجسم قوة الساق الواحدة والتوازن ومرونة الورك دون الحاجة إلى أي معدات.","measurement":"reps","types":["Leg Day","Calisthenics"],"targets":[{"bodyTarget":"quadriceps","percentage":50},{"bodyTarget":"glutes","percentage":30},{"bodyTarget":"hamstrings","percentage":20}]},{"name":"Lunge (Barbell)","description":"With a barbell on your upper back, you step forward and lower the back knee toward the floor before driving back to standing. The barbell allows heavy progressive loading of the quads and glutes while each leg works independently, exposing and fixing imbalances.","descriptionAr":"مع وضع بار الحديد على أعلى الظهر، تخطو للأمام وتخفض الركبة الخلفية نحو الأرض ثم تدفع عائدًا إلى الوقوف. يتيح البار تحميلًا تدريجيًا ثقيلًا على العضلة رباعية الرؤوس والألوية بينما تعمل كل ساق بمفردها، فيكشف فروق القوة ويعالجها.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"quadriceps","percentage":50},{"bodyTarget":"glutes","percentage":30},{"bodyTarget":"hamstrings","percentage":20}]},{"name":"Lunge (Dumbbell)","description":"Holding a dumbbell in each hand at your sides, you step forward into a lunge and push back up through the front heel. The dumbbells load the legs while also challenging grip, and the free stance builds balance and single-leg control.","descriptionAr":"ممسكًا بدمبل في كل يد إلى جانبيك، تخطو للأمام في اندفاع ثم تدفع عائدًا عبر كعب القدم الأمامية. تحمّل الدمبلات الساقين وتتحدى القبضة في آن واحد، بينما تبني الوقفة الحرة التوازن والتحكم على ساق واحدة.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"quadriceps","percentage":50},{"bodyTarget":"glutes","percentage":30},{"bodyTarget":"hamstrings","percentage":20}]},{"name":"Lying Knee Raise","description":"Lying on your back with hands at your sides, you draw the knees toward the chest and lower them without letting the lower back arch. It is a gentle entry point for lower-ab and hip flexor training, ideal for beginners building toward leg raises.","descriptionAr":"مستلقيًا على ظهرك ويداك إلى جانبيك، تسحب الركبتين نحو الصدر ثم تخفضهما دون السماح لأسفل الظهر بالتقوس. إنه مدخل لطيف لتدريب أسفل البطن ومثنيات الورك، ومثالي للمبتدئين تمهيدًا لرفع الساقين المستقيمتين.","measurement":"reps","types":["Core","Calisthenics"],"targets":[{"bodyTarget":"core_abs","percentage":55},{"bodyTarget":"hip_flexors","percentage":35},{"bodyTarget":"core_deep","percentage":10}]},{"name":"Lying Leg Curl (Machine)","description":"Lying face down with the pad behind your ankles, you curl the heels toward the glutes and lower back slowly. It isolates the hamstrings through knee flexion, a function squats and deadlifts barely train, making it essential for balanced leg development and injury prevention.","descriptionAr":"مستلقيًا على بطنك مع وضع الوسادة خلف كاحليك، تثني الكعبين نحو الألوية ثم تعود ببطء. يعزل هذا التمرين العضلات المأبضية عبر ثني الركبة، وهي وظيفة لا تدربها القرفصاء والرفعة الميتة إلا قليلًا، ما يجعله أساسيًا لتطور متوازن للساقين والوقاية من الإصابات.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"hamstrings","percentage":80},{"bodyTarget":"calves","percentage":10},{"bodyTarget":"glutes","percentage":10}]},{"name":"Lying Neck Curls","description":"Lying face-up, you flex the neck by lifting the head toward the chest against gravity or light resistance, strengthening the deep neck flexors. Building neck strength improves head stability and posture and helps protect against strain in contact sports.","descriptionAr":"يُؤدى هذا التمرين بالاستلقاء على الظهر ورفع الرأس نحو الصدر ضد الجاذبية أو مقاومة خفيفة لتقوية عضلات الرقبة الأمامية العميقة. تُحسّن قوة الرقبة ثبات الرأس والقوام وتساعد على الوقاية من الإجهاد في الرياضات الاحتكاكية.","measurement":"reps","types":["Upper Body"],"targets":[{"bodyTarget":"traps","percentage":85},{"bodyTarget":"upper_back","percentage":15}]},{"name":"Lying Neck Curls (Weighted)","description":"Lying face up on a bench with your head off the edge and a plate held against the forehead, you curl the chin toward the chest and lower back slowly. It strengthens the front of the neck, an area linked to reduced concussion risk in contact and combat sports.","descriptionAr":"مستلقيًا على ظهرك على مقعد مع خروج رأسك عن حافته وإمساك قرص وزن على جبهتك، تثني الذقن نحو الصدر ثم تعود ببطء. يقوي هذا التمرين مقدمة الرقبة، وهي منطقة يرتبط تقويتها بخفض خطر الارتجاج في الرياضات الاحتكاكية والقتالية.","measurement":"reps","types":["Upper Body"],"targets":[{"bodyTarget":"traps","percentage":85},{"bodyTarget":"upper_back","percentage":15}]},{"name":"Lying Neck Extension","description":"Lying face-down off the edge of a bench, you raise the head upward against gravity to strengthen the neck extensor muscles. It is a safe bodyweight starting point for building neck strength and endurance before adding external load.","descriptionAr":"يُؤدى بالاستلقاء على البطن مع إخراج الرأس من حافة المقعد ثم رفعه ضد الجاذبية لتقوية عضلات الرقبة الخلفية. يُعد نقطة بداية آمنة بوزن الجسم لبناء قوة الرقبة وتحملها قبل إضافة أوزان خارجية.","measurement":"reps","types":["Upper Body"],"targets":[{"bodyTarget":"traps","percentage":80},{"bodyTarget":"upper_back","percentage":20}]},{"name":"Lying Neck Extension (Weighted)","description":"Lying face-down with a plate held against the back of the head, you extend the neck upward to load the neck extensors and upper trapezius. Progressive weighted work builds a stronger, more resilient neck for athletes and improves head-carriage posture.","descriptionAr":"يُؤدى بالاستلقاء على البطن مع تثبيت وزن خلف الرأس ثم مد الرقبة إلى الأعلى لتحميل عضلات الرقبة الخلفية والجزء العلوي من العضلة شبه المنحرفة. يبني التحميل التدريجي رقبة أقوى وأكثر تحملاً للرياضيين ويحسّن وضعية الرأس.","measurement":"reps","types":["Upper Body"],"targets":[{"bodyTarget":"traps","percentage":80},{"bodyTarget":"upper_back","percentage":20}]},{"name":"Meadows Rows (Barbell)","description":"A single-arm row performed over the end of a landmine barbell with an overhand grip, pulling the elbow up and back. The staggered stance and unique bar path emphasize the upper back and lats through a long stretch, with the biceps and rear delts assisting.","descriptionAr":"تجديف بذراع واحدة يُؤدى فوق طرف بار مثبت أرضياً بقبضة علوية مع سحب المرفق إلى الأعلى والخلف. تُبرز الوقفة المتباعدة ومسار البار الفريد أعلى الظهر والعضلة الظهرية العريضة عبر إطالة كاملة، بمساعدة العضلة ذات الرأسين والكتف الخلفي.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"upper_back","percentage":50},{"bodyTarget":"lats","percentage":20},{"bodyTarget":"biceps","percentage":15},{"bodyTarget":"shoulders_posterior","percentage":15}]},{"name":"Negative Pull Up","description":"You start at the top of the bar and lower yourself as slowly as possible, training only the eccentric phase of the pull-up. This builds the lat, biceps, and grip strength needed to progress toward full unassisted pull-ups.","descriptionAr":"تبدأ من أعلى العقلة ثم تهبط ببطء شديد قدر الإمكان، متدرباً على المرحلة السلبية فقط من تمرين العقلة. يبني ذلك قوة العضلة الظهرية العريضة والعضلة ذات الرأسين وقبضة اليد اللازمة للتقدم نحو أداء العقلة الكاملة دون مساعدة.","measurement":"reps","types":["Pull Day","Calisthenics"],"targets":[{"bodyTarget":"lats","percentage":55},{"bodyTarget":"biceps","percentage":20},{"bodyTarget":"upper_back","percentage":15},{"bodyTarget":"shoulders_posterior","percentage":10}]},{"name":"Nordic Hamstrings Curls","description":"With the ankles anchored, you kneel upright and lower your torso forward under control using only the hamstrings to resist the fall. This intense eccentric exercise is well documented for building hamstring strength and reducing hamstring strain risk in sprinting sports.","descriptionAr":"مع تثبيت الكاحلين، تركع بجذع مستقيم ثم تهبط بجسمك إلى الأمام ببطء معتمداً على العضلات الخلفية للفخذ فقط لمقاومة السقوط. هذا التمرين اللامركزي المكثف موثق جيداً لبناء قوة أوتار الركبة وتقليل خطر إصابتها في رياضات العدو.","measurement":"reps","types":["Leg Day","Calisthenics"],"targets":[{"bodyTarget":"hamstrings","percentage":75},{"bodyTarget":"glutes","percentage":15},{"bodyTarget":"calves","percentage":10}]},{"name":"Oblique Crunch","description":"A crunch performed with a twist or to one side, bringing the shoulder toward the opposite hip to engage the oblique muscles along with the rectus abdominis. Strong obliques support trunk rotation, side bending, and overall core stability.","descriptionAr":"تمرين طحن يُؤدى مع دوران أو ميل إلى جانب واحد بتقريب الكتف نحو الورك المقابل لإشراك العضلات المائلة إلى جانب العضلة البطنية المستقيمة. تدعم العضلات المائلة القوية دوران الجذع والانحناء الجانبي وثبات الجذع عموماً.","measurement":"reps","types":["Core"],"targets":[{"bodyTarget":"obliques","percentage":55},{"bodyTarget":"core_abs","percentage":45}]},{"name":"One Arm Push Up","description":"An advanced push-up performed on a single arm with feet spread wide, demanding maximal pressing strength from the chest, triceps, and front shoulder. The unilateral load also forces intense core and hip bracing to keep the torso from rotating.","descriptionAr":"تمرين ضغط متقدم يُؤدى على ذراع واحدة مع مباعدة القدمين، ويتطلب أقصى قوة دفع من الصدر والعضلة ثلاثية الرؤوس ومقدمة الكتف. كما يفرض الحمل الأحادي شداً مكثفاً لعضلات الجذع والورك لمنع دوران الجسم.","measurement":"reps","types":["Push Day","Calisthenics"],"targets":[{"bodyTarget":"chest","percentage":45},{"bodyTarget":"triceps","percentage":25},{"bodyTarget":"core_abs","percentage":15},{"bodyTarget":"shoulders_anterior","percentage":15}]},{"name":"Overhead Curl (Cable)","description":"Performed with the arms held at shoulder height on a high cable, you curl the handles toward the head, keeping the upper arms fixed. The elevated arm position emphasizes the short head and peak contraction of the biceps under constant cable tension.","descriptionAr":"يُؤدى مع رفع الذراعين بمستوى الكتفين على بكرة عالية، حيث تثني المقبضين نحو الرأس مع تثبيت العضدين. تُبرز وضعية الذراع المرتفعة الرأس القصير للعضلة ذات الرأسين وذروة انقباضها تحت شد الكابل المستمر.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"biceps","percentage":80},{"bodyTarget":"forearms","percentage":20}]},{"name":"Overhead Dumbbell Lunge","description":"A lunge performed while holding a dumbbell locked out overhead, training the quads, glutes, and hamstrings through each stride. Keeping the weight overhead adds a strong shoulder-stability and core-control demand to the movement.","descriptionAr":"طعن يُؤدى مع حمل دمبل مرفوعاً فوق الرأس بذراع ممدودة، فيدرب العضلة رباعية الرؤوس والألوية وأوتار الركبة في كل خطوة. يضيف إبقاء الوزن فوق الرأس تحدياً كبيراً لثبات الكتف والتحكم في الجذع.","measurement":"reps","types":["Leg Day","Functional"],"targets":[{"bodyTarget":"quadriceps","percentage":45},{"bodyTarget":"glutes","percentage":25},{"bodyTarget":"hamstrings","percentage":15},{"bodyTarget":"shoulders_anterior","percentage":15}]},{"name":"Overhead Plate Raise","description":"Holding a weight plate with both hands, you raise it from thigh level all the way overhead with straight arms. The long range of motion works the front and side delts through their full arc, with the traps and triceps assisting at the top.","descriptionAr":"تمسك قرص وزن بكلتا اليدين ثم ترفعه من مستوى الفخذ حتى فوق الرأس بذراعين ممدودتين. يعمل نطاق الحركة الطويل على الكتف الأمامي والجانبي عبر قوسهما الكامل، بمساعدة شبه المنحرفة والعضلة ثلاثية الرؤوس في الأعلى.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"shoulders_anterior","percentage":60},{"bodyTarget":"shoulders_lateral","percentage":20},{"bodyTarget":"traps","percentage":10},{"bodyTarget":"triceps","percentage":10}]},{"name":"Overhead Press (Dumbbell)","description":"You press a dumbbell in each hand from shoulder height to full lockout overhead, building the anterior and lateral deltoids with strong triceps involvement. Dumbbells allow a natural pressing path and expose side-to-side strength imbalances better than a barbell.","descriptionAr":"تدفع دمبل في كل يد من مستوى الكتف حتى الامتداد الكامل فوق الرأس، لبناء الكتف الأمامي والجانبي مع مشاركة قوية من العضلة ثلاثية الرؤوس. تتيح الدمبلات مساراً طبيعياً للدفع وتكشف فروق القوة بين الجانبين أفضل من البار.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"shoulders_anterior","percentage":55},{"bodyTarget":"shoulders_lateral","percentage":20},{"bodyTarget":"triceps","percentage":20},{"bodyTarget":"traps","percentage":5}]},{"name":"Overhead Press (Smith Machine)","description":"A shoulder press performed on the Smith machine's guided bar path, pressing from the upper chest to lockout overhead. The fixed track reduces the balance demand so you can focus load directly on the deltoids and triceps.","descriptionAr":"تمرين دفع للكتفين يُؤدى على مسار البار الموجه في جهاز سميث، بالدفع من أعلى الصدر حتى الامتداد الكامل فوق الرأس. يقلل المسار الثابت الحاجة إلى التوازن مما يتيح تركيز الحمل مباشرة على الكتفين والعضلة ثلاثية الرؤوس.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"shoulders_anterior","percentage":55},{"bodyTarget":"shoulders_lateral","percentage":20},{"bodyTarget":"triceps","percentage":20},{"bodyTarget":"traps","percentage":5}]},{"name":"Overhead Squat","description":"You squat to full depth while holding a barbell locked out overhead in a wide snatch grip. Beyond training the quads and glutes, it is one of the most demanding tests of shoulder, thoracic, and core stability and underpins the snatch in Olympic lifting.","descriptionAr":"تنزل إلى قرفصاء كاملة العمق مع حمل البار ممدوداً فوق الرأس بقبضة خطف واسعة. إلى جانب تدريب رباعية الرؤوس والألوية، يُعد من أكثر التمارين تطلباً لثبات الكتفين والجذع والصدر، وهو أساس رفعة الخطف في الرفع الأولمبي.","measurement":"reps","types":["Full Body","Olympic Lifting"],"targets":[{"bodyTarget":"quadriceps","percentage":35},{"bodyTarget":"glutes","percentage":25},{"bodyTarget":"core_abs","percentage":20},{"bodyTarget":"shoulders_anterior","percentage":20}]},{"name":"Overhead Triceps Extension (Cable)","description":"Facing away from a low cable, you extend the arms from behind the head to full lockout overhead. The stretched overhead position places heavy emphasis on the long head of the triceps, which favors overall triceps growth.","descriptionAr":"مستدبراً بكرة منخفضة، تمد الذراعين من خلف الرأس حتى الامتداد الكامل فوق الرأس. تضع وضعية الإطالة فوق الرأس تركيزاً كبيراً على الرأس الطويل للعضلة ثلاثية الرؤوس، مما يعزز نموها الكلي.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"triceps","percentage":80},{"bodyTarget":"shoulders_anterior","percentage":10},{"bodyTarget":"core_abs","percentage":10}]},{"name":"Partial Glute Bridge (Barbell)","description":"A barbell glute bridge performed through a shortened top-range of motion, keeping constant tension on the glutes near full hip extension. Working the strongest part of the range lets you handle heavy loads and reinforce the hip lockout used in squats and deadlifts.","descriptionAr":"جسر ألوية بالبار يُؤدى في النطاق العلوي المختصر من الحركة، مع إبقاء شد مستمر على العضلات الألوية قرب الامتداد الكامل للورك. يتيح العمل في أقوى جزء من النطاق استخدام أوزان ثقيلة وتعزيز قفل الورك المستخدم في القرفصاء والرفعة الميتة.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"glutes","percentage":70},{"bodyTarget":"hamstrings","percentage":20},{"bodyTarget":"core_abs","percentage":10}]},{"name":"Pause Squat (Barbell)","description":"A barbell squat with a deliberate two-to-three-second pause in the bottom position before driving back up. Eliminating the stretch reflex forces the quads and glutes to produce force from a dead stop, building strength and positional control out of the hole.","descriptionAr":"قرفصاء بالبار مع توقف مقصود لثانيتين إلى ثلاث في الوضع السفلي قبل الدفع للأعلى. يجبر إلغاء منعكس الإطالة العضلة رباعية الرؤوس والألوية على توليد القوة من سكون تام، مما يبني القوة والتحكم في أعمق نقطة من الحركة.","measurement":"reps","types":["Leg Day","Powerlifting"],"targets":[{"bodyTarget":"quadriceps","percentage":50},{"bodyTarget":"glutes","percentage":25},{"bodyTarget":"hamstrings","percentage":15},{"bodyTarget":"erector_spinae","percentage":10}]},{"name":"Pendlay Row (Barbell)","description":"A strict barbell row where every rep starts from a dead stop on the floor with the torso parallel to the ground. Pulling explosively from the floor builds upper-back and lat power that transfers directly to deadlifts and heavy pulling.","descriptionAr":"تجديف صارم بالبار تبدأ فيه كل تكرار من سكون تام على الأرض مع جذع موازٍ للأرض. يبني السحب الانفجاري من الأرض قوة أعلى الظهر والعضلة الظهرية العريضة بما ينتقل مباشرة إلى الرفعة الميتة والسحب الثقيل.","measurement":"reps","types":["Pull Day","Powerlifting"],"targets":[{"bodyTarget":"upper_back","percentage":45},{"bodyTarget":"lats","percentage":25},{"bodyTarget":"biceps","percentage":15},{"bodyTarget":"shoulders_posterior","percentage":15}]},{"name":"Pendulum Squat (Machine)","description":"A machine squat whose arcing pendulum path keeps the torso upright and tracks the body's natural squat motion. The design allows very deep, knee-friendly squatting that loads the quads intensely with minimal lower-back stress.","descriptionAr":"قرفصاء على جهاز يتحرك بمسار قوسي بندولي يحافظ على الجذع منتصباً ويحاكي حركة القرفصاء الطبيعية. يتيح التصميم نزولاً عميقاً جداً ولطيفاً على الركبتين، محملاً العضلة رباعية الرؤوس بشدة مع إجهاد ضئيل لأسفل الظهر.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"quadriceps","percentage":55},{"bodyTarget":"glutes","percentage":25},{"bodyTarget":"hamstrings","percentage":10},{"bodyTarget":"adductors","percentage":10}]},{"name":"Pilates","description":"A low-impact movement system built around controlled, precise exercises that strengthen the deep core while coordinating breath with motion. Regular practice improves posture, flexibility, body awareness, and trunk stability.","descriptionAr":"منظومة حركية منخفضة التأثير تقوم على تمارين دقيقة ومضبوطة تقوّي عضلات الجذع العميقة مع تنسيق التنفس مع الحركة. تحسّن الممارسة المنتظمة القوام والمرونة والوعي الجسدي وثبات الجذع.","measurement":"reps","types":["Full Body","Core","Mobility"],"targets":[{"bodyTarget":"core_deep","percentage":40},{"bodyTarget":"core_abs","percentage":25},{"bodyTarget":"flexibility","percentage":20},{"bodyTarget":"balance","percentage":15}]},{"name":"Pinwheel Curl (Dumbbell)","description":"A cross-body hammer curl in which the dumbbell is curled diagonally toward the opposite shoulder with a neutral grip. The angle and grip shift emphasis onto the brachialis and brachioradialis, thickening the upper arm and forearm.","descriptionAr":"ثني مطرقي متقاطع يُرفع فيه الدمبل قطرياً نحو الكتف المقابل بقبضة محايدة. تنقل الزاوية والقبضة التركيز إلى العضلة العضدية والعضدية الكعبرية، مما يزيد سماكة العضد والساعد.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"biceps","percentage":60},{"bodyTarget":"forearms","percentage":40}]},{"name":"Plank Pushup","description":"From a forearm plank you press up one arm at a time into a push-up position, then lower back down, alternating lead arms. The transition trains chest and triceps pressing strength while the plank base keeps the core braced throughout.","descriptionAr":"من وضع البلانك على الساعدين تدفع نفسك للأعلى بذراع تلو الأخرى إلى وضع الضغط ثم تعود للأسفل بالتناوب بين الذراعين. يدرب هذا الانتقال قوة الدفع في الصدر والعضلة ثلاثية الرؤوس بينما تُبقي قاعدة البلانك الجذع مشدوداً طوال الوقت.","measurement":"reps","types":["Push Day","Core","Calisthenics"],"targets":[{"bodyTarget":"chest","percentage":35},{"bodyTarget":"triceps","percentage":25},{"bodyTarget":"core_abs","percentage":25},{"bodyTarget":"shoulders_anterior","percentage":15}]},{"name":"Plate Curl","description":"You grip a weight plate by its edges and curl it from the thighs toward the chest, keeping the elbows tucked. The open plate grip adds a pinching demand that works the forearms and grip alongside the biceps.","descriptionAr":"تمسك قرص وزن من حوافه وتثنيه من مستوى الفخذين نحو الصدر مع إبقاء المرفقين قريبين من الجسم. تضيف قبضة القرص المفتوحة تحدياً للقبضة يعمل على الساعدين إلى جانب العضلة ذات الرأسين.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"biceps","percentage":75},{"bodyTarget":"forearms","percentage":25}]},{"name":"Plate Front Raise","description":"Holding a plate with both hands at the hips, you raise it with straight arms to shoulder height and lower under control. It isolates the front deltoids while the two-handed grip keeps the movement stable and symmetrical.","descriptionAr":"تحمل قرص وزن بكلتا اليدين عند الوركين ثم ترفعه بذراعين ممدودتين حتى مستوى الكتفين وتنزله ببطء. يعزل التمرين الكتف الأمامي بينما تحافظ القبضة الثنائية على حركة ثابتة ومتناظرة.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"shoulders_anterior","percentage":70},{"bodyTarget":"shoulders_lateral","percentage":20},{"bodyTarget":"traps","percentage":10}]},{"name":"Plate Press","description":"You press a weight plate held between both palms away from the chest until the arms are fully extended. Squeezing the plate throughout keeps the inner chest under continuous tension while the triceps and front delts assist the press.","descriptionAr":"تدفع قرص وزن ممسوكاً بين راحتي اليدين بعيداً عن الصدر حتى امتداد الذراعين بالكامل. يُبقي الضغط المستمر على القرص منتصف الصدر تحت شد متواصل بينما تساعد العضلة ثلاثية الرؤوس ومقدمة الكتف في الدفع.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"chest","percentage":55},{"bodyTarget":"triceps","percentage":25},{"bodyTarget":"shoulders_anterior","percentage":20}]},{"name":"Plate Squeeze (Svend Press)","description":"You press two plates together between flat palms and extend them from the chest while squeezing inward as hard as possible. The constant inward squeeze produces an intense isometric contraction of the inner chest that is hard to achieve with conventional pressing.","descriptionAr":"تضغط قرصين معاً بين راحتي اليدين وتمدهما بعيداً عن الصدر مع العصر للداخل بأقصى قوة. يولّد الضغط الداخلي المستمر انقباضاً متساوي القياس مكثفاً في منتصف الصدر يصعب تحقيقه بتمارين الدفع التقليدية.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"chest","percentage":65},{"bodyTarget":"triceps","percentage":15},{"bodyTarget":"shoulders_anterior","percentage":10},{"bodyTarget":"forearms","percentage":10}]},{"name":"Preacher Curl (Barbell)","description":"You curl a barbell with the upper arms braced on the angled preacher pad, which removes all body momentum. The strict support isolates the biceps and heavily loads the stretched bottom position, a strong stimulus for growth.","descriptionAr":"تثني باراً مع تثبيت العضدين على وسادة الجهاز المائلة، مما يلغي أي زخم من الجسم. يعزل هذا الدعم الصارم العضلة ذات الرأسين ويحمّل وضع الإطالة السفلي بقوة، وهو محفز قوي للنمو.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"biceps","percentage":80},{"bodyTarget":"forearms","percentage":20}]},{"name":"Preacher Curl (Dumbbell)","description":"A single-arm curl performed with the upper arm fixed on the preacher bench pad, eliminating swing and cheating. Training one arm at a time isolates each biceps fully and helps correct strength imbalances between sides.","descriptionAr":"ثني بذراع واحدة يُؤدى مع تثبيت العضد على وسادة مقعد الثني، مما يلغي التأرجح والغش. يعزل التدريب بذراع واحدة كل عضلة ذات رأسين بالكامل ويساعد على تصحيح فروق القوة بين الجانبين.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"biceps","percentage":80},{"bodyTarget":"forearms","percentage":20}]},{"name":"Preacher Curl (Machine)","description":"A machine curl with the upper arms locked on a pad and resistance following a fixed cam path. The guided motion keeps tension on the biceps through the entire range, making it easy to train close to failure safely.","descriptionAr":"ثني على جهاز مع تثبيت العضدين على وسادة ومقاومة تسير في مسار ثابت. تحافظ الحركة الموجهة على الشد في العضلة ذات الرأسين عبر كامل النطاق، مما يسهل التدريب قرب الإجهاد الكامل بأمان.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"biceps","percentage":80},{"bodyTarget":"forearms","percentage":20}]},{"name":"Press Under","description":"An Olympic lifting drill in which you press yourself down under a stationary bar, dropping the hips into a squat as the arms lock out overhead. It teaches the timing, overhead stability, and receiving position needed for the jerk and snatch.","descriptionAr":"تمرين تعليمي من الرفع الأولمبي تدفع فيه جسمك للأسفل تحت بار ثابت، خافضاً الوركين إلى القرفصاء بينما تمتد الذراعان فوق الرأس. يعلّم التوقيت وثبات الوزن فوق الرأس ووضعية الاستلام اللازمة لرفعتي النتر والخطف.","measurement":"reps","types":["Olympic Lifting","Full Body"],"targets":[{"bodyTarget":"shoulders_anterior","percentage":35},{"bodyTarget":"quadriceps","percentage":25},{"bodyTarget":"triceps","percentage":20},{"bodyTarget":"core_abs","percentage":20}]},{"name":"Pull Up (Assisted)","description":"A pull-up performed on an assisted machine or with a partner supporting part of your body weight. It lets you practice the full pull-up range with correct technique while gradually reducing assistance as the lats and arms get stronger.","descriptionAr":"عقلة تُؤدى على جهاز مساعدة أو بدعم شريك يحمل جزءاً من وزن الجسم. تتيح التدرب على النطاق الكامل للعقلة بأسلوب صحيح مع تقليل المساعدة تدريجياً كلما ازدادت قوة الظهر والذراعين.","measurement":"reps","types":["Pull Day","Calisthenics"],"targets":[{"bodyTarget":"lats","percentage":55},{"bodyTarget":"biceps","percentage":20},{"bodyTarget":"upper_back","percentage":15},{"bodyTarget":"shoulders_posterior","percentage":10}]},{"name":"Pull Up (Band)","description":"A pull-up with a resistance band looped under the feet or knees to offset part of your body weight. The band gives the most help at the bottom and least at the top, making it an effective bridge toward unassisted pull-ups.","descriptionAr":"عقلة مع حزام مقاومة مثبت تحت القدمين أو الركبتين لتعويض جزء من وزن الجسم. يقدم الحزام أكبر مساعدة في الأسفل وأقلها في الأعلى، مما يجعله جسراً فعالاً نحو أداء العقلة دون مساعدة.","measurement":"reps","types":["Pull Day","Calisthenics"],"targets":[{"bodyTarget":"lats","percentage":55},{"bodyTarget":"biceps","percentage":20},{"bodyTarget":"upper_back","percentage":15},{"bodyTarget":"shoulders_posterior","percentage":10}]},{"name":"Pull Up (Weighted)","description":"A standard pull-up performed with extra load from a dip belt, weighted vest, or dumbbell between the feet. Adding external weight turns the pull-up into a heavy strength builder for the lats, upper back, and arms.","descriptionAr":"عقلة اعتيادية تُؤدى بحمل إضافي عبر حزام أثقال أو سترة موزونة أو دمبل بين القدمين. تحوّل الأوزان الخارجية العقلة إلى تمرين قوة ثقيل للعضلة الظهرية العريضة وأعلى الظهر والذراعين.","measurement":"reps","types":["Pull Day","Calisthenics"],"targets":[{"bodyTarget":"lats","percentage":55},{"bodyTarget":"biceps","percentage":20},{"bodyTarget":"upper_back","percentage":15},{"bodyTarget":"shoulders_posterior","percentage":10}]},{"name":"Pullover (Dumbbell)","description":"Lying across a bench, you lower a single dumbbell in an arc behind the head and pull it back over the chest with slightly bent arms. The deep stretch trains the lats and chest together, with the long head of the triceps assisting.","descriptionAr":"مستلقياً بعرض المقعد، تخفض دمبلاً واحداً في قوس خلف الرأس ثم تسحبه فوق الصدر بذراعين شبه ممدودتين. تدرب الإطالة العميقة العضلة الظهرية العريضة والصدر معاً، بمساعدة الرأس الطويل للعضلة ثلاثية الرؤوس.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"lats","percentage":50},{"bodyTarget":"chest","percentage":30},{"bodyTarget":"triceps","percentage":20}]},{"name":"Pullover (Machine)","description":"Seated in a pullover machine, you drive the arms down from overhead to the sides in a fixed arc. It is one of the few machines that isolates the lats through a long range without the biceps limiting the set.","descriptionAr":"جالساً في جهاز السحب العلوي، تدفع الذراعين من فوق الرأس نحو الجانبين في قوس ثابت. وهو من الأجهزة القليلة التي تعزل العضلة الظهرية العريضة عبر نطاق طويل دون أن تحد العضلة ذات الرأسين من الأداء.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"lats","percentage":60},{"bodyTarget":"chest","percentage":20},{"bodyTarget":"triceps","percentage":20}]},{"name":"Push Press","description":"You dip slightly at the knees and drive the legs to help launch a barbell from the shoulders to lockout overhead. The leg drive lets you overload the shoulders and triceps beyond strict-press weights while training full-body power transfer.","descriptionAr":"تنخفض قليلاً بثني الركبتين ثم تدفع بالساقين لمساعدة البار على الانطلاق من الكتفين حتى الامتداد الكامل فوق الرأس. يتيح دفع الساقين تحميل الكتفين والعضلة ثلاثية الرؤوس بأوزان تفوق الدفع الصارم مع تدريب نقل القوة عبر الجسم كله.","measurement":"reps","types":["Push Day","Olympic Lifting","Full Body"],"targets":[{"bodyTarget":"shoulders_anterior","percentage":45},{"bodyTarget":"triceps","percentage":20},{"bodyTarget":"quadriceps","percentage":20},{"bodyTarget":"glutes","percentage":15}]},{"name":"Push Up - Close Grip","description":"A push-up with the hands placed close together under the chest, keeping the elbows tucked to the sides. The narrow hand position shifts a large share of the work onto the triceps and inner chest.","descriptionAr":"تمرين ضغط تُوضع فيه اليدان متقاربتين تحت الصدر مع إبقاء المرفقين ملاصقين للجانبين. تنقل وضعية اليدين الضيقة جزءاً كبيراً من الجهد إلى العضلة ثلاثية الرؤوس ومنتصف الصدر.","measurement":"reps","types":["Push Day","Calisthenics"],"targets":[{"bodyTarget":"chest","percentage":40},{"bodyTarget":"triceps","percentage":40},{"bodyTarget":"shoulders_anterior","percentage":10},{"bodyTarget":"core_abs","percentage":10}]},{"name":"Push Up (Weighted)","description":"A push-up performed with a plate on the back or a weighted vest to increase resistance. The added load makes the push-up a progressive strength exercise for the chest, triceps, and front delts rather than just an endurance drill.","descriptionAr":"تمرين ضغط يُؤدى مع قرص وزن على الظهر أو سترة موزونة لزيادة المقاومة. يحوّل الحمل الإضافي الضغط إلى تمرين قوة تدريجي للصدر والعضلة ثلاثية الرؤوس ومقدمة الكتف بدلاً من مجرد تمرين تحمل.","measurement":"reps","types":["Push Day","Calisthenics"],"targets":[{"bodyTarget":"chest","percentage":50},{"bodyTarget":"triceps","percentage":25},{"bodyTarget":"shoulders_anterior","percentage":15},{"bodyTarget":"core_abs","percentage":10}]},{"name":"Rack Pull","description":"A partial deadlift pulled from pins or blocks set around knee height, shortening the range of motion. The elevated start lets you handle heavier loads than a full deadlift, building the upper back, traps, spinal erectors, and grip.","descriptionAr":"رفعة ميتة جزئية تُسحب من مساند أو صناديق عند مستوى الركبة تقريباً، مما يقصّر نطاق الحركة. تتيح نقطة البداية المرتفعة استخدام أوزان أثقل من الرفعة الكاملة، فتبني أعلى الظهر وشبه المنحرفة وناصبات الفقار وقبضة اليد.","measurement":"reps","types":["Pull Day","Powerlifting"],"targets":[{"bodyTarget":"upper_back","percentage":40},{"bodyTarget":"traps","percentage":20},{"bodyTarget":"erector_spinae","percentage":20},{"bodyTarget":"glutes","percentage":20}]},{"name":"Rear Delt Reverse Fly (Cable)","description":"Standing between crossed cables, you pull the handles outward and back with nearly straight arms to work the rear deltoids. Cable resistance keeps tension constant through the whole arc, which free weights cannot match at the start of the movement.","descriptionAr":"واقفاً بين كابلين متقاطعين، تسحب المقبضين إلى الخارج والخلف بذراعين شبه ممدودتين لتدريب الكتف الخلفي. تحافظ مقاومة الكابل على شد ثابت عبر القوس كاملاً، وهو ما لا توفره الأوزان الحرة في بداية الحركة.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"shoulders_posterior","percentage":65},{"bodyTarget":"upper_back","percentage":20},{"bodyTarget":"traps","percentage":15}]},{"name":"Rear Delt Reverse Fly (Dumbbell)","description":"Hinged forward at the hips, you raise a pair of dumbbells out to the sides with slightly bent elbows, squeezing the shoulder blades together. It strengthens the rear delts and upper back, balancing pressing work and improving shoulder health and posture.","descriptionAr":"منحنياً من الوركين إلى الأمام، ترفع زوجاً من الدمبلات إلى الجانبين بمرفقين شبه مثنيين مع ضم لوحي الكتف. يقوي التمرين الكتف الخلفي وأعلى الظهر، موازناً تمارين الدفع ومحسّناً صحة الكتف والقوام.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"shoulders_posterior","percentage":65},{"bodyTarget":"upper_back","percentage":20},{"bodyTarget":"traps","percentage":15}]},{"name":"Rear Delt Reverse Fly (Machine)","description":"Seated facing the pec-deck machine with the handles set behind, you sweep the arms backward in a horizontal arc. The machine locks the movement path so the rear delts do the work without momentum or lower-back strain.","descriptionAr":"جالساً في مواجهة جهاز الفراشة مع ضبط المقابض للخلف، تفتح الذراعين إلى الخلف في قوس أفقي. يثبّت الجهاز مسار الحركة بحيث يقع الجهد على الكتف الخلفي دون زخم أو إجهاد لأسفل الظهر.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"shoulders_posterior","percentage":65},{"bodyTarget":"upper_back","percentage":20},{"bodyTarget":"traps","percentage":15}]},{"name":"Rear Kick (Machine)","description":"On a glute kickback machine, you drive one leg backward against the resistance pad until the hip is fully extended. The guided path isolates the gluteus maximus with hamstring assistance and allows strict, controlled reps.","descriptionAr":"على جهاز ركلات الألوية الخلفية، تدفع ساقاً واحدة إلى الخلف ضد وسادة المقاومة حتى الامتداد الكامل للورك. يعزل المسار الموجه العضلة الألوية الكبرى بمساعدة أوتار الركبة ويتيح تكرارات دقيقة ومضبوطة.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"glutes","percentage":70},{"bodyTarget":"hamstrings","percentage":30}]},{"name":"Recumbent Bike","description":"You pedal a stationary bike from a reclined, back-supported seat, training the heart and lungs with steady lower-body work. The supported position removes load from the spine and joints, making it a comfortable option for long aerobic sessions and rehabilitation.","descriptionAr":"تقوم بالتبديل على دراجة ثابتة من مقعد مائل مدعوم الظهر، مدرباً القلب والرئتين بعمل مستمر للجزء السفلي من الجسم. تزيل الوضعية المدعومة الحمل عن العمود الفقري والمفاصل، مما يجعلها خياراً مريحاً للجلسات الهوائية الطويلة وإعادة التأهيل.","measurement":"distance_duration","types":["Cardio"],"targets":[{"bodyTarget":"cardiovascular","percentage":55},{"bodyTarget":"endurance","percentage":25},{"bodyTarget":"quadriceps","percentage":20}]},{"name":"Renegade Row (Dumbbell)","description":"From a push-up position gripping two dumbbells, you row one weight to the hip while balancing on the other arm. Each row forces the core and hips to resist rotation, combining upper-back pulling strength with intense anti-rotation stability work.","descriptionAr":"من وضع الضغط ممسكاً بدمبلين، تجدف بوزن واحد نحو الورك بينما تتوازن على الذراع الأخرى. تجبر كل تجديفة الجذع والوركين على مقاومة الدوران، جامعة بين قوة السحب لأعلى الظهر وعمل مكثف لثبات مقاومة الالتفاف.","measurement":"reps","types":["Pull Day","Core","Functional"],"targets":[{"bodyTarget":"upper_back","percentage":35},{"bodyTarget":"core_abs","percentage":30},{"bodyTarget":"lats","percentage":20},{"bodyTarget":"biceps","percentage":15}]},{"name":"Reverse Crunch","description":"Lying on your back, you curl the knees toward the chest and lift the hips off the floor using the abs rather than momentum. The movement emphasizes the lower portion of the rectus abdominis while sparing the neck from strain.","descriptionAr":"مستلقياً على الظهر، تسحب الركبتين نحو الصدر وترفع الوركين عن الأرض معتمداً على عضلات البطن لا الزخم. تركز الحركة على الجزء السفلي من العضلة البطنية المستقيمة مع تجنيب الرقبة أي إجهاد.","measurement":"reps","types":["Core"],"targets":[{"bodyTarget":"core_abs","percentage":65},{"bodyTarget":"hip_flexors","percentage":25},{"bodyTarget":"obliques","percentage":10}]},{"name":"Reverse Curl (Barbell)","description":"A barbell curl performed with an overhand (pronated) grip, keeping the wrists straight throughout. The reversed grip shifts emphasis to the brachioradialis and brachialis, building forearm size and grip strength alongside the biceps.","descriptionAr":"ثني بالبار يُؤدى بقبضة علوية مع إبقاء المعصمين مستقيمين طوال الحركة. تنقل القبضة المعكوسة التركيز إلى العضلة العضدية الكعبرية والعضدية، فتبني حجم الساعد وقوة القبضة إلى جانب العضلة ذات الرأسين.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"biceps","percentage":55},{"bodyTarget":"forearms","percentage":45}]},{"name":"Reverse Curl (Cable)","description":"An overhand-grip curl on a low cable, keeping the elbows pinned to the sides as the bar rises. The cable's constant tension works the brachioradialis and forearm extensors through the entire range, including the usually easy bottom portion.","descriptionAr":"ثني بقبضة علوية على بكرة منخفضة مع تثبيت المرفقين إلى الجانبين أثناء صعود البار. يعمل شد الكابل المستمر على العضلة العضدية الكعبرية وباسطات الساعد عبر كامل النطاق، بما في ذلك الجزء السفلي السهل عادة.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"biceps","percentage":55},{"bodyTarget":"forearms","percentage":45}]},{"name":"Reverse Curl (Dumbbell)","description":"A dumbbell curl with the palms facing down, lifting the weights while keeping the wrists neutral and elbows still. It targets the brachioradialis and brachialis, and dumbbells let each arm work independently to correct imbalances.","descriptionAr":"ثني بالدمبل مع توجيه راحتي اليدين إلى الأسفل، برفع الوزنين مع إبقاء المعصمين محايدين والمرفقين ثابتين. يستهدف التمرين العضلة العضدية الكعبرية والعضدية، وتتيح الدمبلات عمل كل ذراع باستقلالية لتصحيح الفروق.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"biceps","percentage":55},{"bodyTarget":"forearms","percentage":45}]},{"name":"Reverse Fly Single Arm (Cable)","description":"You pull a single cable handle across the body and outward with a nearly straight arm, opening the chest as the arm sweeps back. Working one side at a time gives the rear delt a longer range and full attention on each rep.","descriptionAr":"تسحب مقبض كابل واحد عبر الجسم ثم إلى الخارج بذراع شبه ممدودة، فاتحاً الصدر مع اندفاع الذراع للخلف. يمنح العمل بجانب واحد الكتف الخلفي نطاقاً أطول وتركيزاً كاملاً في كل تكرار.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"shoulders_posterior","percentage":65},{"bodyTarget":"upper_back","percentage":20},{"bodyTarget":"traps","percentage":15}]},{"name":"Reverse Grip Concentration Curl","description":"Seated with the elbow braced against the inner thigh, you curl a dumbbell using an overhand grip. Combining strict concentration-curl isolation with the pronated grip puts focused work on the brachialis and forearm while limiting all momentum.","descriptionAr":"جالساً مع إسناد المرفق إلى داخل الفخذ، تثني دمبلاً بقبضة علوية. يجمع التمرين بين عزل ثني التركيز الصارم والقبضة العلوية ليضع جهداً مركزاً على العضلة العضدية والساعد مع منع أي زخم.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"biceps","percentage":60},{"bodyTarget":"forearms","percentage":40}]},{"name":"Reverse Grip Lat Pulldown (Cable)","description":"A lat pulldown performed with a shoulder-width underhand grip, pulling the bar to the upper chest. The supinated grip increases biceps involvement and lets the elbows track close to the body, emphasizing the lower lat fibers.","descriptionAr":"سحب علوي يُؤدى بقبضة سفلية بعرض الكتفين مع جذب البار إلى أعلى الصدر. تزيد القبضة السفلية مشاركة العضلة ذات الرأسين وتتيح مرور المرفقين قريباً من الجسم، مركزة على الألياف السفلية للعضلة الظهرية العريضة.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"lats","percentage":55},{"bodyTarget":"biceps","percentage":25},{"bodyTarget":"upper_back","percentage":10},{"bodyTarget":"shoulders_posterior","percentage":10}]},{"name":"Reverse Grip Triceps Pushdown","description":"A cable pushdown performed with the palms facing up, extending the arms fully while the elbows stay pinned. The underhand grip keeps the wrists locked and shifts emphasis toward the medial head of the triceps for a strong lockout.","descriptionAr":"دفع لأسفل على الكابل يُؤدى وراحتا اليدين إلى الأعلى، بمد الذراعين بالكامل مع ثبات المرفقين. تثبّت القبضة السفلية المعصمين وتنقل التركيز نحو الرأس الإنسي للعضلة ثلاثية الرؤوس من أجل امتداد نهائي قوي.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"triceps","percentage":80},{"bodyTarget":"forearms","percentage":20}]},{"name":"Reverse Hyperextension","description":"Lying face-down on a bench or reverse-hyper machine with the legs hanging free, you swing the legs up until they are level with the torso. It strengthens the glutes, hamstrings, and spinal erectors while gently decompressing the lower back instead of loading it.","descriptionAr":"مستلقياً على البطن فوق مقعد أو جهاز مخصص مع تدلي الساقين، ترفع الساقين حتى تصبحا بمستوى الجذع. يقوي التمرين الألوية وأوتار الركبة وناصبات الفقار مع تخفيف الضغط بلطف عن أسفل الظهر بدلاً من تحميله.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"glutes","percentage":50},{"bodyTarget":"hamstrings","percentage":25},{"bodyTarget":"erector_spinae","percentage":25}]},{"name":"Reverse Lunge","description":"A bodyweight lunge in which you step backward, lower the rear knee toward the floor, and drive back up through the front leg. It is a knee-friendly way to build single-leg strength and balance in the quads, glutes, and hamstrings.","descriptionAr":"طعن بوزن الجسم تخطو فيه إلى الخلف وتخفض الركبة الخلفية نحو الأرض ثم تدفع عائداً عبر الساق الأمامية. وهو أسلوب لطيف على الركبة لبناء قوة وتوازن الساق الواحدة في رباعية الرؤوس والألوية وأوتار الركبة.","measurement":"reps","types":["Leg Day","Calisthenics"],"targets":[{"bodyTarget":"quadriceps","percentage":50},{"bodyTarget":"glutes","percentage":30},{"bodyTarget":"hamstrings","percentage":20}]},{"name":"Reverse Lunge (Barbell)","description":"With a barbell on the upper back, you step one leg backward and lower into a lunge before driving back to standing. Stepping backward keeps the front shin more vertical than a forward lunge, loading the quads and glutes with less knee stress.","descriptionAr":"مع بار على أعلى الظهر، تخطو بساق واحدة إلى الخلف وتنزل في وضع الطعن ثم تدفع عائداً للوقوف. تُبقي الخطوة الخلفية ساق الأمام أكثر عمودية من الطعن الأمامي، فتحمّل رباعية الرؤوس والألوية بإجهاد أقل على الركبة.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"quadriceps","percentage":50},{"bodyTarget":"glutes","percentage":30},{"bodyTarget":"hamstrings","percentage":20}]},{"name":"Reverse Lunge (Dumbbell)","description":"Holding a dumbbell in each hand at your sides, you step backward into a lunge and push through the front heel to return. The dumbbells load the quads, glutes, and hamstrings while also challenging grip and upright posture.","descriptionAr":"حاملاً دمبلاً في كل يد إلى جانبيك، تخطو للخلف في وضع الطعن ثم تدفع بكعب القدم الأمامية للعودة. تحمّل الدمبلات رباعية الرؤوس والألوية وأوتار الركبة مع تحدٍ إضافي للقبضة واستقامة الجذع.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"quadriceps","percentage":50},{"bodyTarget":"glutes","percentage":30},{"bodyTarget":"hamstrings","percentage":20}]},{"name":"Reverse Plank","description":"Sitting with the hands behind the hips, you lift the pelvis until the body forms a straight line facing upward and hold the position. The isometric hold strengthens the posterior chain and core together while opening the shoulders and hips.","descriptionAr":"جالساً واليدان خلف الوركين، ترفع الحوض حتى يشكل الجسم خطاً مستقيماً متجهاً للأعلى وتثبت على الوضع. يقوي هذا الثبات المتساوي القياس السلسلة الخلفية والجذع معاً مع فتح الكتفين والوركين.","measurement":"time_hold","types":["Core","Calisthenics"],"targets":[{"bodyTarget":"core_abs","percentage":35},{"bodyTarget":"glutes","percentage":30},{"bodyTarget":"hamstrings","percentage":20},{"bodyTarget":"erector_spinae","percentage":15}]},{"name":"Reverse Wrist Curl (Dumbbell)","description":"With the forearm supported and palm facing down, you raise the back of the hand upward against the dumbbell's resistance. It isolates the wrist extensors on top of the forearm, balancing gripping work and helping protect the elbow from overuse strain.","descriptionAr":"مع إسناد الساعد وتوجيه راحة اليد إلى الأسفل، ترفع ظهر اليد إلى الأعلى ضد مقاومة الدمبل. يعزل التمرين باسطات المعصم أعلى الساعد، موازناً تمارين القبض ومساعداً على وقاية المرفق من إجهاد الاستخدام المفرط.","measurement":"reps","types":["Upper Body"],"targets":[{"bodyTarget":"forearms","percentage":90},{"bodyTarget":"biceps","percentage":10}]},{"name":"Romanian Deadlift (Barbell)","description":"Starting from standing, you hinge at the hips and lower the barbell along the thighs with a flat back and slightly bent knees, then drive the hips forward to stand. It loads the hamstrings and glutes through a deep stretch, making it a cornerstone for posterior-chain strength.","descriptionAr":"من وضع الوقوف، تنحني من الوركين وتنزل البار محاذياً للفخذين بظهر مستقيم وركبتين شبه مثنيتين، ثم تدفع الوركين للأمام للوقوف. يحمّل التمرين أوتار الركبة والألوية عبر إطالة عميقة، مما يجعله ركيزة لقوة السلسلة الخلفية.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"hamstrings","percentage":50},{"bodyTarget":"glutes","percentage":30},{"bodyTarget":"erector_spinae","percentage":20}]},{"name":"Romanian Deadlift (Dumbbell)","description":"Holding dumbbells in front of the thighs, you push the hips back and lower the weights down the legs with a neutral spine before returning to standing. The dumbbell version allows a natural bar path and is an accessible way to learn and load the hip hinge.","descriptionAr":"حاملاً دمبلين أمام الفخذين، تدفع الوركين للخلف وتنزل الوزنين على امتداد الساقين بعمود فقري محايد ثم تعود للوقوف. تتيح نسخة الدمبل مساراً طبيعياً للحركة وتُعد وسيلة ميسّرة لتعلم انحناء الورك وتحميله.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"hamstrings","percentage":50},{"bodyTarget":"glutes","percentage":30},{"bodyTarget":"erector_spinae","percentage":20}]},{"name":"Romanian Deadlift (Smith Machine)","description":"A Romanian deadlift performed on the Smith machine's fixed vertical track, hinging at the hips as the bar slides down the thighs. The guided path removes the balance demand, letting you concentrate purely on stretching and contracting the hamstrings and glutes.","descriptionAr":"رفعة رومانية تُؤدى على المسار العمودي الثابت لجهاز سميث، بالانحناء من الوركين بينما ينزلق البار على الفخذين. يلغي المسار الموجه الحاجة إلى التوازن، فيتيح التركيز الكامل على إطالة أوتار الركبة والألوية وانقباضهما.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"hamstrings","percentage":50},{"bodyTarget":"glutes","percentage":30},{"bodyTarget":"erector_spinae","percentage":20}]},{"name":"Rope Cable Curl","description":"You curl a rope attachment from a low cable using a neutral, hammer-style grip, splitting the rope ends apart at the top. The grip and constant cable tension develop the biceps together with the brachialis and brachioradialis for thicker arms.","descriptionAr":"تثني حبلاً متصلاً ببكرة منخفضة بقبضة محايدة على طريقة المطرقة، مع فصل طرفي الحبل في الأعلى. تنمّي القبضة وشد الكابل المستمر العضلة ذات الرأسين مع العضدية والعضدية الكعبرية لذراعين أكثر سماكة.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"biceps","percentage":70},{"bodyTarget":"forearms","percentage":30}]},{"name":"Rope Straight Arm Pulldown","description":"With arms nearly straight, you pull a rope from overhead down to the thighs in a wide arc, hinging slightly at the hips. Keeping the elbows extended removes the biceps from the pull, isolating the lats and teaching the mind-muscle connection used in rows and pulldowns.","descriptionAr":"بذراعين شبه ممدودتين، تسحب حبلاً من فوق الرأس نزولاً إلى الفخذين في قوس واسع مع انحناء بسيط من الوركين. يُخرج مد المرفقين العضلة ذات الرأسين من الحركة، فيعزل العضلة الظهرية العريضة ويعلّم الاتصال العصبي العضلي المستخدم في التجديف والسحب.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"lats","percentage":70},{"bodyTarget":"triceps","percentage":15},{"bodyTarget":"core_abs","percentage":15}]},{"name":"Running","description":"A fundamental aerobic exercise in which you sustain a rhythmic stride outdoors or on a track, elevating heart rate for extended periods. Regular running strengthens the heart and lungs, builds leg endurance, and supports calorie expenditure and mental wellbeing.","descriptionAr":"تمرين هوائي أساسي تحافظ فيه على خطوات إيقاعية في الهواء الطلق أو على مضمار، رافعاً معدل ضربات القلب لفترات ممتدة. يقوي الجري المنتظم القلب والرئتين، ويبني تحمل الساقين، ويدعم حرق السعرات والصحة النفسية.","measurement":"distance_duration","types":["Cardio"],"targets":[{"bodyTarget":"cardiovascular","percentage":50},{"bodyTarget":"endurance","percentage":25},{"bodyTarget":"quadriceps","percentage":15},{"bodyTarget":"calves","percentage":10}]},{"name":"Russian Twist (Bodyweight)","description":"Sit with the torso leaned back and heels raised, then rotate the trunk from side to side under control. This trains the obliques and rectus abdominis, building rotational strength and core stability.","descriptionAr":"اجلس مع إمالة الجذع إلى الخلف ورفع الكعبين، ثم قم بتدوير الجذع من جانب إلى آخر بتحكم. يقوي هذا التمرين العضلات المائلة وعضلة البطن المستقيمة، ويبني القوة الدورانية وثبات الجذع.","measurement":"reps","types":["Core","Calisthenics"],"targets":[{"bodyTarget":"core_abs","percentage":55},{"bodyTarget":"obliques","percentage":45}]},{"name":"Russian Twist (Weighted)","description":"Holding a plate or dumbbell at the chest, lean the torso back and rotate side to side while keeping the spine long. The added load increases the demand on the obliques and deep core for greater rotational strength.","descriptionAr":"أمسك قرصًا أو دمبل أمام الصدر، وأمل الجذع إلى الخلف ثم قم بالتدوير من جانب إلى آخر مع إبقاء العمود الفقري مستقيمًا. يزيد الوزن الإضافي الحمل على العضلات المائلة وعضلات الجذع لبناء قوة دورانية أكبر.","measurement":"reps","types":["Core"],"targets":[{"bodyTarget":"core_abs","percentage":55},{"bodyTarget":"obliques","percentage":45}]},{"name":"Seal Row (Barbell)","description":"Lying face down on an elevated bench, row a barbell to the underside of the bench with no body momentum. This strictly isolates the mid and upper back, lats, and rear delts while removing lower-back strain.","descriptionAr":"استلقِ على بطنك فوق مقعد مرتفع واسحب البار نحو أسفل المقعد دون أي اندفاع من الجسم. يعزل هذا التمرين عضلات الظهر العلوية والوسطى والعضلة الظهرية العريضة والكتف الخلفي مع إزالة الإجهاد عن أسفل الظهر.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"upper_back","percentage":55},{"bodyTarget":"lats","percentage":20},{"bodyTarget":"biceps","percentage":15},{"bodyTarget":"shoulders_posterior","percentage":10}]},{"name":"Seal Row (Dumbbell)","description":"Lying chest-down on an elevated bench, row a dumbbell in each hand toward your hips without swinging. It builds the upper back, lats, and rear delts with strict form and zero lower-back loading.","descriptionAr":"استلقِ على صدرك فوق مقعد مرتفع واسحب دمبل في كل يد نحو الوركين دون تأرجح. يبني هذا التمرين الظهر العلوي والعضلة الظهرية العريضة والكتف الخلفي بأداء صارم ودون تحميل على أسفل الظهر.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"upper_back","percentage":55},{"bodyTarget":"lats","percentage":20},{"bodyTarget":"biceps","percentage":15},{"bodyTarget":"shoulders_posterior","percentage":10}]},{"name":"Seated Cable Row - Bar Grip","description":"Seated at a cable station, pull a straight bar to your torso while keeping the chest tall and squeezing the shoulder blades together. It develops the mid-back, lats, and biceps and reinforces good pulling posture.","descriptionAr":"اجلس أمام جهاز الكابل واسحب البار المستقيم نحو جذعك مع إبقاء الصدر مرفوعًا وضم لوحي الكتف معًا. يطور هذا التمرين منتصف الظهر والعضلة الظهرية العريضة والعضلة ذات الرأسين ويعزز وضعية سحب سليمة.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"upper_back","percentage":50},{"bodyTarget":"lats","percentage":25},{"bodyTarget":"biceps","percentage":15},{"bodyTarget":"shoulders_posterior","percentage":10}]},{"name":"Seated Cable Row - Bar Wide Grip","description":"Using a wide overhand grip on the bar, row toward the upper abdomen with elbows flared slightly out. The wider grip shifts emphasis to the mid-traps, rhomboids, and rear delts for a thicker upper back.","descriptionAr":"باستخدام قبضة واسعة على البار، اسحب نحو أعلى البطن مع فتح المرفقين قليلاً إلى الخارج. تنقل القبضة الواسعة التركيز إلى منتصف الظهر والعضلات المعينية والكتف الخلفي لبناء ظهر علوي أكثر سماكة.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"upper_back","percentage":55},{"bodyTarget":"shoulders_posterior","percentage":15},{"bodyTarget":"lats","percentage":15},{"bodyTarget":"biceps","percentage":15}]},{"name":"Seated Cable Row - V Grip (Cable)","description":"With a narrow V-handle, pull toward the lower ribs while keeping the elbows close to the body. The neutral close grip emphasizes the lats and mid-back through a long range of motion and allows heavy, controlled loading.","descriptionAr":"باستخدام مقبض V الضيق، اسحب نحو أسفل الأضلاع مع إبقاء المرفقين قريبين من الجسم. تركز القبضة الضيقة المحايدة على العضلة الظهرية العريضة ومنتصف الظهر عبر مدى حركة طويل وتسمح بتحميل ثقيل ومنضبط.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"upper_back","percentage":50},{"bodyTarget":"lats","percentage":25},{"bodyTarget":"biceps","percentage":15},{"bodyTarget":"shoulders_posterior","percentage":10}]},{"name":"Seated Chest Flys (Cable)","description":"Seated between two cable columns, bring the handles together in a wide arc in front of the chest with slightly bent elbows. Constant cable tension isolates the pectorals through their full adduction range and builds inner-chest definition.","descriptionAr":"اجلس بين عمودي الكابل واجمع المقبضين في قوس واسع أمام الصدر مع ثني المرفقين قليلاً. يوفر الكابل شدًا مستمرًا يعزل العضلات الصدرية عبر كامل مدى التقريب ويحسن تحديد منتصف الصدر.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"chest","percentage":75},{"bodyTarget":"shoulders_anterior","percentage":15},{"bodyTarget":"biceps","percentage":10}]},{"name":"Seated Dip Machine","description":"Seated with hands on the machine's handles, press downward until the arms are fully extended. It replicates the dip movement to load the triceps, lower chest, and front delts with guided stability that suits progressive overload.","descriptionAr":"اجلس وضع يديك على مقبضي الجهاز ثم اضغط للأسفل حتى يمتد الذراعان بالكامل. يحاكي هذا الجهاز حركة الغطس لتحميل العضلة ثلاثية الرؤوس وأسفل الصدر والكتف الأمامي بثبات موجه يناسب زيادة الأحمال التدريجية.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"triceps","percentage":60},{"bodyTarget":"chest","percentage":25},{"bodyTarget":"shoulders_anterior","percentage":15}]},{"name":"Seated Incline Curl (Dumbbell)","description":"Sitting back on an incline bench with arms hanging behind the torso, curl the dumbbells up without moving the elbows forward. The stretched starting position emphasizes the long head of the biceps for fuller arm development.","descriptionAr":"اجلس على مقعد مائل مع تدلي الذراعين خلف الجذع، ثم ارفع الدمبل للأعلى دون تحريك المرفقين للأمام. تركز وضعية البداية الممدودة على الرأس الطويل للعضلة ذات الرأسين لتطوير أكمل للذراع.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"biceps","percentage":80},{"bodyTarget":"forearms","percentage":20}]},{"name":"Seated Incline Hammer Curl (Dumbbell)","description":"On an incline bench with a neutral (palms-facing) grip, curl the dumbbells while the arms start in a deep stretch behind the body. The hammer grip shifts load toward the brachialis and brachioradialis, thickening the arm and forearm.","descriptionAr":"على مقعد مائل وبقبضة محايدة (راحتا اليدين متقابلتان)، ارفع الدمبل بينما يبدأ الذراعان في وضع تمدد عميق خلف الجسم. تنقل قبضة المطرقة الحمل نحو العضلة العضدية والعضدية الكعبرية مما يزيد سماكة الذراع والساعد.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"biceps","percentage":60},{"bodyTarget":"forearms","percentage":40}]},{"name":"Seated Lateral Raise (Dumbbell)","description":"Seated upright, raise the dumbbells out to the sides until the arms are near shoulder height, then lower slowly. Sitting removes leg drive and body swing, isolating the lateral deltoids for wider-looking shoulders.","descriptionAr":"اجلس بوضع مستقيم وارفع الدمبل جانبًا حتى يقترب الذراعان من مستوى الكتف، ثم اخفضهما ببطء. يمنع الجلوس دفع الساقين وتأرجح الجسم، فيعزل الرأس الجانبي للكتف لمظهر أعرض للأكتاف.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"shoulders_lateral","percentage":75},{"bodyTarget":"traps","percentage":15},{"bodyTarget":"shoulders_anterior","percentage":10}]},{"name":"Seated Leg Curl (Machine)","description":"Seated with the pad above the ankles, curl the legs down and back against resistance, then return under control. The seated hip angle keeps the hamstrings lengthened, making it one of the most effective isolation moves for hamstring growth.","descriptionAr":"اجلس مع وضع الوسادة فوق الكاحلين، ثم اثنِ الساقين للأسفل والخلف ضد المقاومة وعد بتحكم. تحافظ زاوية الورك في الجلوس على استطالة العضلات الخلفية للفخذ، مما يجعله من أكثر تمارين العزل فعالية لتنميتها.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"hamstrings","percentage":80},{"bodyTarget":"calves","percentage":20}]},{"name":"Seated Overhead Press (Barbell)","description":"Seated with back support, press a barbell from the clavicles to full lockout overhead. The seated position stabilizes the torso so the deltoids and triceps can be loaded heavily for pressing strength and shoulder mass.","descriptionAr":"اجلس مع دعم الظهر وادفع البار من مستوى الترقوة حتى الامتداد الكامل فوق الرأس. تثبّت وضعية الجلوس الجذع بحيث يمكن تحميل عضلات الكتف والعضلة ثلاثية الرؤوس بأوزان ثقيلة لبناء قوة الدفع وكتلة الكتف.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"shoulders_anterior","percentage":55},{"bodyTarget":"triceps","percentage":25},{"bodyTarget":"shoulders_lateral","percentage":20}]},{"name":"Seated Overhead Press (Dumbbell)","description":"Seated with dumbbells at shoulder height, press both weights overhead until the arms lock out, then lower with control. Dumbbells demand independent stabilization from each shoulder, correcting side-to-side strength imbalances.","descriptionAr":"اجلس مع الدمبل عند مستوى الكتف وادفع الوزنين فوق الرأس حتى امتداد الذراعين بالكامل، ثم اخفضهما بتحكم. تتطلب الدمبل تثبيتًا مستقلاً من كل كتف، مما يصحح فروق القوة بين الجانبين.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"shoulders_anterior","percentage":55},{"bodyTarget":"triceps","percentage":25},{"bodyTarget":"shoulders_lateral","percentage":20}]},{"name":"Seated Palms Up Wrist Curl","description":"With forearms resting on your thighs and palms facing up, let the weight roll toward the fingers, then curl the wrists upward. This isolates the wrist flexors, building forearm size and grip strength.","descriptionAr":"ضع الساعدين على الفخذين وراحتا اليدين للأعلى، ودع الوزن ينزلق نحو الأصابع ثم اثنِ الرسغين للأعلى. يعزل هذا التمرين عضلات ثني الرسغ ويبني حجم الساعد وقوة القبضة.","measurement":"reps","types":["Upper Body"],"targets":[{"bodyTarget":"forearms","percentage":90},{"bodyTarget":"biceps","percentage":10}]},{"name":"Seated Row (Machine)","description":"With the chest braced against the machine pad, pull the handles toward the torso and squeeze the shoulder blades together. The fixed path and chest support isolate the mid-back and lats while eliminating momentum and lower-back stress.","descriptionAr":"اسند الصدر إلى وسادة الجهاز واسحب المقبضين نحو الجذع مع ضم لوحي الكتف. يعزل المسار الثابت ودعم الصدر منتصف الظهر والعضلة الظهرية العريضة مع إزالة الاندفاع والإجهاد عن أسفل الظهر.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"upper_back","percentage":50},{"bodyTarget":"lats","percentage":25},{"bodyTarget":"biceps","percentage":15},{"bodyTarget":"shoulders_posterior","percentage":10}]},{"name":"Seated Shoulder Press (Machine)","description":"Seated in the machine, press the handles overhead along a guided path until the arms extend fully. The fixed track stabilizes the movement, letting you overload the deltoids and triceps safely even near failure.","descriptionAr":"اجلس في الجهاز وادفع المقبضين فوق الرأس على مسار موجه حتى يمتد الذراعان بالكامل. يثبّت المسار الثابت الحركة، مما يتيح تحميل عضلات الكتف والعضلة ثلاثية الرؤوس بأمان حتى قرب الإجهاد الكامل.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"shoulders_anterior","percentage":55},{"bodyTarget":"triceps","percentage":25},{"bodyTarget":"shoulders_lateral","percentage":20}]},{"name":"Seated Triceps Press","description":"Seated with the weight held overhead, lower it behind the head by bending the elbows, then extend the arms back to lockout. The overhead position places the triceps' long head under a deep stretch, which strongly stimulates growth.","descriptionAr":"اجلس مع حمل الوزن فوق الرأس، ثم اخفضه خلف الرأس بثني المرفقين وعد بمد الذراعين حتى الامتداد الكامل. تضع الوضعية فوق الرأس الرأس الطويل للعضلة ثلاثية الرؤوس تحت تمدد عميق يحفز النمو بقوة.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"triceps","percentage":85},{"bodyTarget":"shoulders_anterior","percentage":15}]},{"name":"Seated Wrist Curl (Barbell)","description":"With forearms supported on the thighs or a bench and palms up, flex the wrists to curl the barbell upward, then lower slowly. It targets the wrist flexors to develop forearm mass and a stronger grip.","descriptionAr":"اسند الساعدين على الفخذين أو على مقعد وراحتا اليدين للأعلى، ثم اثنِ الرسغين لرفع البار وأنزله ببطء. يستهدف هذا التمرين عضلات ثني الرسغ لتنمية كتلة الساعد وتقوية القبضة.","measurement":"reps","types":["Upper Body"],"targets":[{"bodyTarget":"forearms","percentage":90},{"bodyTarget":"biceps","percentage":10}]},{"name":"Seated Wrist Extension (Barbell)","description":"With forearms supported and palms facing down, raise the back of the hands upward against the barbell's resistance, then lower under control. It strengthens the often-neglected wrist extensors, balancing forearm development and protecting the elbows and wrists.","descriptionAr":"اسند الساعدين وراحتا اليدين للأسفل، ثم ارفع ظهر اليدين للأعلى ضد مقاومة البار وأنزله بتحكم. يقوي هذا التمرين عضلات بسط الرسغ المهملة غالبًا، مما يوازن تطور الساعد ويحمي المرفقين والرسغين.","measurement":"reps","types":["Upper Body"],"targets":[{"bodyTarget":"forearms","percentage":90},{"bodyTarget":"triceps","percentage":10}]},{"name":"Shoulder Press (Dumbbell)","description":"Hold a dumbbell at each shoulder and press both overhead until the arms are fully extended, then lower with control. It is a foundational builder of deltoid and triceps strength that also trains shoulder stability through a free range of motion.","descriptionAr":"أمسك دمبل عند كل كتف وادفع الوزنين فوق الرأس حتى امتداد الذراعين بالكامل، ثم اخفضهما بتحكم. يعد هذا التمرين أساسيًا لبناء قوة الكتف والعضلة ثلاثية الرؤوس، كما يدرب ثبات الكتف عبر مدى حركة حر.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"shoulders_anterior","percentage":55},{"bodyTarget":"triceps","percentage":25},{"bodyTarget":"shoulders_lateral","percentage":20}]},{"name":"Shoulder Press (Machine Plates)","description":"On a plate-loaded press machine, push the handles overhead along the machine's arc until the elbows extend. The guided movement removes balance demands so the delts and triceps can be trained hard with heavy, safe loading.","descriptionAr":"على جهاز الضغط المحمّل بالأقراص، ادفع المقبضين فوق الرأس على مسار الجهاز حتى امتداد المرفقين. تزيل الحركة الموجهة متطلبات التوازن ليتم تدريب عضلات الكتف والعضلة ثلاثية الرؤوس بأحمال ثقيلة وآمنة.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"shoulders_anterior","percentage":55},{"bodyTarget":"triceps","percentage":25},{"bodyTarget":"shoulders_lateral","percentage":20}]},{"name":"Shoulder Taps","description":"From a high plank, lift one hand to tap the opposite shoulder while keeping the hips completely still, alternating sides. It builds shoulder stability and anti-rotation core strength using only bodyweight.","descriptionAr":"من وضعية البلانك العالية، ارفع يدًا واحدة للمس الكتف المقابل مع إبقاء الوركين ثابتين تمامًا، وبالتناوب بين الجانبين. يبني هذا التمرين ثبات الكتف وقوة الجذع المقاومة للدوران باستخدام وزن الجسم فقط.","measurement":"reps","types":["Core","Calisthenics"],"targets":[{"bodyTarget":"shoulders_anterior","percentage":45},{"bodyTarget":"core_abs","percentage":30},{"bodyTarget":"triceps","percentage":15},{"bodyTarget":"core_deep","percentage":10}]},{"name":"Shrug (Barbell)","description":"Holding a barbell at arm's length, elevate the shoulders straight up toward the ears, pause, and lower slowly. It directly loads the upper trapezius for neck and upper-back mass while also challenging grip strength.","descriptionAr":"أمسك البار بذراعين ممدودتين وارفع الكتفين مباشرة نحو الأذنين، ثم توقف لحظة واخفضهما ببطء. يحمّل هذا التمرين العضلة شبه المنحرفة العلوية مباشرة لبناء كتلة الرقبة وأعلى الظهر، كما يتحدى قوة القبضة.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"traps","percentage":85},{"bodyTarget":"forearms","percentage":15}]},{"name":"Shrug (Cable)","description":"Standing at a low cable, grip the handle or bar and raise the shoulders toward the ears against constant cable tension. The cable keeps the traps loaded through the entire range, including the bottom stretch.","descriptionAr":"قف أمام كابل منخفض وأمسك المقبض أو البار ثم ارفع الكتفين نحو الأذنين ضد شد الكابل المستمر. يحافظ الكابل على تحميل العضلة شبه المنحرفة عبر كامل مدى الحركة بما في ذلك وضع التمدد السفلي.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"traps","percentage":85},{"bodyTarget":"forearms","percentage":15}]},{"name":"Shrug (Dumbbell)","description":"With a dumbbell in each hand at your sides, lift the shoulders straight up as high as possible, then lower under control. The neutral dumbbell position allows a natural range of motion and works the upper traps and grip together.","descriptionAr":"أمسك دمبل في كل يد على جانبي الجسم وارفع الكتفين للأعلى إلى أقصى حد، ثم اخفضهما بتحكم. تتيح وضعية الدمبل المحايدة مدى حركة طبيعيًا وتعمل على العضلة شبه المنحرفة العلوية والقبضة معًا.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"traps","percentage":85},{"bodyTarget":"forearms","percentage":15}]},{"name":"Shrug (Machine)","description":"Using a shrug machine's handles or pads, elevate the shoulders as high as possible and squeeze at the top. The guided load path lets you isolate the upper trapezius with heavy weight and minimal grip limitation.","descriptionAr":"باستخدام مقابض جهاز الشرغ أو وسائده، ارفع الكتفين إلى أقصى ارتفاع واضغط في الأعلى. يتيح مسار الحمل الموجه عزل العضلة شبه المنحرفة العلوية بوزن ثقيل مع حد أدنى من قيود القبضة.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"traps","percentage":90},{"bodyTarget":"forearms","percentage":10}]},{"name":"Shrug (Smith Machine)","description":"With the Smith machine bar held at arm's length, shrug the shoulders straight up along the fixed vertical track. The stabilized bar path removes balance demands so the upper traps can be overloaded safely.","descriptionAr":"أمسك بار جهاز سميث بذراعين ممدودتين وارفع الكتفين للأعلى على المسار العمودي الثابت. يزيل مسار البار المستقر متطلبات التوازن مما يسمح بتحميل العضلة شبه المنحرفة العلوية بأمان.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"traps","percentage":90},{"bodyTarget":"forearms","percentage":10}]},{"name":"Side Bend","description":"Standing tall with hands at your sides or behind the head, bend the torso to one side and return upright without twisting. This bodyweight movement activates the obliques and improves lateral trunk mobility and control.","descriptionAr":"قف مستقيمًا ويداك على الجانبين أو خلف الرأس، ثم أمل الجذع إلى جانب واحد وعد إلى الوضع المستقيم دون التواء. ينشط هذا التمرين بوزن الجسم العضلات المائلة ويحسن حركة الجذع الجانبية والتحكم فيها.","measurement":"reps","types":["Core","Calisthenics"],"targets":[{"bodyTarget":"obliques","percentage":65},{"bodyTarget":"core_abs","percentage":25},{"bodyTarget":"erector_spinae","percentage":10}]},{"name":"Side Bend (Dumbbell)","description":"Standing with a dumbbell in one hand, bend the torso sideways toward the weight, then pull back upright using the opposite obliques. It strengthens lateral trunk flexion and builds oblique strength for a stable, resilient waist.","descriptionAr":"قف ممسكًا بدمبل في يد واحدة وأمل الجذع جانبيًا نحو الوزن، ثم عد إلى الوضع المستقيم باستخدام العضلات المائلة في الجانب المقابل. يقوي هذا التمرين الانثناء الجانبي للجذع ويبني عضلات مائلة قوية لخصر ثابت ومتين.","measurement":"reps","types":["Core"],"targets":[{"bodyTarget":"obliques","percentage":65},{"bodyTarget":"core_abs","percentage":25},{"bodyTarget":"erector_spinae","percentage":10}]},{"name":"Single Arm Cable Crossover","description":"Standing side-on to a cable column, sweep one handle across the body toward the opposite hip or chest line. Working one side at a time gives the pecs a full adduction range and forces the core to resist rotation.","descriptionAr":"قف بجانب عمود الكابل واسحب المقبض بيد واحدة عبر الجسم نحو خط الورك أو الصدر المقابل. يمنح العمل بجانب واحد العضلة الصدرية مدى تقريب كاملاً ويجبر الجذع على مقاومة الدوران.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"chest","percentage":70},{"bodyTarget":"shoulders_anterior","percentage":20},{"bodyTarget":"core_abs","percentage":10}]},{"name":"Single Arm Cable Row","description":"Facing a cable with one handle, pull it toward your torso while keeping the shoulders square and the trunk braced. Unilateral rowing evens out left-right back strength and allows extra scapular range on each pull.","descriptionAr":"واجه الكابل وأمسك المقبض بيد واحدة واسحبه نحو جذعك مع إبقاء الكتفين متوازيين والجذع مشدودًا. يعالج التجديف بذراع واحدة الفروق في قوة الظهر بين الجانبين ويتيح مدى حركة إضافيًا للوح الكتف في كل سحبة.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"upper_back","percentage":45},{"bodyTarget":"lats","percentage":25},{"bodyTarget":"biceps","percentage":20},{"bodyTarget":"shoulders_posterior","percentage":10}]},{"name":"Single Arm Curl (Cable)","description":"Standing beside a low cable, curl the handle upward with one arm while keeping the elbow pinned to your side. The cable's constant tension keeps the biceps working through the whole rep, and single-arm work corrects strength imbalances.","descriptionAr":"قف بجانب كابل منخفض وارفع المقبض بذراع واحدة مع تثبيت المرفق إلى جانب الجسم. يحافظ الشد المستمر للكابل على عمل العضلة ذات الرأسين طوال التكرار، ويصحح العمل بذراع واحدة فروق القوة بين الجانبين.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"biceps","percentage":80},{"bodyTarget":"forearms","percentage":20}]},{"name":"Single Arm Landmine Press (Barbell)","description":"With one end of the barbell anchored in a landmine, press the other end up and forward with one arm. The angled bar path is friendly to the shoulder joint while training the delts, triceps, upper chest, and anti-rotation core strength.","descriptionAr":"ثبّت أحد طرفي البار في قاعدة اللاندماين وادفع الطرف الآخر للأعلى وللأمام بذراع واحدة. مسار البار المائل لطيف على مفصل الكتف بينما يدرب عضلات الكتف والعضلة ثلاثية الرؤوس وأعلى الصدر وقوة الجذع المقاومة للدوران.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"shoulders_anterior","percentage":50},{"bodyTarget":"triceps","percentage":20},{"bodyTarget":"chest","percentage":15},{"bodyTarget":"core_abs","percentage":15}]},{"name":"Single Arm Lat Pulldown","description":"Seated or kneeling at a cable, pull a single handle down toward the side of your chest, driving the elbow to the hip. One-arm pulldowns give the lat a longer range and stronger contraction while fixing side-to-side pulling imbalances.","descriptionAr":"اجلس أو اركع أمام الكابل واسحب المقبض بيد واحدة نحو جانب صدرك مع دفع المرفق باتجاه الورك. يمنح السحب بذراع واحدة العضلة الظهرية العريضة مدى أطول وانقباضًا أقوى مع تصحيح فروق السحب بين الجانبين.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"lats","percentage":60},{"bodyTarget":"biceps","percentage":20},{"bodyTarget":"upper_back","percentage":10},{"bodyTarget":"shoulders_posterior","percentage":10}]},{"name":"Single Arm Lateral Raise (Cable)","description":"Standing side-on to a low cable, raise the handle out to the side until the arm reaches shoulder height. The cable loads the side delt even at the bottom of the movement, giving more consistent tension than dumbbells.","descriptionAr":"قف بجانب كابل منخفض وارفع المقبض جانبيًا حتى يصل الذراع إلى مستوى الكتف. يحمّل الكابل الرأس الجانبي للكتف حتى في أسفل الحركة، مما يوفر شدًا أكثر ثباتًا من الدمبل.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"shoulders_lateral","percentage":75},{"bodyTarget":"traps","percentage":15},{"bodyTarget":"shoulders_anterior","percentage":10}]},{"name":"Single Arm Tricep Extension (Dumbbell)","description":"Holding a dumbbell overhead with one arm, lower it behind the head by bending the elbow, then extend back to lockout. The overhead single-arm position deeply stretches the triceps' long head and isolates each arm for balanced development.","descriptionAr":"أمسك دمبل فوق الرأس بذراع واحدة واخفضه خلف الرأس بثني المرفق، ثم مد الذراع حتى الامتداد الكامل. تمدد الوضعية فوق الرأس الرأس الطويل للعضلة ثلاثية الرؤوس بعمق وتعزل كل ذراع لتطور متوازن.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"triceps","percentage":85},{"bodyTarget":"shoulders_anterior","percentage":15}]},{"name":"Single Arm Triceps Pushdown (Cable)","description":"Facing a high cable, press the single handle down with one arm until the elbow is fully extended, keeping the upper arm still. Working one arm at a time isolates the triceps and lets you focus on a hard contraction at lockout.","descriptionAr":"واجه الكابل العالي وادفع المقبض للأسفل بذراع واحدة حتى امتداد المرفق بالكامل مع تثبيت العضد. يعزل العمل بذراع واحدة العضلة ثلاثية الرؤوس ويتيح التركيز على انقباض قوي عند الامتداد الكامل.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"triceps","percentage":85},{"bodyTarget":"forearms","percentage":15}]},{"name":"Single Leg Extensions","description":"Seated in the leg extension machine, extend one knee at a time until the leg is straight, then lower slowly. Training each leg alone isolates the quadriceps and corrects strength differences between legs.","descriptionAr":"اجلس في جهاز مد الساق ومد ركبة واحدة في كل مرة حتى تستقيم الساق، ثم اخفضها ببطء. يعزل تدريب كل ساق على حدة العضلة رباعية الرؤوس ويصحح فروق القوة بين الساقين.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"quadriceps","percentage":90},{"bodyTarget":"hip_flexors","percentage":10}]},{"name":"Single Leg Glute Bridge","description":"Lying on your back with one foot planted and the other leg extended, drive the hips up until the body forms a straight line. It isolates one glute at a time, building hip extension strength and pelvic stability without equipment.","descriptionAr":"استلقِ على ظهرك مع تثبيت قدم واحدة ومد الساق الأخرى، ثم ادفع الوركين للأعلى حتى يشكل الجسم خطًا مستقيمًا. يعزل هذا التمرين عضلة الألوية في كل جانب على حدة، ويبني قوة مد الورك وثبات الحوض دون معدات.","measurement":"reps","types":["Leg Day","Lower Body","Calisthenics"],"targets":[{"bodyTarget":"glutes","percentage":60},{"bodyTarget":"hamstrings","percentage":25},{"bodyTarget":"erector_spinae","percentage":15}]},{"name":"Single Leg Hip Thrust","description":"With the upper back supported on a bench, extend one leg and drive the hips up using the planted foot until full hip extension. It strengthens each glute independently and improves hip stability using only bodyweight.","descriptionAr":"اسند أعلى الظهر على مقعد ومد ساقًا واحدة، ثم ادفع الوركين للأعلى بالقدم المثبتة حتى الامتداد الكامل للورك. يقوي هذا التمرين كل عضلة ألوية على حدة ويحسن ثبات الورك باستخدام وزن الجسم فقط.","measurement":"reps","types":["Leg Day","Lower Body","Calisthenics"],"targets":[{"bodyTarget":"glutes","percentage":65},{"bodyTarget":"hamstrings","percentage":20},{"bodyTarget":"quadriceps","percentage":15}]},{"name":"Single Leg Hip Thrust (Dumbbell)","description":"With the upper back on a bench and a dumbbell on the hip of the working leg, drive through one foot to lift the hips to full extension. The single-leg setup with added load intensifies glute recruitment and exposes left-right differences.","descriptionAr":"اسند أعلى الظهر على مقعد وضع دمبل على ورك الساق العاملة، ثم ادفع بقدم واحدة لرفع الوركين حتى الامتداد الكامل. يزيد الأداء بساق واحدة مع الوزن الإضافي من تفعيل عضلة الألوية ويكشف الفروق بين الجانبين.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"glutes","percentage":65},{"bodyTarget":"hamstrings","percentage":20},{"bodyTarget":"quadriceps","percentage":15}]},{"name":"Single Leg Press (Machine)","description":"Seated in the leg press, place one foot on the platform and press the sled away until the knee is nearly extended. Pressing one leg at a time balances strength between legs and lets you load the quads and glutes with back support.","descriptionAr":"اجلس في جهاز ضغط الأرجل وضع قدمًا واحدة على المنصة، ثم ادفع الحامل بعيدًا حتى تقترب الركبة من الامتداد الكامل. يوازن الضغط بساق واحدة القوة بين الساقين ويتيح تحميل العضلة رباعية الرؤوس والألوية مع دعم الظهر.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"quadriceps","percentage":55},{"bodyTarget":"glutes","percentage":30},{"bodyTarget":"hamstrings","percentage":15}]},{"name":"Single Leg Romanian Deadlift (Barbell)","description":"Balancing on one leg with a barbell in hand, hinge at the hip and lower the bar while the free leg extends behind you, then drive back up. It loads the hamstrings and glutes through a deep stretch while training single-leg balance and hip stability.","descriptionAr":"اتزن على ساق واحدة ممسكًا بالبار، ثم انحنِ من الورك وأنزل البار بينما تمتد الساق الحرة خلفك، ثم عد للأعلى. يحمّل هذا التمرين العضلات الخلفية للفخذ والألوية عبر تمدد عميق بينما يدرب التوازن على ساق واحدة وثبات الورك.","measurement":"reps","types":["Leg Day","Lower Body","Functional"],"targets":[{"bodyTarget":"hamstrings","percentage":45},{"bodyTarget":"glutes","percentage":30},{"bodyTarget":"erector_spinae","percentage":15},{"bodyTarget":"balance","percentage":10}]},{"name":"Single Leg Romanian Deadlift (Dumbbell)","description":"Standing on one leg with a dumbbell in hand, hinge forward at the hip as the free leg extends behind for counterbalance, then return upright. It strengthens the hamstrings and glutes of the stance leg while sharpening balance and ankle-hip stability.","descriptionAr":"قف على ساق واحدة ممسكًا بالدمبل، ثم انحنِ للأمام من الورك بينما تمتد الساق الحرة خلفك للموازنة، ثم عد إلى الوقوف. يقوي هذا التمرين العضلات الخلفية للفخذ والألوية في ساق الارتكاز مع تحسين التوازن وثبات الكاحل والورك.","measurement":"reps","types":["Leg Day","Lower Body","Functional"],"targets":[{"bodyTarget":"hamstrings","percentage":45},{"bodyTarget":"glutes","percentage":30},{"bodyTarget":"erector_spinae","percentage":15},{"bodyTarget":"balance","percentage":10}]},{"name":"Single Leg Standing Calf Raise","description":"Standing on one foot, preferably on a step, rise onto the ball of the foot and lower the heel slowly through a full range. This bodyweight movement builds calf strength and endurance while training single-leg balance.","descriptionAr":"قف على قدم واحدة، ويفضل على حافة درجة، ثم ارتفع على مقدمة القدم وأنزل الكعب ببطء عبر مدى كامل. يبني هذا التمرين بوزن الجسم قوة عضلة الساق وتحملها بينما يدرب التوازن على ساق واحدة.","measurement":"reps","types":["Leg Day","Lower Body","Calisthenics"],"targets":[{"bodyTarget":"calves","percentage":90},{"bodyTarget":"balance","percentage":10}]},{"name":"Single Leg Standing Calf Raise (Barbell)","description":"With a barbell across the upper back, rise onto the ball of one foot as high as possible, then lower the heel slowly. Loading one calf at a time with the bar builds maximal calf strength and evens out size differences between legs.","descriptionAr":"ضع البار على أعلى الظهر وارتفع على مقدمة قدم واحدة إلى أقصى حد، ثم أنزل الكعب ببطء. يبني تحميل كل ساق على حدة بالبار قوة قصوى لعضلة الساق ويعالج فروق الحجم بين الساقين.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"calves","percentage":90},{"bodyTarget":"balance","percentage":10}]},{"name":"Single Leg Standing Calf Raise (Dumbbell)","description":"Holding a dumbbell on the working side, rise onto the ball of one foot, pause at the top, and lower the heel below the step for a stretch. It isolates each calf under load, developing size, strength, and ankle stability.","descriptionAr":"أمسك دمبل في جهة الساق العاملة وارتفع على مقدمة قدم واحدة، وتوقف في الأعلى ثم أنزل الكعب تحت مستوى الدرجة للتمدد. يعزل هذا التمرين كل ساق تحت الحمل، فيطور الحجم والقوة وثبات الكاحل.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"calves","percentage":90},{"bodyTarget":"balance","percentage":10}]},{"name":"Single Leg Standing Calf Raise (Machine)","description":"Under the machine's shoulder pads, rise onto the ball of one foot through a full range, then lower the heel for a deep stretch. The machine stabilizes the load so each calf can be trained heavily and evenly.","descriptionAr":"قف تحت وسادتي الكتف في الجهاز وارتفع على مقدمة قدم واحدة عبر مدى كامل، ثم أنزل الكعب لتمدد عميق. يثبّت الجهاز الحمل بحيث يمكن تدريب كل ساق بوزن ثقيل وبشكل متساوٍ.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"calves","percentage":90},{"bodyTarget":"balance","percentage":10}]},{"name":"Sissy Squat (Weighted)","description":"Holding a plate against the chest, lean the torso back and bend the knees forward over the toes while rising onto the balls of the feet. It places an extreme stretch on the quadriceps, especially the rectus femoris, making it a powerful quad isolation movement.","descriptionAr":"أمسك قرصًا أمام الصدر وأمل الجذع للخلف مع دفع الركبتين للأمام فوق أصابع القدمين والارتفاع على مقدمتي القدمين. يضع هذا التمرين تمددًا شديدًا على العضلة رباعية الرؤوس، خاصة المستقيمة الفخذية، مما يجعله تمرين عزل قويًا للفخذ الأمامي.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"quadriceps","percentage":80},{"bodyTarget":"hip_flexors","percentage":10},{"bodyTarget":"core_abs","percentage":10}]},{"name":"Sit Up","description":"Lying on your back with knees bent, curl the torso up until the chest approaches the thighs, then lower back down slowly. It is a classic bodyweight movement that strengthens the rectus abdominis and hip flexors and builds trunk endurance.","descriptionAr":"استلقِ على ظهرك مع ثني الركبتين، ثم ارفع الجذع حتى يقترب الصدر من الفخذين وعد للأسفل ببطء. إنه تمرين كلاسيكي بوزن الجسم يقوي عضلة البطن المستقيمة وثنيات الورك ويبني تحمل الجذع.","measurement":"reps","types":["Core","Calisthenics"],"targets":[{"bodyTarget":"core_abs","percentage":70},{"bodyTarget":"hip_flexors","percentage":30}]},{"name":"Sit Up (Weighted)","description":"Lying with knees bent and a weight held at the chest, curl the torso all the way up to a seated position, then lower with control. The external load lets the abdominals and hip flexors be progressively overloaded like any other muscle group.","descriptionAr":"استلقِ مع ثني الركبتين وحمل وزن أمام الصدر، ثم ارفع الجذع بالكامل حتى وضع الجلوس وأنزله بتحكم. يتيح الحمل الخارجي زيادة التحميل التدريجي على عضلات البطن وثنيات الورك مثل أي مجموعة عضلية أخرى.","measurement":"reps","types":["Core"],"targets":[{"bodyTarget":"core_abs","percentage":70},{"bodyTarget":"hip_flexors","percentage":30}]},{"name":"Skating","description":"Gliding on ice or inline skates propels the body with repeated sideways leg pushes. It provides low-impact cardiovascular conditioning while strengthening the quads, glutes, and hip stabilizers and improving balance.","descriptionAr":"يدفع التزلج على الجليد أو بالعجلات الجسم من خلال دفعات جانبية متكررة بالساقين. يوفر لياقة قلبية وعائية منخفضة التأثير على المفاصل بينما يقوي الفخذين والألوية ومثبتات الورك ويحسن التوازن.","measurement":"distance_duration","types":["Cardio"],"targets":[{"bodyTarget":"cardiovascular","percentage":50},{"bodyTarget":"quadriceps","percentage":20},{"bodyTarget":"glutes","percentage":15},{"bodyTarget":"endurance","percentage":15}]},{"name":"Skiing","description":"Skiing descends or traverses snow using sustained leg drive, edge control, and trunk stability. It delivers strong cardiovascular and muscular endurance work, with the quads and core absorbing terrain forces throughout.","descriptionAr":"يعتمد التزلج على الثلج على دفع مستمر بالساقين والتحكم في الحواف وثبات الجذع أثناء الانحدار أو التنقل. يوفر عملاً قويًا للتحمل القلبي والعضلي، حيث تمتص عضلات الفخذ والجذع قوى التضاريس طوال الوقت.","measurement":"distance_duration","types":["Cardio","Full Body"],"targets":[{"bodyTarget":"cardiovascular","percentage":50},{"bodyTarget":"quadriceps","percentage":25},{"bodyTarget":"endurance","percentage":15},{"bodyTarget":"core_abs","percentage":10}]},{"name":"Skullcrusher (Barbell)","description":"Lying on a bench, lower the barbell toward the forehead by bending only the elbows, then extend the arms back to lockout. Keeping the upper arms vertical isolates the triceps, making this a staple builder of arm size and pressing strength.","descriptionAr":"استلقِ على مقعد وأنزل البار نحو الجبهة بثني المرفقين فقط، ثم مد الذراعين حتى الامتداد الكامل. يؤدي إبقاء العضدين عموديين إلى عزل العضلة ثلاثية الرؤوس، مما يجعله تمرينًا أساسيًا لبناء حجم الذراع وقوة الدفع.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"triceps","percentage":85},{"bodyTarget":"forearms","percentage":15}]},{"name":"Skullcrusher (Dumbbell)","description":"Lying on a bench with a dumbbell in each hand, bend the elbows to lower the weights beside the head, then extend back up. The neutral dumbbell grip is easier on the wrists and elbows while fully isolating the triceps.","descriptionAr":"استلقِ على مقعد ممسكًا بدمبل في كل يد، ثم اثنِ المرفقين لإنزال الوزنين بجانب الرأس ومدهما للأعلى مجددًا. قبضة الدمبل المحايدة ألطف على الرسغين والمرفقين مع عزل كامل للعضلة ثلاثية الرؤوس.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"triceps","percentage":85},{"bodyTarget":"forearms","percentage":15}]},{"name":"Sled Pull","description":"Attached to a loaded sled by straps or rope, walk or row the sled toward you with powerful leg drive and back pulls. It builds full-body work capacity, grip, and posterior-chain strength with almost no eccentric stress, so recovery is fast.","descriptionAr":"اربط نفسك بزلاجة محملة بحبل أو أحزمة، ثم امشِ أو اسحب الزلاجة نحوك بدفع قوي من الساقين وسحبات من الظهر. يبني هذا التمرين قدرة عمل لكامل الجسم وقوة القبضة والسلسلة الخلفية مع إجهاد سلبي شبه معدوم، مما يسرع الاستشفاء.","measurement":"reps","types":["Full Body","Functional"],"targets":[{"bodyTarget":"quadriceps","percentage":30},{"bodyTarget":"glutes","percentage":30},{"bodyTarget":"upper_back","percentage":25},{"bodyTarget":"forearms","percentage":15}]},{"name":"Snowboarding","description":"Riding a snowboard down slopes demands continuous leg drive, edge transitions, and trunk control. It combines cardiovascular conditioning with strong isometric work for the quads and core, and sharpens balance and coordination.","descriptionAr":"يتطلب ركوب لوح التزلج على المنحدرات دفعًا مستمرًا بالساقين وانتقالات بين الحواف وتحكمًا في الجذع. يجمع بين اللياقة القلبية الوعائية وعمل ثابت قوي لعضلات الفخذ والجذع، ويصقل التوازن والتناسق.","measurement":"distance_duration","types":["Cardio"],"targets":[{"bodyTarget":"cardiovascular","percentage":45},{"bodyTarget":"quadriceps","percentage":25},{"bodyTarget":"core_abs","percentage":15},{"bodyTarget":"balance","percentage":15}]},{"name":"Spider Curl (Barbell)","description":"Lying chest-down on an incline bench with the arms hanging vertically, curl the barbell up without any shoulder movement. The strict vertical arm position removes momentum and keeps peak tension on the biceps' short head at the top.","descriptionAr":"استلقِ بصدرك على مقعد مائل مع تدلي الذراعين عموديًا، ثم ارفع البار دون أي حركة من الكتف. تزيل وضعية الذراع العمودية الصارمة الاندفاع وتحافظ على ذروة الشد على الرأس القصير للعضلة ذات الرأسين في الأعلى.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"biceps","percentage":80},{"bodyTarget":"forearms","percentage":20}]},{"name":"Spider Curl (Dumbbell)","description":"Chest-down on an incline bench with dumbbells hanging straight down, curl the weights up while the upper arms stay fixed. Dumbbells allow supination during the curl, maximizing the biceps contraction with zero body momentum.","descriptionAr":"استلقِ بصدرك على مقعد مائل مع تدلي الدمبل مباشرة للأسفل، ثم ارفع الوزنين مع بقاء العضدين ثابتين. تتيح الدمبل لف الرسغ أثناء الرفع، مما يزيد انقباض العضلة ذات الرأسين إلى أقصى حد دون أي اندفاع من الجسم.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"biceps","percentage":80},{"bodyTarget":"forearms","percentage":20}]},{"name":"Spiderman","description":"From a plank position, drive one knee up toward the same-side elbow, then return and alternate sides. It works the abs and obliques while opening the hips, blending core strength with dynamic mobility.","descriptionAr":"من وضعية البلانك، ادفع ركبة واحدة نحو المرفق في الجهة نفسها، ثم عد وبدّل الجانبين. يعمل هذا التمرين على عضلات البطن والعضلات المائلة مع فتح الوركين، جامعًا بين قوة الجذع والمرونة الديناميكية.","measurement":"reps","types":["Core","Calisthenics","Mobility"],"targets":[{"bodyTarget":"core_abs","percentage":50},{"bodyTarget":"obliques","percentage":25},{"bodyTarget":"hip_flexors","percentage":25}]},{"name":"Spinning","description":"On a stationary spin bike, pedal through intervals of varying resistance and cadence, often guided by music or a coach. It delivers high-calorie, low-impact cardiovascular training that builds leg endurance and aerobic capacity.","descriptionAr":"على دراجة ثابتة، بدّل بين فترات متفاوتة المقاومة وسرعة الدوران، غالبًا بإيقاع موسيقي أو بتوجيه مدرب. يوفر تدريبًا قلبيًا وعائيًا عالي الحرق ومنخفض التأثير على المفاصل يبني تحمل الساقين والسعة الهوائية.","measurement":"distance_duration","types":["Cardio","HIIT"],"targets":[{"bodyTarget":"cardiovascular","percentage":55},{"bodyTarget":"quadriceps","percentage":25},{"bodyTarget":"endurance","percentage":20}]},{"name":"Split Jerk","description":"From the front rack, dip and drive the barbell explosively overhead while splitting the feet into a lunge stance, then recover to standing. This Olympic lift develops total-body power, overhead strength, and precise footwork under load.","descriptionAr":"من وضعية الحمل الأمامي، انخفض قليلاً ثم ادفع البار بقوة انفجارية فوق الرأس مع فتح القدمين في وضعية الاندفاع، ثم عد إلى الوقوف. يطور هذا الرفع الأولمبي القدرة الانفجارية لكامل الجسم وقوة الرفع فوق الرأس ودقة حركة القدمين تحت الحمل.","measurement":"reps","types":["Olympic Lifting","Full Body"],"targets":[{"bodyTarget":"shoulders_anterior","percentage":30},{"bodyTarget":"quadriceps","percentage":30},{"bodyTarget":"triceps","percentage":20},{"bodyTarget":"glutes","percentage":20}]},{"name":"Split Squat (Dumbbell)","description":"With dumbbells at your sides and feet in a staggered stance, lower the back knee toward the floor and drive up through the front foot. It builds single-leg quad and glute strength while improving hip stability and balance between legs.","descriptionAr":"أمسك الدمبل على جانبي الجسم وضع القدمين في وضعية متباعدة أمامية وخلفية، ثم أنزل الركبة الخلفية نحو الأرض وادفع للأعلى بالقدم الأمامية. يبني هذا التمرين قوة الفخذ الأمامي والألوية لكل ساق على حدة ويحسن ثبات الورك والتوازن بين الساقين.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"quadriceps","percentage":50},{"bodyTarget":"glutes","percentage":30},{"bodyTarget":"hamstrings","percentage":20}]},{"name":"Squat (Band)","description":"A squat performed against the resistance of an elastic band, which increases tension as you stand up. It strengthens the quadriceps, glutes, and hamstrings with joint-friendly, accommodating resistance that is ideal for warm-ups or home training.","descriptionAr":"تمرين القرفصاء يُؤدى ضد مقاومة حزام مطاطي تزداد شدته كلما وقفت. يقوي العضلة الرباعية والألوية وأوتار الركبة بمقاومة متدرجة لطيفة على المفاصل، وهو مثالي للإحماء أو التدريب المنزلي.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"quadriceps","percentage":55},{"bodyTarget":"glutes","percentage":25},{"bodyTarget":"hamstrings","percentage":20}]},{"name":"Squat (Barbell)","description":"The barbell back squat loads a bar across the upper back while you sit down and drive back up through the whole lower body. It is a foundational strength lift that builds the quadriceps and glutes while the hamstrings and spinal erectors stabilize the trunk.","descriptionAr":"قرفصاء البار الخلفية تضع البار على أعلى الظهر بينما تنزل بالجسم ثم تدفع للوقوف بكامل الجزء السفلي. وهو رفعة قوة أساسية تبني العضلة الرباعية والألوية بينما تعمل أوتار الركبة وعضلات ناصبة الفقار على تثبيت الجذع.","measurement":"reps","types":["Leg Day","Lower Body","Powerlifting"],"targets":[{"bodyTarget":"quadriceps","percentage":50},{"bodyTarget":"glutes","percentage":25},{"bodyTarget":"hamstrings","percentage":15},{"bodyTarget":"erector_spinae","percentage":10}]},{"name":"Squat (Bodyweight)","description":"The bodyweight squat uses only your own weight to train the fundamental sit-and-stand movement pattern. It develops the quadriceps, glutes, and hamstrings and builds mobility and work capacity with no equipment.","descriptionAr":"قرفصاء وزن الجسم تعتمد على وزنك فقط لتدريب نمط الحركة الأساسي للجلوس والوقوف. تنمي العضلة الرباعية والألوية وأوتار الركبة وتحسن المرونة والقدرة على العمل دون أي معدات.","measurement":"reps","types":["Leg Day","Calisthenics","Lower Body"],"targets":[{"bodyTarget":"quadriceps","percentage":55},{"bodyTarget":"glutes","percentage":25},{"bodyTarget":"hamstrings","percentage":20}]},{"name":"Squat (Dumbbell)","description":"A squat performed while holding dumbbells at the sides or at the shoulders, adding load without a barbell. It strengthens the quadriceps, glutes, and hamstrings and is easy to learn and scale in any gym or at home.","descriptionAr":"قرفصاء تُؤدى مع حمل الدمبل على الجانبين أو عند الكتفين لإضافة حمل دون بار. تقوي العضلة الرباعية والألوية وأوتار الركبة، وهي سهلة التعلم والتدرج في أي صالة أو في المنزل.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"quadriceps","percentage":55},{"bodyTarget":"glutes","percentage":25},{"bodyTarget":"hamstrings","percentage":20}]},{"name":"Squat (Machine)","description":"The machine squat guides the movement along a fixed path, reducing the balance demand of a free-weight squat. It lets you focus effort on the quadriceps and glutes safely, making it useful for beginners and for high-fatigue sets.","descriptionAr":"قرفصاء الجهاز توجه الحركة على مسار ثابت مما يقلل الحاجة إلى التوازن مقارنة بالأوزان الحرة. تتيح تركيز الجهد على العضلة الرباعية والألوية بأمان، ما يجعلها مفيدة للمبتدئين وللمجموعات عالية الإجهاد.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"quadriceps","percentage":60},{"bodyTarget":"glutes","percentage":25},{"bodyTarget":"hamstrings","percentage":15}]},{"name":"Squat (Smith Machine)","description":"The Smith machine squat uses a bar fixed on vertical rails, providing stability so you can load the legs without balancing a free bar. It emphasizes the quadriceps and glutes and allows foot placement adjustments to shift emphasis.","descriptionAr":"قرفصاء جهاز سميث تستخدم بارًا مثبتًا على سكك عمودية يوفر ثباتًا يتيح تحميل الساقين دون موازنة بار حر. تركز على العضلة الرباعية والألوية وتسمح بتعديل وضع القدمين لتغيير التركيز العضلي.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"quadriceps","percentage":60},{"bodyTarget":"glutes","percentage":25},{"bodyTarget":"hamstrings","percentage":15}]},{"name":"Squat (Suspension)","description":"A squat performed while holding suspension straps, which assist balance and allow a deeper, more controlled range of motion. It trains the quadriceps, glutes, and hamstrings and is excellent for beginners learning squat depth and control.","descriptionAr":"قرفصاء تُؤدى أثناء الإمساك بأحزمة التعليق التي تساعد على التوازن وتسمح بمدى حركة أعمق وأكثر تحكمًا. تدرب العضلة الرباعية والألوية وأوتار الركبة، وهي ممتازة للمبتدئين لتعلم عمق القرفصاء والتحكم فيها.","measurement":"reps","types":["Leg Day","Calisthenics","Functional"],"targets":[{"bodyTarget":"quadriceps","percentage":55},{"bodyTarget":"glutes","percentage":25},{"bodyTarget":"hamstrings","percentage":20}]},{"name":"Squat Row","description":"The squat row combines a squat with a rowing pull, usually on suspension straps or a cable, in one continuous movement. It trains the legs and the pulling muscles of the back together, making it an efficient full-body conditioning exercise.","descriptionAr":"تمرين القرفصاء مع التجديف يجمع بين القرفصاء وسحبة التجديف، عادة على أحزمة التعليق أو الكابل، في حركة واحدة متصلة. يدرب الساقين وعضلات السحب في الظهر معًا، مما يجعله تمرينًا فعالًا للياقة الجسم بالكامل.","measurement":"reps","types":["Full Body","Functional"],"targets":[{"bodyTarget":"quadriceps","percentage":30},{"bodyTarget":"lats","percentage":30},{"bodyTarget":"glutes","percentage":20},{"bodyTarget":"biceps","percentage":20}]},{"name":"Stair Machine (Floors)","description":"Climbing on a stair machine, tracked by floors completed, provides continuous low-impact cardiovascular work. It raises the heart rate steadily while the quadriceps and glutes drive each step, improving aerobic fitness and leg endurance.","descriptionAr":"الصعود على جهاز الدرج، مقاسًا بعدد الطوابق المنجزة، يوفر عملًا قلبيًا وعائيًا متواصلًا منخفض التأثير. يرفع معدل ضربات القلب بثبات بينما تدفع العضلة الرباعية والألوية كل خطوة، مما يحسن اللياقة الهوائية وتحمل الساقين.","measurement":"distance_duration","types":["Cardio"],"targets":[{"bodyTarget":"cardiovascular","percentage":60},{"bodyTarget":"endurance","percentage":20},{"bodyTarget":"quadriceps","percentage":10},{"bodyTarget":"glutes","percentage":10}]},{"name":"Stair Machine (Steps)","description":"Climbing on a stair machine, tracked by the number of steps taken, delivers steady low-impact cardio. Each step loads the quadriceps and glutes, building aerobic capacity and lower-body endurance without pounding the joints.","descriptionAr":"الصعود على جهاز الدرج، مقاسًا بعدد الخطوات، يقدم تمرينًا قلبيًا ثابتًا منخفض التأثير. كل خطوة تُحمّل العضلة الرباعية والألوية، مما يبني السعة الهوائية وتحمل الجزء السفلي دون إجهاد المفاصل.","measurement":"distance_duration","types":["Cardio"],"targets":[{"bodyTarget":"cardiovascular","percentage":60},{"bodyTarget":"endurance","percentage":20},{"bodyTarget":"quadriceps","percentage":10},{"bodyTarget":"glutes","percentage":10}]},{"name":"Standing Cable Glute Kickbacks","description":"Standing with an ankle cuff attached to a low cable, you drive one leg straight back against the resistance. This isolates the gluteus maximus through hip extension, with the hamstrings assisting and the core stabilizing the pelvis.","descriptionAr":"واقفًا مع تثبيت سوار الكاحل بكابل منخفض، تدفع ساقًا واحدة إلى الخلف مباشرة ضد المقاومة. يعزل هذا التمرين العضلة الألوية الكبرى عبر بسط الورك، بمساعدة أوتار الركبة وتثبيت عضلات البطن للحوض.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"glutes","percentage":70},{"bodyTarget":"hamstrings","percentage":20},{"bodyTarget":"core_abs","percentage":10}]},{"name":"Standing Calf Raise (Barbell)","description":"With a barbell across the upper back, you rise onto the balls of the feet and lower under control. Performed with straight knees, it targets the gastrocnemius, building calf size and ankle strength while challenging balance.","descriptionAr":"مع وضع البار على أعلى الظهر، ترتفع على مقدمة القدمين ثم تنزل بتحكم. يُؤدى بركبتين مستقيمتين فيستهدف عضلة الساق التوأمية، مما يبني حجم بطة الساق وقوة الكاحل مع تحدي التوازن.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"calves","percentage":90},{"bodyTarget":"balance","percentage":10}]},{"name":"Standing Calf Raise (Dumbbell)","description":"Holding dumbbells at your sides, you press up onto the toes and lower slowly, often with the balls of the feet on a raised edge for a fuller stretch. It strengthens the gastrocnemius and improves ankle stability and balance.","descriptionAr":"ممسكًا بالدمبل على جانبيك، تدفع جسمك للأعلى على أطراف الأصابع ثم تنزل ببطء، وغالبًا ما توضع مقدمة القدمين على حافة مرتفعة لإطالة أكبر. يقوي العضلة التوأمية ويحسن ثبات الكاحل والتوازن.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"calves","percentage":90},{"bodyTarget":"balance","percentage":10}]},{"name":"Standing Calf Raise (Machine)","description":"On a standing calf machine with pads on the shoulders, you rise onto the toes through a full range of motion. The fixed path removes the balance demand so the gastrocnemius can be loaded heavily and safely.","descriptionAr":"على جهاز بطة الساق واقفًا مع وسائد على الكتفين، ترتفع على أطراف الأصابع بمدى حركة كامل. المسار الثابت يلغي الحاجة إلى التوازن مما يسمح بتحميل العضلة التوأمية بثقل وأمان.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"calves","percentage":95},{"bodyTarget":"hamstrings","percentage":5}]},{"name":"Standing Calf Raise (Smith)","description":"With the Smith machine bar across the upper back, you rise onto the balls of the feet and lower under control. The guided bar path stabilizes the load, letting you train the gastrocnemius heavily without balance limitations.","descriptionAr":"مع وضع بار جهاز سميث على أعلى الظهر، ترتفع على مقدمة القدمين ثم تنزل بتحكم. مسار البار الموجه يثبت الحمل، مما يتيح تدريب العضلة التوأمية بأوزان ثقيلة دون قيود التوازن.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"calves","percentage":95},{"bodyTarget":"hamstrings","percentage":5}]},{"name":"Standing Leg Curls","description":"Standing at a leg curl machine, you flex one knee to curl the pad up toward the glutes. It isolates the hamstrings one leg at a time, helping correct strength imbalances and protect the knee joint.","descriptionAr":"واقفًا عند جهاز ثني الساق، تثني ركبة واحدة لرفع الوسادة نحو الألوية. يعزل التمرين أوتار الركبة ساقًا واحدة في كل مرة، مما يساعد على تصحيح اختلالات القوة وحماية مفصل الركبة.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"hamstrings","percentage":80},{"bodyTarget":"calves","percentage":15},{"bodyTarget":"glutes","percentage":5}]},{"name":"Standing Military Press (Barbell)","description":"The standing military press drives a barbell from the shoulders to full lockout overhead with a strict, upright torso. It builds the anterior and lateral deltoids and triceps while the core braces hard to keep the trunk rigid.","descriptionAr":"الضغط العسكري واقفًا يدفع البار من الكتفين حتى الفرد الكامل فوق الرأس بجذع منتصب وصارم. يبني الرأس الأمامي والجانبي للكتف والعضلة ثلاثية الرؤوس بينما تشد عضلات البطن بقوة لإبقاء الجذع ثابتًا.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"shoulders_anterior","percentage":45},{"bodyTarget":"triceps","percentage":25},{"bodyTarget":"shoulders_lateral","percentage":20},{"bodyTarget":"core_abs","percentage":10}]},{"name":"Standing Y Raise (Cable)","description":"From a low cable, you raise straight arms up and out into a Y shape overhead. It strengthens the deltoids and lower trapezius through a long range, improving overhead mobility and shoulder-blade control.","descriptionAr":"من كابل منخفض، ترفع ذراعين مستقيمتين للأعلى وللخارج على شكل حرف Y فوق الرأس. يقوي العضلة الدالية والجزء السفلي من شبه المنحرفة عبر مدى طويل، مما يحسن حركة الرفع فوق الرأس والتحكم بلوح الكتف.","measurement":"reps","types":["Upper Body","Functional"],"targets":[{"bodyTarget":"shoulders_anterior","percentage":40},{"bodyTarget":"shoulders_lateral","percentage":25},{"bodyTarget":"traps","percentage":25},{"bodyTarget":"upper_back","percentage":10}]},{"name":"Step Up","description":"You step onto a box or bench with one leg and drive the body up until standing tall on top. This unilateral movement builds the quadriceps and glutes, improves single-leg balance, and carries over directly to climbing and daily activities.","descriptionAr":"تصعد على صندوق أو مقعد بساق واحدة وتدفع الجسم للأعلى حتى الوقوف الكامل فوقه. هذه الحركة الأحادية تبني العضلة الرباعية والألوية وتحسن التوازن على ساق واحدة وتنعكس مباشرة على صعود الدرج والأنشطة اليومية.","measurement":"reps","types":["Leg Day","Functional"],"targets":[{"bodyTarget":"quadriceps","percentage":50},{"bodyTarget":"glutes","percentage":30},{"bodyTarget":"hamstrings","percentage":15},{"bodyTarget":"calves","percentage":5}]},{"name":"Sternum Pull up (Gironda)","description":"The Gironda sternum pull-up has you lean far back and pull until the lower chest touches the bar, blending a pull-up with a row. This extended range works the lats through full contraction and hits the mid-back and rear delts harder than a standard pull-up.","descriptionAr":"عقلة جيروندا إلى عظمة القص تتطلب الميل بعيدًا إلى الخلف والسحب حتى يلمس أسفل الصدر البار، فتجمع بين العقلة والتجديف. هذا المدى الممتد يعمل على العضلة الظهرية العريضة بانقباض كامل ويستهدف منتصف الظهر والكتف الخلفي أكثر من العقلة العادية.","measurement":"reps","types":["Pull Day","Calisthenics","Upper Body"],"targets":[{"bodyTarget":"lats","percentage":50},{"bodyTarget":"upper_back","percentage":20},{"bodyTarget":"biceps","percentage":20},{"bodyTarget":"shoulders_posterior","percentage":10}]},{"name":"Straight Arm Lat Pulldown (Cable)","description":"With arms nearly straight, you pull a high cable bar down in an arc to the thighs using shoulder extension only. Removing the elbow bend takes the biceps out of the movement, isolating the lats and teaching a strong mind-muscle connection.","descriptionAr":"بذراعين شبه مستقيمتين، تسحب بار الكابل العلوي للأسفل في قوس حتى الفخذين باستخدام بسط الكتف فقط. إلغاء ثني المرفق يستبعد العضلة ذات الرأسين من الحركة، فيعزل الظهرية العريضة ويعزز الارتباط الذهني العضلي.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"lats","percentage":65},{"bodyTarget":"triceps","percentage":15},{"bodyTarget":"upper_back","percentage":10},{"bodyTarget":"core_abs","percentage":10}]},{"name":"Straight Leg Deadlift","description":"The straight leg deadlift hinges at the hips with minimal knee bend, lowering the weight along the legs until the hamstrings stretch fully. It builds the hamstrings and glutes through a long range while the spinal erectors hold the back flat.","descriptionAr":"الرفعة المميتة بساقين مستقيمتين تعتمد على الانحناء من الوركين مع ثني بسيط للركبتين، وإنزال الوزن بمحاذاة الساقين حتى تمتد أوتار الركبة بالكامل. تبني أوتار الركبة والألوية عبر مدى طويل بينما تحافظ عضلات ناصبة الفقار على استقامة الظهر.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"hamstrings","percentage":45},{"bodyTarget":"glutes","percentage":25},{"bodyTarget":"erector_spinae","percentage":20},{"bodyTarget":"lower_back","percentage":10}]},{"name":"Stretching","description":"Stretching lengthens muscles and connective tissue through held or gently repeated positions. Done regularly, it improves range of motion, eases post-training stiffness, and supports better movement quality.","descriptionAr":"تمارين الإطالة تعمل على تطويل العضلات والأنسجة الضامة عبر أوضاع ثابتة أو مكررة بلطف. ممارستها بانتظام تحسن مدى الحركة وتخفف التيبس بعد التدريب وتدعم جودة الحركة.","measurement":"reps","types":["Mobility"],"targets":[{"bodyTarget":"flexibility","percentage":85},{"bodyTarget":"balance","percentage":15}]},{"name":"Suitcase Carry (Dumbbell)","description":"You walk while carrying a heavy dumbbell in one hand, resisting the urge to lean toward the load. This trains the obliques and deep core to keep the trunk level, while the grip and traps work hard to hold the weight.","descriptionAr":"تمشي حاملًا دمبل ثقيلًا بيد واحدة مع مقاومة الميل نحو الحمل. يدرب هذا التمرين العضلات المائلة وعضلات الجذع العميقة على إبقاء الجذع مستويًا، بينما تعمل القبضة وشبه المنحرفة بجهد لحمل الوزن.","measurement":"reps","types":["Functional","Core","Full Body"],"targets":[{"bodyTarget":"obliques","percentage":30},{"bodyTarget":"core_deep","percentage":25},{"bodyTarget":"forearms","percentage":25},{"bodyTarget":"traps","percentage":20}]},{"name":"Sumo Squat","description":"The sumo squat is a wide-stance squat with the toes angled outward, lowering the hips straight down between the legs. It trains the quadriceps while placing extra demand on the inner-thigh adductors and glutes.","descriptionAr":"قرفصاء السومو هي قرفصاء بوقفة واسعة مع توجيه أصابع القدمين للخارج وإنزال الوركين عموديًا بين الساقين. تدرب العضلة الرباعية مع تحميل إضافي على العضلات الضامة للفخذ الداخلي والألوية.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"quadriceps","percentage":40},{"bodyTarget":"adductors","percentage":25},{"bodyTarget":"glutes","percentage":25},{"bodyTarget":"hamstrings","percentage":10}]},{"name":"Sumo Squat (Barbell)","description":"The barbell sumo squat uses a wide stance with toes turned out, sinking the hips between the legs. The wide position shifts more work onto the inner thighs and glutes alongside the quadriceps.","descriptionAr":"قرفصاء السومو بالبار تعتمد على وقفة واسعة مع توجيه أصابع القدمين للخارج وإنزال الوركين بين الساقين. الوضع الواسع ينقل جزءًا أكبر من العمل إلى الفخذين الداخليين والألوية إلى جانب العضلة الرباعية.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"quadriceps","percentage":40},{"bodyTarget":"adductors","percentage":25},{"bodyTarget":"glutes","percentage":25},{"bodyTarget":"hamstrings","percentage":10}]},{"name":"Sumo Squat (Dumbbell)","description":"Holding a dumbbell vertically between the legs, you squat with a wide stance and toes pointed out. It emphasizes the adductors and glutes together with the quadriceps and is a simple way to load the wide-stance pattern.","descriptionAr":"ممسكًا بدمبل عموديًا بين الساقين، تؤدي القرفصاء بوقفة واسعة وأصابع قدمين متجهة للخارج. يركز على العضلات الضامة والألوية مع العضلة الرباعية، وهو وسيلة بسيطة لتحميل نمط الوقفة الواسعة.","measurement":"reps","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"quadriceps","percentage":40},{"bodyTarget":"adductors","percentage":25},{"bodyTarget":"glutes","percentage":25},{"bodyTarget":"hamstrings","percentage":10}]},{"name":"Toe Touch","description":"Lying on your back with legs raised vertically, you crunch upward and reach your hands toward your toes. The short, focused range keeps constant tension on the upper abdominals with support from the hip flexors.","descriptionAr":"مستلقيًا على ظهرك مع رفع الساقين عموديًا، ترفع جذعك وتمد يديك نحو أصابع قدميك. المدى القصير والمركّز يحافظ على توتر مستمر في الجزء العلوي من عضلات البطن بمساندة عضلات ثني الورك.","measurement":"reps","types":["Core","Calisthenics"],"targets":[{"bodyTarget":"core_abs","percentage":70},{"bodyTarget":"hip_flexors","percentage":20},{"bodyTarget":"obliques","percentage":10}]},{"name":"Torso Rotation","description":"Torso rotation turns the upper body against resistance, on a machine, cable, or with a band, while the hips stay fixed. It strengthens the abdominals and obliques that control twisting, supporting sports movements and spine stability.","descriptionAr":"تدوير الجذع يلف الجزء العلوي من الجسم ضد مقاومة، على جهاز أو كابل أو بحزام مطاطي، بينما يبقى الوركان ثابتين. يقوي عضلات البطن والعضلات المائلة المسؤولة عن الالتفاف، مما يدعم الحركات الرياضية وثبات العمود الفقري.","measurement":"reps","types":["Core"],"targets":[{"bodyTarget":"core_abs","percentage":55},{"bodyTarget":"obliques","percentage":35},{"bodyTarget":"core_deep","percentage":10}]},{"name":"Treadmill","description":"Walking or running on a treadmill provides adjustable-speed, adjustable-incline cardiovascular training indoors. It improves heart and lung fitness and burns calories, with incline options adding extra work for the legs and glutes.","descriptionAr":"المشي أو الجري على جهاز المشي يوفر تدريبًا قلبيًا وعائيًا داخليًا بسرعة وميل قابلين للتعديل. يحسن لياقة القلب والرئتين ويحرق السعرات، مع خيارات الميل التي تضيف جهدًا إضافيًا للساقين والألوية.","measurement":"distance_duration","types":["Cardio"],"targets":[{"bodyTarget":"cardiovascular","percentage":60},{"bodyTarget":"endurance","percentage":25},{"bodyTarget":"quadriceps","percentage":10},{"bodyTarget":"calves","percentage":5}]},{"name":"Triceps Dip","description":"The dip lowers your body between parallel bars by bending the elbows, then presses back up to straight arms. Keeping the torso upright emphasizes the triceps, with the chest and front delts assisting the press.","descriptionAr":"تمرين الغطس ينزل الجسم بين قضيبين متوازيين بثني المرفقين ثم يدفعه للأعلى حتى استقامة الذراعين. إبقاء الجذع منتصبًا يركز الجهد على العضلة ثلاثية الرؤوس بمساندة الصدر ومقدمة الكتف.","measurement":"reps","types":["Push Day","Upper Body","Calisthenics"],"targets":[{"bodyTarget":"triceps","percentage":55},{"bodyTarget":"chest","percentage":25},{"bodyTarget":"shoulders_anterior","percentage":20}]},{"name":"Triceps Dip (Assisted)","description":"The assisted dip uses a machine platform or band to support part of your body weight while you lower and press back up between parallel bars. It lets you build the triceps, chest, and front delts progressively until full bodyweight dips are possible.","descriptionAr":"الغطس بمساعدة يستخدم منصة جهاز أو حزامًا مطاطيًا لدعم جزء من وزن الجسم بينما تنزل وتدفع للأعلى بين قضيبين متوازيين. يتيح بناء العضلة ثلاثية الرؤوس والصدر ومقدمة الكتف تدريجيًا حتى تتمكن من أداء الغطس بوزن الجسم كاملًا.","measurement":"reps","types":["Push Day","Upper Body","Calisthenics"],"targets":[{"bodyTarget":"triceps","percentage":55},{"bodyTarget":"chest","percentage":25},{"bodyTarget":"shoulders_anterior","percentage":20}]},{"name":"Triceps Dip (Weighted)","description":"The weighted dip adds a belt or dumbbell to the parallel-bar dip, lowering the body until the elbows pass ninety degrees and pressing back to lockout. The added load makes it one of the strongest builders of triceps and lower-chest pressing power.","descriptionAr":"الغطس بوزن إضافي يضيف حزام أثقال أو دمبل إلى الغطس على القضيبين المتوازيين، حيث تنزل حتى يتجاوز المرفقان تسعين درجة ثم تدفع حتى الفرد الكامل. الحمل الإضافي يجعله من أقوى تمارين بناء ثلاثية الرؤوس وقوة الدفع لأسفل الصدر.","measurement":"reps","types":["Push Day","Upper Body","Calisthenics"],"targets":[{"bodyTarget":"triceps","percentage":55},{"bodyTarget":"chest","percentage":25},{"bodyTarget":"shoulders_anterior","percentage":20}]},{"name":"Triceps Extension (Barbell)","description":"Lying or seated, you lower a barbell behind or toward the head by bending only the elbows, then extend back to straight arms. It isolates all three heads of the triceps, with the long head stretched hardest when the arms are overhead.","descriptionAr":"مستلقيًا أو جالسًا، تُنزل البار خلف الرأس أو نحوه بثني المرفقين فقط ثم تمد الذراعين حتى الاستقامة. يعزل التمرين رؤوس العضلة ثلاثية الرؤوس الثلاثة، ويُمدد الرأس الطويل بأقصى درجة عندما تكون الذراعان فوق الرأس.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"triceps","percentage":85},{"bodyTarget":"forearms","percentage":15}]},{"name":"Triceps Extension (Cable)","description":"Using a cable attachment, you extend the elbows from a bent position to full lockout while the upper arms stay still. The cable keeps tension on the triceps through the entire range, making it a smooth, joint-friendly isolation exercise.","descriptionAr":"باستخدام مقبض الكابل، تمد المرفقين من وضع الثني حتى الفرد الكامل مع بقاء العضدين ثابتين. يحافظ الكابل على التوتر في ثلاثية الرؤوس طوال المدى، مما يجعله تمرين عزل سلسًا ولطيفًا على المفاصل.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"triceps","percentage":85},{"bodyTarget":"forearms","percentage":15}]},{"name":"Triceps Extension (Dumbbell)","description":"Holding a dumbbell overhead or lying down, you bend the elbows to lower the weight, then extend the arms back to straight. The overhead position places a deep stretch on the long head of the triceps, driving growth across the whole muscle.","descriptionAr":"ممسكًا بدمبل فوق الرأس أو مستلقيًا، تثني المرفقين لإنزال الوزن ثم تمد الذراعين حتى الاستقامة. الوضع فوق الرأس يضع إطالة عميقة على الرأس الطويل لثلاثية الرؤوس، مما يحفز نمو العضلة بأكملها.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"triceps","percentage":85},{"bodyTarget":"forearms","percentage":15}]},{"name":"Triceps Extension (Machine)","description":"The machine triceps extension fixes the upper arms on a pad while you press the handles down or forward to straighten the elbows. The guided path isolates the triceps consistently, making it easy to train close to failure safely.","descriptionAr":"جهاز مد ثلاثية الرؤوس يثبت العضدين على وسادة بينما تدفع المقابض للأسفل أو للأمام حتى استقامة المرفقين. المسار الموجه يعزل ثلاثية الرؤوس بثبات، مما يسهل التدريب قرب الإجهاد الكامل بأمان.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"triceps","percentage":85},{"bodyTarget":"forearms","percentage":15}]},{"name":"Triceps Extension (Suspension)","description":"Leaning forward into suspension straps, you bend the elbows to lower the head toward the hands, then extend back to straight arms. Your body angle sets the difficulty, and the instability forces the core to brace while the triceps do the pressing.","descriptionAr":"مائلًا للأمام على أحزمة التعليق، تثني المرفقين لإنزال الرأس نحو اليدين ثم تمد الذراعين حتى الاستقامة. زاوية الجسم تحدد الصعوبة، وعدم الثبات يجبر عضلات الجذع على الشد بينما تقوم ثلاثية الرؤوس بالدفع.","measurement":"reps","types":["Push Day","Upper Body","Calisthenics"],"targets":[{"bodyTarget":"triceps","percentage":75},{"bodyTarget":"core_abs","percentage":15},{"bodyTarget":"shoulders_anterior","percentage":10}]},{"name":"Triceps Kickback (Cable)","description":"Hinged forward with the upper arm held parallel to the floor, you extend the elbow to push the cable handle straight back. The cable keeps resistance on the triceps even at full contraction, where dumbbell kickbacks lose tension.","descriptionAr":"منحنيًا للأمام مع تثبيت العضد موازيًا للأرض، تمد المرفق لدفع مقبض الكابل مباشرة إلى الخلف. يحافظ الكابل على المقاومة على ثلاثية الرؤوس حتى في الانقباض الكامل، حيث تفقد نسخة الدمبل توترها.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"triceps","percentage":85},{"bodyTarget":"shoulders_posterior","percentage":15}]},{"name":"Triceps Kickback (Dumbbell)","description":"Bent over with the upper arm locked against the torso, you extend the elbow to drive the dumbbell straight back. Peak tension arrives at full extension, making it a strict finisher that emphasizes the triceps' contracted position.","descriptionAr":"منحنيًا مع تثبيت العضد ملاصقًا للجذع، تمد المرفق لدفع الدمبل مباشرة إلى الخلف. تصل ذروة التوتر عند المد الكامل، مما يجعله تمرينًا ختاميًا صارمًا يركز على وضع الانقباض الكامل لثلاثية الرؤوس.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"triceps","percentage":85},{"bodyTarget":"shoulders_posterior","percentage":15}]},{"name":"Triceps Pressdown","description":"Standing at a high cable, you press the bar or handle down until the elbows lock out, keeping the upper arms pinned to your sides. It is a staple triceps isolation exercise that is easy to load progressively and gentle on the shoulders.","descriptionAr":"واقفًا عند كابل مرتفع، تضغط البار أو المقبض للأسفل حتى فرد المرفقين مع تثبيت العضدين على الجانبين. هو تمرين عزل أساسي لثلاثية الرؤوس، سهل التدرج في الحمل ولطيف على الكتفين.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"triceps","percentage":85},{"bodyTarget":"forearms","percentage":15}]},{"name":"Triceps Rope Pushdown","description":"Using a rope on a high cable, you push down and split the rope ends apart at the bottom of each rep. The rope allows a longer range and a harder peak contraction than a straight bar, targeting all three triceps heads.","descriptionAr":"باستخدام حبل على كابل مرتفع، تدفع للأسفل وتفصل طرفي الحبل عند نهاية كل تكرار. يتيح الحبل مدى أطول وانقباضًا ذروويًا أقوى من البار المستقيم، مستهدفًا رؤوس ثلاثية الرؤوس الثلاثة.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"triceps","percentage":85},{"bodyTarget":"forearms","percentage":15}]},{"name":"Upright Row (Barbell)","description":"The barbell upright row pulls the bar vertically from the thighs to chest height, leading with the elbows. It builds the lateral deltoids and trapezius; using a slightly wider grip and stopping near chest height keeps the shoulders comfortable.","descriptionAr":"التجديف العمودي بالبار يسحب البار عموديًا من الفخذين حتى مستوى الصدر مع قيادة الحركة بالمرفقين. يبني الرأس الجانبي للكتف والعضلة شبه المنحرفة؛ واستخدام قبضة أوسع قليلًا والتوقف قرب مستوى الصدر يحافظ على راحة الكتفين.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"shoulders_lateral","percentage":45},{"bodyTarget":"traps","percentage":35},{"bodyTarget":"biceps","percentage":20}]},{"name":"Upright Row (Cable)","description":"Standing over a low cable, you pull the bar or rope up along the body to chest height with elbows leading. The cable's constant tension works the lateral delts and traps smoothly through the entire range of motion.","descriptionAr":"واقفًا فوق كابل منخفض، تسحب البار أو الحبل للأعلى بمحاذاة الجسم حتى مستوى الصدر مع قيادة المرفقين. التوتر المستمر للكابل يعمل على الرأس الجانبي للكتف وشبه المنحرفة بسلاسة طوال مدى الحركة.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"shoulders_lateral","percentage":45},{"bodyTarget":"traps","percentage":35},{"bodyTarget":"biceps","percentage":20}]},{"name":"Upright Row (Dumbbell)","description":"Holding dumbbells in front of the thighs, you pull them up along the body to chest height, elbows rising first. The independent dumbbells let each arm find a comfortable path, reducing wrist and shoulder strain while training the side delts and traps.","descriptionAr":"ممسكًا بالدمبل أمام الفخذين، تسحبهما للأعلى بمحاذاة الجسم حتى مستوى الصدر مع ارتفاع المرفقين أولًا. استقلالية الدمبل تتيح لكل ذراع مسارًا مريحًا، مما يقلل إجهاد الرسغ والكتف أثناء تدريب الرأس الجانبي وشبه المنحرفة.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"shoulders_lateral","percentage":45},{"bodyTarget":"traps","percentage":35},{"bodyTarget":"biceps","percentage":20}]},{"name":"V Up","description":"From lying flat, you lift the straight legs and torso simultaneously so the body folds into a V, reaching hands toward the feet. It demands strong abdominals and hip flexors working together and trains the whole front of the core in one movement.","descriptionAr":"من وضع الاستلقاء، ترفع الساقين المستقيمتين والجذع معًا حتى ينطوي الجسم على شكل حرف V مع مد اليدين نحو القدمين. يتطلب عمل عضلات البطن وثنيات الورك معًا بقوة ويدرب كامل الجهة الأمامية للجذع في حركة واحدة.","measurement":"reps","types":["Core","Calisthenics"],"targets":[{"bodyTarget":"core_abs","percentage":60},{"bodyTarget":"hip_flexors","percentage":30},{"bodyTarget":"obliques","percentage":10}]},{"name":"Vertical Traction (Machine)","description":"The vertical traction machine replicates a pull-up on a guided lever, pulling the handles down toward the shoulders. It builds the lats and biceps with a stable, adjustable load, making vertical pulling accessible at any strength level.","descriptionAr":"جهاز السحب العمودي يحاكي العقلة عبر ذراع موجهة، حيث تسحب المقابض للأسفل نحو الكتفين. يبني الظهرية العريضة والعضلة ذات الرأسين بحمل ثابت وقابل للتعديل، مما يجعل السحب العمودي متاحًا لأي مستوى قوة.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"lats","percentage":55},{"bodyTarget":"biceps","percentage":20},{"bodyTarget":"upper_back","percentage":15},{"bodyTarget":"shoulders_posterior","percentage":10}]},{"name":"Waiter Curl (Dumbbell)","description":"Holding one dumbbell vertically by its top head with both palms, like a waiter carrying a tray, you curl it up while keeping the palms facing the ceiling. This position forces full supination throughout, emphasizing the biceps peak.","descriptionAr":"ممسكًا بدمبل واحد عموديًا من رأسه العلوي بكلتا الراحتين، كأنك نادل يحمل صينية، ترفعه بثني المرفقين مع إبقاء الراحتين نحو السقف. يفرض هذا الوضع استلقاءً كاملًا للساعد طوال الحركة، مما يركز على ذروة العضلة ذات الرأسين.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"biceps","percentage":70},{"bodyTarget":"forearms","percentage":20},{"bodyTarget":"shoulders_anterior","percentage":10}]},{"name":"Walking","description":"Walking is low-impact, steady-state cardio that nearly anyone can do daily. It supports heart health, aids recovery between hard sessions, and contributes meaningfully to daily energy expenditure.","descriptionAr":"المشي تمرين قلبي منخفض التأثير وثابت الوتيرة يمكن لأي شخص تقريبًا ممارسته يوميًا. يدعم صحة القلب ويساعد على الاستشفاء بين الحصص الشاقة ويسهم بشكل ملموس في استهلاك الطاقة اليومي.","measurement":"distance_duration","types":["Cardio"],"targets":[{"bodyTarget":"cardiovascular","percentage":55},{"bodyTarget":"endurance","percentage":25},{"bodyTarget":"calves","percentage":10},{"bodyTarget":"quadriceps","percentage":10}]},{"name":"Walking Lunge (Dumbbell)","description":"Holding dumbbells at your sides, you step forward into a lunge and push through to step directly into the next one. The continuous stepping builds the quadriceps and glutes while challenging single-leg balance and coordination.","descriptionAr":"ممسكًا بالدمبل على جانبيك، تخطو للأمام في وضع الطعن ثم تدفع لتنتقل مباشرة إلى الخطوة التالية. الخطوات المتواصلة تبني العضلة الرباعية والألوية مع تحدي التوازن والتناسق على ساق واحدة.","measurement":"reps","types":["Leg Day","Functional"],"targets":[{"bodyTarget":"quadriceps","percentage":45},{"bodyTarget":"glutes","percentage":30},{"bodyTarget":"hamstrings","percentage":15},{"bodyTarget":"calves","percentage":10}]},{"name":"Walking Lunge (Sandbag)","description":"Carrying a sandbag across the shoulders or in the arms, you lunge forward step after step. The shifting, unstable load adds heavy core and postural work to a movement that already builds the quadriceps and glutes.","descriptionAr":"حاملًا كيس رمل على الكتفين أو بين الذراعين، تؤدي الطعنات للأمام خطوة بعد خطوة. الحمل المتحرك وغير المستقر يضيف عملًا كبيرًا لعضلات الجذع والقوام إلى حركة تبني أصلًا العضلة الرباعية والألوية.","measurement":"reps","types":["Leg Day","Functional"],"targets":[{"bodyTarget":"quadriceps","percentage":40},{"bodyTarget":"glutes","percentage":30},{"bodyTarget":"hamstrings","percentage":15},{"bodyTarget":"core_abs","percentage":15}]},{"name":"Wall Ball","description":"The wall ball combines a front squat with an explosive overhead throw of a medicine ball to a target on the wall, catching it into the next rep. It links the legs and shoulders in one powerful rhythm and quickly becomes a demanding conditioning exercise.","descriptionAr":"تمرين كرة الحائط يجمع بين قرفصاء أمامية ورمية انفجارية بكرة طبية نحو هدف على الحائط، ثم التقاطها للتكرار التالي. يربط الساقين والكتفين في إيقاع قوي واحد ويتحول سريعًا إلى تمرين لياقة مُجهد.","measurement":"reps","types":["CrossFit / WOD","Full Body","HIIT"],"targets":[{"bodyTarget":"quadriceps","percentage":35},{"bodyTarget":"glutes","percentage":25},{"bodyTarget":"shoulders_anterior","percentage":25},{"bodyTarget":"cardiovascular","percentage":15}]},{"name":"Wall Sit","description":"You hold a seated position against a wall with knees at roughly ninety degrees, back flat against the surface. This isometric hold builds quadriceps endurance and mental grit with zero equipment and minimal joint stress.","descriptionAr":"تثبت وضعية الجلوس مستندًا إلى الحائط مع ثني الركبتين بزاوية تسعين درجة تقريبًا وظهر مستوٍ على السطح. هذا الثبات متساوي القياس يبني تحمل العضلة الرباعية والصلابة الذهنية دون معدات وبإجهاد ضئيل على المفاصل.","measurement":"time_hold","types":["Leg Day","Lower Body"],"targets":[{"bodyTarget":"quadriceps","percentage":65},{"bodyTarget":"glutes","percentage":25},{"bodyTarget":"core_abs","percentage":10}]},{"name":"Warm Up","description":"A warm-up gradually raises heart rate and body temperature through light cardio and dynamic movements before training. It prepares the muscles, joints, and nervous system for harder work and reduces injury risk.","descriptionAr":"الإحماء يرفع معدل ضربات القلب وحرارة الجسم تدريجيًا عبر تمارين قلبية خفيفة وحركات ديناميكية قبل التدريب. يهيئ العضلات والمفاصل والجهاز العصبي للجهد الأشد ويقلل خطر الإصابة.","measurement":"reps","types":["Mobility","Cardio"],"targets":[{"bodyTarget":"cardiovascular","percentage":40},{"bodyTarget":"flexibility","percentage":35},{"bodyTarget":"endurance","percentage":25}]},{"name":"Wide Pull Up","description":"The wide-grip pull-up takes the hands well outside shoulder width, pulling the chin over the bar. The wide grip shortens the biceps' contribution and shifts more of the work onto the lats, building back width.","descriptionAr":"العقلة بقبضة واسعة تضع اليدين أبعد بوضوح من عرض الكتفين مع سحب الذقن فوق البار. القبضة الواسعة تقلل مساهمة العضلة ذات الرأسين وتنقل جزءًا أكبر من العمل إلى الظهرية العريضة، مما يبني عرض الظهر.","measurement":"reps","types":["Pull Day","Calisthenics","Upper Body"],"targets":[{"bodyTarget":"lats","percentage":55},{"bodyTarget":"biceps","percentage":20},{"bodyTarget":"upper_back","percentage":15},{"bodyTarget":"shoulders_posterior","percentage":10}]},{"name":"Wide-Elbow Triceps Press (Dumbbell)","description":"Lying down with dumbbells, you lower the weights beside the head with elbows flared wide, then press back to straight arms. The flared position blends a triceps extension with a pressing motion, recruiting the chest and front delts as helpers.","descriptionAr":"مستلقيًا مع الدمبل، تُنزل الوزنين بجانب الرأس مع فتح المرفقين للخارج ثم تدفع حتى استقامة الذراعين. الوضع المفتوح يمزج بين مد ثلاثية الرؤوس وحركة الدفع، مستدعيًا الصدر ومقدمة الكتف للمساندة.","measurement":"reps","types":["Push Day","Upper Body"],"targets":[{"bodyTarget":"triceps","percentage":65},{"bodyTarget":"chest","percentage":20},{"bodyTarget":"shoulders_anterior","percentage":15}]},{"name":"Wrist Roller","description":"Holding a handle with a weight hanging from a rope, you roll the wrists to wind the rope up and then lower it back down. It is one of the most effective forearm and grip builders, with the shoulders working isometrically to hold the arms up.","descriptionAr":"ممسكًا بمقبض يتدلى منه وزن بحبل، تلف الرسغين للف الحبل صعودًا ثم إنزاله مجددًا. هو من أكثر تمارين بناء الساعدين والقبضة فعالية، بينما تعمل الكتفان بشكل متساوي القياس لإبقاء الذراعين مرفوعتين.","measurement":"reps","types":["Upper Body","Functional"],"targets":[{"bodyTarget":"forearms","percentage":80},{"bodyTarget":"shoulders_anterior","percentage":20}]},{"name":"Yoga","description":"Yoga moves the body through flowing sequences and held postures coordinated with breathing. Regular practice improves flexibility, balance, and deep core control while lowering stress and aiding recovery.","descriptionAr":"اليوغا تحرك الجسم عبر تسلسلات انسيابية وأوضاع ثابتة منسقة مع التنفس. الممارسة المنتظمة تحسن المرونة والتوازن والتحكم العميق بعضلات الجذع مع خفض التوتر والمساعدة على الاستشفاء.","measurement":"reps","types":["Mobility"],"targets":[{"bodyTarget":"flexibility","percentage":45},{"bodyTarget":"balance","percentage":30},{"bodyTarget":"core_deep","percentage":25}]},{"name":"Zercher Squat","description":"The Zercher squat cradles the barbell in the crooks of the elbows against the torso while you squat. The front-loaded position keeps the torso upright and forces the core and upper back to work intensely alongside the quadriceps and glutes.","descriptionAr":"قرفصاء زيرتشر تحمل البار في ثنية المرفقين ملاصقًا للجذع أثناء أداء القرفصاء. الحمل الأمامي يبقي الجذع منتصبًا ويجبر عضلات الجذع وأعلى الظهر على العمل بشدة إلى جانب العضلة الرباعية والألوية.","measurement":"reps","types":["Leg Day","Functional"],"targets":[{"bodyTarget":"quadriceps","percentage":40},{"bodyTarget":"glutes","percentage":25},{"bodyTarget":"erector_spinae","percentage":20},{"bodyTarget":"core_abs","percentage":15}]},{"name":"Zottman Curl (Dumbbell)","description":"The Zottman curl lifts the dumbbells with palms up, then rotates the wrists at the top to lower with palms down. Curling concentrically works the biceps while the pronated lowering phase heavily loads the forearm extensors and brachioradialis.","descriptionAr":"تمرين زوتمان يرفع الدمبل والراحتان للأعلى ثم يدير الرسغين عند القمة للنزول والراحتان للأسفل. مرحلة الرفع تعمل على العضلة ذات الرأسين بينما مرحلة النزول بالكب تُحمّل بشدة عضلات الساعد الباسطة والعضلة العضدية الكعبرية.","measurement":"reps","types":["Pull Day","Upper Body"],"targets":[{"bodyTarget":"biceps","percentage":55},{"bodyTarget":"forearms","percentage":35},{"bodyTarget":"shoulders_anterior","percentage":10}]}];
